-- KJV batch 8 (blocks 176-200 of 349)
-- Run this in Supabase Dashboard SQL Editor

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 1, E'The proverbs of Solomon the son of David, king of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 2, E'To know wisdom and instruction; to perceive the words of understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 3, E'To receive the instruction of wisdom, justice, and judgment, and equity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 4, E'To give subtilty to the simple, to the young man knowledge and discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 5, E'A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 6, E'To understand a proverb, and the interpretation; the words of the wise, and their dark sayings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 7, E'The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 8, E'My son, hear the instruction of thy father, and forsake not the law of thy mother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 9, E'For they shall be an ornament of grace unto thy head, and chains about thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 10, E'My son, if sinners entice thee, consent thou not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 11, E'If they say, Come with us, let us lay wait for blood, let us lurk privily for the innocent without cause:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 12, E'Let us swallow them up alive as the grave; and whole, as those that go down into the pit:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 13, E'We shall find all precious substance, we shall fill our houses with spoil:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 14, E'Cast in thy lot among us; let us all have one purse:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 15, E'My son, walk not thou in the way with them; refrain thy foot from their path:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 16, E'For their feet run to evil, and make haste to shed blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 17, E'Surely in vain the net is spread in the sight of any bird.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 18, E'And they lay wait for their own blood; they lurk privily for their own lives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 19, E'So are the ways of every one that is greedy of gain; which taketh away the life of the owners thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 20, E'Wisdom crieth without; she uttereth her voice in the streets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 21, E'She crieth in the chief place of concourse, in the openings of the gates: in the city she uttereth her words, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 22, E'How long, ye simple ones, will ye love simplicity? and the scorners delight in their scorning, and fools hate knowledge?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 23, E'Turn you at my reproof: behold, I will pour out my spirit unto you, I will make known my words unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 24, E'Because I have called, and ye refused; I have stretched out my hand, and no man regarded;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 25, E'But ye have set at nought all my counsel, and would none of my reproof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 26, E'I also will laugh at your calamity; I will mock when your fear cometh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 27, E'When your fear cometh as desolation, and your destruction cometh as a whirlwind; when distress and anguish cometh upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 28, E'Then shall they call upon me, but I will not answer; they shall seek me early, but they shall not find me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 29, E'For that they hated knowledge, and did not choose the fear of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 30, E'They would none of my counsel: they despised all my reproof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 31, E'Therefore shall they eat of the fruit of their own way, and be filled with their own devices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 32, E'For the turning away of the simple shall slay them, and the prosperity of fools shall destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 33, E'But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 1, E'My son, if thou wilt receive my words, and hide my commandments with thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 2, E'So that thou incline thine ear unto wisdom, and apply thine heart to understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 3, E'Yea, if thou criest after knowledge, and liftest up thy voice for understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 4, E'If thou seekest her as silver, and searchest for her as for hid treasures;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 5, E'Then shalt thou understand the fear of the LORD, and find the knowledge of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 6, E'For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 7, E'He layeth up sound wisdom for the righteous: he is a buckler to them that walk uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 8, E'He keepeth the paths of judgment, and preserveth the way of his saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 9, E'Then shalt thou understand righteousness, and judgment, and equity; yea, every good path.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 10, E'When wisdom entereth into thine heart, and knowledge is pleasant unto thy soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 11, E'Discretion shall preserve thee, understanding shall keep thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 12, E'To deliver thee from the way of the evil man, from the man that speaketh froward things;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 13, E'Who leave the paths of uprightness, to walk in the ways of darkness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 14, E'Who rejoice to do evil, and delight in the frowardness of the wicked;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 15, E'Whose ways are crooked, and they froward in their paths:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 16, E'To deliver thee from the strange woman, even from the stranger which flattereth with her words;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 17, E'Which forsaketh the guide of her youth, and forgetteth the covenant of her God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 18, E'For her house inclineth unto death, and her paths unto the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 19, E'None that go unto her return again, neither take they hold of the paths of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 20, E'That thou mayest walk in the way of good men, and keep the paths of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 21, E'For the upright shall dwell in the land, and the perfect shall remain in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 22, E'But the wicked shall be cut off from the earth, and the transgressors shall be rooted out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 1, E'My son, forget not my law; but let thine heart keep my commandments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 2, E'For length of days, and long life, and peace, shall they add to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 3, E'Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 4, E'So shalt thou find favour and good understanding in the sight of God and man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 5, E'Trust in the LORD with all thine heart; and lean not unto thine own understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 6, E'In all thy ways acknowledge him, and he shall direct thy paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 7, E'Be not wise in thine own eyes: fear the LORD, and depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 8, E'It shall be health to thy navel, and marrow to thy bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 9, E'Honour the LORD with thy substance, and with the firstfruits of all thine increase:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 10, E'So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 11, E'My son, despise not the chastening of the LORD; neither be weary of his correction:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 12, E'For whom the LORD loveth he correcteth; even as a father the son in whom he delighteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 13, E'Happy is the man that findeth wisdom, and the man that getteth understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 14, E'For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 15, E'She is more precious than rubies: and all the things thou canst desire are not to be compared unto her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 16, E'Length of days is in her right hand; and in her left hand riches and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 17, E'Her ways are ways of pleasantness, and all her paths are peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 18, E'She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 19, E'The LORD by wisdom hath founded the earth; by understanding hath he established the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 20, E'By his knowledge the depths are broken up, and the clouds drop down the dew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 21, E'My son, let not them depart from thine eyes: keep sound wisdom and discretion:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 22, E'So shall they be life unto thy soul, and grace to thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 23, E'Then shalt thou walk in thy way safely, and thy foot shall not stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 24, E'When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 25, E'Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 26, E'For the LORD shall be thy confidence, and shall keep thy foot from being taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 27, E'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 28, E'Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 29, E'Devise not evil against thy neighbour, seeing he dwelleth securely by thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 30, E'Strive not with a man without cause, if he have done thee no harm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 31, E'Envy thou not the oppressor, and choose none of his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 32, E'For the froward is abomination to the LORD: but his secret is with the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 33, E'The curse of the LORD is in the house of the wicked: but he blesseth the habitation of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 34, E'Surely he scorneth the scorners: but he giveth grace unto the lowly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 35, E'The wise shall inherit glory: but shame shall be the promotion of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 1, E'Hear, ye children, the instruction of a father, and attend to know understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 2, E'For I give you good doctrine, forsake ye not my law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 3, E'For I was my father’s son, tender and only beloved in the sight of my mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 4, E'He taught me also, and said unto me, Let thine heart retain my words: keep my commandments, and live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 5, E'Get wisdom, get understanding: forget it not; neither decline from the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 6, E'Forsake her not, and she shall preserve thee: love her, and she shall keep thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 7, E'Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 8, E'Exalt her, and she shall promote thee: she shall bring thee to honour, when thou dost embrace her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 9, E'She shall give to thine head an ornament of grace: a crown of glory shall she deliver to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 10, E'Hear, O my son, and receive my sayings; and the years of thy life shall be many.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 11, E'I have taught thee in the way of wisdom; I have led thee in right paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 12, E'When thou goest, thy steps shall not be straitened; and when thou runnest, thou shalt not stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 13, E'Take fast hold of instruction; let her not go: keep her; for she is thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 14, E'Enter not into the path of the wicked, and go not in the way of evil men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 15, E'Avoid it, pass not by it, turn from it, and pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 16, E'For they sleep not, except they have done mischief; and their sleep is taken away, unless they cause some to fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 17, E'For they eat the bread of wickedness, and drink the wine of violence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 18, E'But the path of the just is as the shining light, that shineth more and more unto the perfect day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 19, E'The way of the wicked is as darkness: they know not at what they stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 20, E'My son, attend to my words; incline thine ear unto my sayings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 21, E'Let them not depart from thine eyes; keep them in the midst of thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 22, E'For they are life unto those that find them, and health to all their flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 23, E'Keep thy heart with all diligence; for out of it are the issues of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 24, E'Put away from thee a froward mouth, and perverse lips put far from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 25, E'Let thine eyes look right on, and let thine eyelids look straight before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 26, E'Ponder the path of thy feet, and let all thy ways be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 27, E'Turn not to the right hand nor to the left: remove thy foot from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 1, E'My son, attend unto my wisdom, and bow thine ear to my understanding:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 2, E'That thou mayest regard discretion, and that thy lips may keep knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 3, E'For the lips of a strange woman drop as an honeycomb, and her mouth is smoother than oil:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 4, E'But her end is bitter as wormwood, sharp as a two-edged sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 5, E'Her feet go down to death; her steps take hold on hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 6, E'Lest thou shouldest ponder the path of life, her ways are moveable, that thou canst not know them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 7, E'Hear me now therefore, O ye children, and depart not from the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 8, E'Remove thy way far from her, and come not nigh the door of her house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 9, E'Lest thou give thine honour unto others, and thy years unto the cruel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 10, E'Lest strangers be filled with thy wealth; and thy labours be in the house of a stranger;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 11, E'And thou mourn at the last, when thy flesh and thy body are consumed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 12, E'And say, How have I hated instruction, and my heart despised reproof;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 13, E'And have not obeyed the voice of my teachers, nor inclined mine ear to them that instructed me!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 14, E'I was almost in all evil in the midst of the congregation and assembly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 15, E'Drink waters out of thine own cistern, and running waters out of thine own well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 16, E'Let thy fountains be dispersed abroad, and rivers of waters in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 17, E'Let them be only thine own, and not strangers’ with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 18, E'Let thy fountain be blessed: and rejoice with the wife of thy youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 19, E'Let her be as the loving hind and pleasant roe; let her breasts satisfy thee at all times; and be thou ravished always with her love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 20, E'And why wilt thou, my son, be ravished with a strange woman, and embrace the bosom of a stranger?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 21, E'For the ways of man are before the eyes of the LORD, and he pondereth all his goings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 22, E'His own iniquities shall take the wicked himself, and he shall be holden with the cords of his sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 23, E'He shall die without instruction; and in the greatness of his folly he shall go astray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 1, E'My son, if thou be surety for thy friend, if thou hast stricken thy hand with a stranger,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 2, E'Thou art snared with the words of thy mouth, thou art taken with the words of thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 3, E'Do this now, my son, and deliver thyself, when thou art come into the hand of thy friend; go, humble thyself, and make sure thy friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 4, E'Give not sleep to thine eyes, nor slumber to thine eyelids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 5, E'Deliver thyself as a roe from the hand of the hunter, and as a bird from the hand of the fowler.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 6, E'Go to the ant, thou sluggard; consider her ways, and be wise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 7, E'Which having no guide, overseer, or ruler,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 8, E'Provideth her meat in the summer, and gathereth her food in the harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 9, E'How long wilt thou sleep, O sluggard? when wilt thou arise out of thy sleep?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 10, E'Yet a little sleep, a little slumber, a little folding of the hands to sleep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 11, E'So shall thy poverty come as one that travelleth, and thy want as an armed man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 12, E'A naughty person, a wicked man, walketh with a froward mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 13, E'He winketh with his eyes, he speaketh with his feet, he teacheth with his fingers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 14, E'Frowardness is in his heart, he deviseth mischief continually; he soweth discord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 15, E'Therefore shall his calamity come suddenly; suddenly shall he be broken without remedy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 16, E'These six things doth the LORD hate: yea, seven are an abomination unto him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 17, E'A proud look, a lying tongue, and hands that shed innocent blood,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 18, E'An heart that deviseth wicked imaginations, feet that be swift in running to mischief,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 19, E'A false witness that speaketh lies, and he that soweth discord among brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 20, E'My son, keep thy father’s commandment, and forsake not the law of thy mother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 21, E'Bind them continually upon thine heart, and tie them about thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 22, E'When thou goest, it shall lead thee; when thou sleepest, it shall keep thee; and when thou awakest, it shall talk with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 23, E'For the commandment is a lamp; and the law is light; and reproofs of instruction are the way of life:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 24, E'To keep thee from the evil woman, from the flattery of the tongue of a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 25, E'Lust not after her beauty in thine heart; neither let her take thee with her eyelids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 26, E'For by means of a whorish woman a man is brought to a piece of bread: and the adulteress will hunt for the precious life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 27, E'Can a man take fire in his bosom, and his clothes not be burned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 28, E'Can one go upon hot coals, and his feet not be burned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 29, E'So he that goeth in to his neighbour’s wife; whosoever toucheth her shall not be innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 30, E'Men do not despise a thief, if he steal to satisfy his soul when he is hungry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 31, E'But if he be found, he shall restore sevenfold; he shall give all the substance of his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 32, E'But whoso committeth adultery with a woman lacketh understanding: he that doeth it destroyeth his own soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 33, E'A wound and dishonour shall he get; and his reproach shall not be wiped away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 34, E'For jealousy is the rage of a man: therefore he will not spare in the day of vengeance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 35, E'He will not regard any ransom; neither will he rest content, though thou givest many gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 1, E'My son, keep my words, and lay up my commandments with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 2, E'Keep my commandments, and live; and my law as the apple of thine eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 3, E'Bind them upon thy fingers, write them upon the table of thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 4, E'Say unto wisdom, Thou art my sister; and call understanding thy kinswoman:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 5, E'That they may keep thee from the strange woman, from the stranger which flattereth with her words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 6, E'For at the window of my house I looked through my casement,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 7, E'And beheld among the simple ones, I discerned among the youths, a young man void of understanding,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 8, E'Passing through the street near her corner; and he went the way to her house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 9, E'In the twilight, in the evening, in the black and dark night:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 10, E'And, behold, there met him a woman with the attire of an harlot, and subtil of heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 11, E'(She is loud and stubborn; her feet abide not in her house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 12, E'Now is she without, now in the streets, and lieth in wait at every corner.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 13, E'So she caught him, and kissed him, and with an impudent face said unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 14, E'I have peace offerings with me; this day have I payed my vows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 15, E'Therefore came I forth to meet thee, diligently to seek thy face, and I have found thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 16, E'I have decked my bed with coverings of tapestry, with carved works, with fine linen of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 17, E'I have perfumed my bed with myrrh, aloes, and cinnamon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 18, E'Come, let us take our fill of love until the morning: let us solace ourselves with loves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 19, E'For the goodman is not at home, he is gone a long journey:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 20, E'He hath taken a bag of money with him, and will come home at the day appointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 21, E'With her much fair speech she caused him to yield, with the flattering of her lips she forced him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 22, E'He goeth after her straightway, as an ox goeth to the slaughter, or as a fool to the correction of the stocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 23, E'Till a dart strike through his liver; as a bird hasteth to the snare, and knoweth not that it is for his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 24, E'Hearken unto me now therefore, O ye children, and attend to the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 25, E'Let not thine heart decline to her ways, go not astray in her paths.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 26, E'For she hath cast down many wounded: yea, many strong men have been slain by her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 27, E'Her house is the way to hell, going down to the chambers of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 1, E'Doth not wisdom cry? and understanding put forth her voice?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 2, E'She standeth in the top of high places, by the way in the places of the paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 3, E'She crieth at the gates, at the entry of the city, at the coming in at the doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 4, E'Unto you, O men, I call; and my voice is to the sons of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 5, E'O ye simple, understand wisdom: and, ye fools, be ye of an understanding heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 6, E'Hear; for I will speak of excellent things; and the opening of my lips shall be right things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 7, E'For my mouth shall speak truth; and wickedness is an abomination to my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 8, E'All the words of my mouth are in righteousness; there is nothing froward or perverse in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 9, E'They are all plain to him that understandeth, and right to them that find knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 10, E'Receive my instruction, and not silver; and knowledge rather than choice gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 11, E'For wisdom is better than rubies; and all the things that may be desired are not to be compared to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 12, E'I wisdom dwell with prudence, and find out knowledge of witty inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 13, E'The fear of the LORD is to hate evil: pride, and arrogancy, and the evil way, and the froward mouth, do I hate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 14, E'Counsel is mine, and sound wisdom: I am understanding; I have strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 15, E'By me kings reign, and princes decree justice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 16, E'By me princes rule, and nobles, even all the judges of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 17, E'I love them that love me; and those that seek me early shall find me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 18, E'Riches and honour are with me; yea, durable riches and righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 19, E'My fruit is better than gold, yea, than fine gold; and my revenue than choice silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 20, E'I lead in the way of righteousness, in the midst of the paths of judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 21, E'That I may cause those that love me to inherit substance; and I will fill their treasures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 22, E'The LORD possessed me in the beginning of his way, before his works of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 23, E'I was set up from everlasting, from the beginning, or ever the earth was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 24, E'When there were no depths, I was brought forth; when there were no fountains abounding with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 25, E'Before the mountains were settled, before the hills was I brought forth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 26, E'While as yet he had not made the earth, nor the fields, nor the highest part of the dust of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 27, E'When he prepared the heavens, I was there: when he set a compass upon the face of the depth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 28, E'When he established the clouds above: when he strengthened the fountains of the deep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 29, E'When he gave to the sea his decree, that the waters should not pass his commandment: when he appointed the foundations of the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 30, E'Then I was by him, as one brought up with him: and I was daily his delight, rejoicing always before him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 31, E'Rejoicing in the habitable part of his earth; and my delights were with the sons of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 32, E'Now therefore hearken unto me, O ye children: for blessed are they that keep my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 33, E'Hear instruction, and be wise, and refuse it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 34, E'Blessed is the man that heareth me, watching daily at my gates, waiting at the posts of my doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 35, E'For whoso findeth me findeth life, and shall obtain favour of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 36, E'But he that sinneth against me wrongeth his own soul: all they that hate me love death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 1, E'Wisdom hath builded her house, she hath hewn out her seven pillars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 2, E'She hath killed her beasts; she hath mingled her wine; she hath also furnished her table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 3, E'She hath sent forth her maidens: she crieth upon the highest places of the city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 4, E'Whoso is simple, let him turn in hither: as for him that wanteth understanding, she saith to him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 5, E'Come, eat of my bread, and drink of the wine which I have mingled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 6, E'Forsake the foolish, and live; and go in the way of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 7, E'He that reproveth a scorner getteth to himself shame: and he that rebuketh a wicked man getteth himself a blot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 8, E'Reprove not a scorner, lest he hate thee: rebuke a wise man, and he will love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 9, E'Give instruction to a wise man, and he will be yet wiser: teach a just man, and he will increase in learning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 10, E'The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 11, E'For by me thy days shall be multiplied, and the years of thy life shall be increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 12, E'If thou be wise, thou shalt be wise for thyself: but if thou scornest, thou alone shalt bear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 13, E'A foolish woman is clamorous: she is simple, and knoweth nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 14, E'For she sitteth at the door of her house, on a seat in the high places of the city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 15, E'To call passengers who go right on their ways:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 16, E'Whoso is simple, let him turn in hither: and as for him that wanteth understanding, she saith to him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 17, E'Stolen waters are sweet, and bread eaten in secret is pleasant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 18, E'But he knoweth not that the dead are there; and that her guests are in the depths of hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 1, E'The proverbs of Solomon. A wise son maketh a glad father: but a foolish son is the heaviness of his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 2, E'Treasures of wickedness profit nothing: but righteousness delivereth from death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 3, E'The LORD will not suffer the soul of the righteous to famish: but he casteth away the substance of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 4, E'He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 5, E'He that gathereth in summer is a wise son: but he that sleepeth in harvest is a son that causeth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 6, E'Blessings are upon the head of the just: but violence covereth the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 7, E'The memory of the just is blessed: but the name of the wicked shall rot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 8, E'The wise in heart will receive commandments: but a prating fool shall fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 9, E'He that walketh uprightly walketh surely: but he that perverteth his ways shall be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 10, E'He that winketh with the eye causeth sorrow: but a prating fool shall fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 11, E'The mouth of a righteous man is a well of life: but violence covereth the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 12, E'Hatred stirreth up strifes: but love covereth all sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 13, E'In the lips of him that hath understanding wisdom is found: but a rod is for the back of him that is void of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 14, E'Wise men lay up knowledge: but the mouth of the foolish is near destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 15, E'The rich man’s wealth is his strong city: the destruction of the poor is their poverty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 16, E'The labour of the righteous tendeth to life: the fruit of the wicked to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 17, E'He is in the way of life that keepeth instruction: but he that refuseth reproof erreth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 18, E'He that hideth hatred with lying lips, and he that uttereth a slander, is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 19, E'In the multitude of words there wanteth not sin: but he that refraineth his lips is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 20, E'The tongue of the just is as choice silver: the heart of the wicked is little worth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 21, E'The lips of the righteous feed many: but fools die for want of wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 22, E'The blessing of the LORD, it maketh rich, and he addeth no sorrow with it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 23, E'It is as sport to a fool to do mischief: but a man of understanding hath wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 24, E'The fear of the wicked, it shall come upon him: but the desire of the righteous shall be granted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 25, E'As the whirlwind passeth, so is the wicked no more: but the righteous is an everlasting foundation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 26, E'As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to them that send him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 27, E'The fear of the LORD prolongeth days: but the years of the wicked shall be shortened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 28, E'The hope of the righteous shall be gladness: but the expectation of the wicked shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 29, E'The way of the LORD is strength to the upright: but destruction shall be to the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 30, E'The righteous shall never be removed: but the wicked shall not inhabit the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 31, E'The mouth of the just bringeth forth wisdom: but the froward tongue shall be cut out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 32, E'The lips of the righteous know what is acceptable: but the mouth of the wicked speaketh frowardness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 1, E'A false balance is abomination to the LORD: but a just weight is his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 2, E'When pride cometh, then cometh shame: but with the lowly is wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 3, E'The integrity of the upright shall guide them: but the perverseness of transgressors shall destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 4, E'Riches profit not in the day of wrath: but righteousness delivereth from death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 5, E'The righteousness of the perfect shall direct his way: but the wicked shall fall by his own wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 6, E'The righteousness of the upright shall deliver them: but transgressors shall be taken in their own naughtiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 7, E'When a wicked man dieth, his expectation shall perish: and the hope of unjust men perisheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 8, E'The righteous is delivered out of trouble, and the wicked cometh in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 9, E'An hypocrite with his mouth destroyeth his neighbour: but through knowledge shall the just be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 10, E'When it goeth well with the righteous, the city rejoiceth: and when the wicked perish, there is shouting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 11, E'By the blessing of the upright the city is exalted: but it is overthrown by the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 12, E'He that is void of wisdom despiseth his neighbour: but a man of understanding holdeth his peace.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 13, E'A talebearer revealeth secrets: but he that is of a faithful spirit concealeth the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 14, E'Where no counsel is, the people fall: but in the multitude of counsellors there is safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 15, E'He that is surety for a stranger shall smart for it: and he that hateth suretiship is sure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 16, E'A gracious woman retaineth honour: and strong men retain riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 17, E'The merciful man doeth good to his own soul: but he that is cruel troubleth his own flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 18, E'The wicked worketh a deceitful work: but to him that soweth righteousness shall be a sure reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 19, E'As righteousness tendeth to life: so he that pursueth evil pursueth it to his own death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 20, E'They that are of a froward heart are abomination to the LORD: but such as are upright in their way are his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 21, E'Though hand join in hand, the wicked shall not be unpunished: but the seed of the righteous shall be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 22, E'As a jewel of gold in a swine’s snout, so is a fair woman which is without discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 23, E'The desire of the righteous is only good: but the expectation of the wicked is wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 24, E'There is that scattereth, and yet increaseth; and there is that withholdeth more than is meet, but it tendeth to poverty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 25, E'The liberal soul shall be made fat: and he that watereth shall be watered also himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 26, E'He that withholdeth corn, the people shall curse him: but blessing shall be upon the head of him that selleth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 27, E'He that diligently seeketh good procureth favour: but he that seeketh mischief, it shall come unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 28, E'He that trusteth in his riches shall fall; but the righteous shall flourish as a branch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 29, E'He that troubleth his own house shall inherit the wind: and the fool shall be servant to the wise of heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 30, E'The fruit of the righteous is a tree of life; and he that winneth souls is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 31, E'Behold, the righteous shall be recompensed in the earth: much more the wicked and the sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 1, E'Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 2, E'A good man obtaineth favour of the LORD: but a man of wicked devices will he condemn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 3, E'A man shall not be established by wickedness: but the root of the righteous shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 4, E'A virtuous woman is a crown to her husband: but she that maketh ashamed is as rottenness in his bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 5, E'The thoughts of the righteous are right: but the counsels of the wicked are deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 6, E'The words of the wicked are to lie in wait for blood: but the mouth of the upright shall deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 7, E'The wicked are overthrown, and are not: but the house of the righteous shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 8, E'A man shall be commended according to his wisdom: but he that is of a perverse heart shall be despised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 9, E'He that is despised, and hath a servant, is better than he that honoureth himself, and lacketh bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 10, E'A righteous man regardeth the life of his beast: but the tender mercies of the wicked are cruel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 11, E'He that tilleth his land shall be satisfied with bread: but he that followeth vain persons is void of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 12, E'The wicked desireth the net of evil men: but the root of the righteous yieldeth fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 13, E'The wicked is snared by the transgression of his lips: but the just shall come out of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 14, E'A man shall be satisfied with good by the fruit of his mouth: and the recompence of a man’s hands shall be rendered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 15, E'The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 16, E'A fool’s wrath is presently known: but a prudent man covereth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 17, E'He that speaketh truth sheweth forth righteousness: but a false witness deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 18, E'There is that speaketh like the piercings of a sword: but the tongue of the wise is health.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 19, E'The lip of truth shall be established for ever: but a lying tongue is but for a moment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 20, E'Deceit is in the heart of them that imagine evil: but to the counsellors of peace is joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 21, E'There shall no evil happen to the just: but the wicked shall be filled with mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 22, E'Lying lips are abomination to the LORD: but they that deal truly are his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 23, E'A prudent man concealeth knowledge: but the heart of fools proclaimeth foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 24, E'The hand of the diligent shall bear rule: but the slothful shall be under tribute.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 25, E'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 26, E'The righteous is more excellent than his neighbour: but the way of the wicked seduceth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 27, E'The slothful man roasteth not that which he took in hunting: but the substance of a diligent man is precious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 28, E'In the way of righteousness is life: and in the pathway thereof there is no death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 1, E'A wise son heareth his father’s instruction: but a scorner heareth not rebuke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 2, E'A man shall eat good by the fruit of his mouth: but the soul of the transgressors shall eat violence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 3, E'He that keepeth his mouth keepeth his life: but he that openeth wide his lips shall have destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 4, E'The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 5, E'A righteous man hateth lying: but a wicked man is loathsome, and cometh to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 6, E'Righteousness keepeth him that is upright in the way: but wickedness overthroweth the sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 7, E'There is that maketh himself rich, yet hath nothing: there is that maketh himself poor, yet hath great riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 8, E'The ransom of a man’s life are his riches: but the poor heareth not rebuke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 9, E'The light of the righteous rejoiceth: but the lamp of the wicked shall be put out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 10, E'Only by pride cometh contention: but with the well advised is wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 11, E'Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 12, E'Hope deferred maketh the heart sick: but when the desire cometh, it is a tree of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 13, E'Whoso despiseth the word shall be destroyed: but he that feareth the commandment shall be rewarded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 14, E'The law of the wise is a fountain of life, to depart from the snares of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 15, E'Good understanding giveth favour: but the way of transgressors is hard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 16, E'Every prudent man dealeth with knowledge: but a fool layeth open his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 17, E'A wicked messenger falleth into mischief: but a faithful ambassador is health.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 18, E'Poverty and shame shall be to him that refuseth instruction: but he that regardeth reproof shall be honoured.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 19, E'The desire accomplished is sweet to the soul: but it is abomination to fools to depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 20, E'He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 21, E'Evil pursueth sinners: but to the righteous good shall be repayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 22, E'A good man leaveth an inheritance to his children’s children: and the wealth of the sinner is laid up for the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 23, E'Much food is in the tillage of the poor: but there is that is destroyed for want of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 24, E'He that spareth his rod hateth his son: but he that loveth him chasteneth him betimes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 25, E'The righteous eateth to the satisfying of his soul: but the belly of the wicked shall want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 1, E'Every wise woman buildeth her house: but the foolish plucketh it down with her hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 2, E'He that walketh in his uprightness feareth the LORD: but he that is perverse in his ways despiseth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 3, E'In the mouth of the foolish is a rod of pride: but the lips of the wise shall preserve them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 4, E'Where no oxen are, the crib is clean: but much increase is by the strength of the ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 5, E'A faithful witness will not lie: but a false witness will utter lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 6, E'A scorner seeketh wisdom, and findeth it not: but knowledge is easy unto him that understandeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 7, E'Go from the presence of a foolish man, when thou perceivest not in him the lips of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 8, E'The wisdom of the prudent is to understand his way: but the folly of fools is deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 9, E'Fools make a mock at sin: but among the righteous there is favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 10, E'The heart knoweth his own bitterness; and a stranger doth not intermeddle with his joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 11, E'The house of the wicked shall be overthrown: but the tabernacle of the upright shall flourish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 12, E'There is a way which seemeth right unto a man, but the end thereof are the ways of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 13, E'Even in laughter the heart is sorrowful; and the end of that mirth is heaviness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 14, E'The backslider in heart shall be filled with his own ways: and a good man shall be satisfied from himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 15, E'The simple believeth every word: but the prudent man looketh well to his going.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 16, E'A wise man feareth, and departeth from evil: but the fool rageth, and is confident.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 17, E'He that is soon angry dealeth foolishly: and a man of wicked devices is hated.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 18, E'The simple inherit folly: but the prudent are crowned with knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 19, E'The evil bow before the good; and the wicked at the gates of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 20, E'The poor is hated even of his own neighbour: but the rich hath many friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 21, E'He that despiseth his neighbour sinneth: but he that hath mercy on the poor, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 22, E'Do they not err that devise evil? but mercy and truth shall be to them that devise good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 23, E'In all labour there is profit: but the talk of the lips tendeth only to penury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 24, E'The crown of the wise is their riches: but the foolishness of fools is folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 25, E'A true witness delivereth souls: but a deceitful witness speaketh lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 26, E'In the fear of the LORD is strong confidence: and his children shall have a place of refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 27, E'The fear of the LORD is a fountain of life, to depart from the snares of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 28, E'In the multitude of people is the king’s honour: but in the want of people is the destruction of the prince.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 29, E'He that is slow to wrath is of great understanding: but he that is hasty of spirit exalteth folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 30, E'A sound heart is the life of the flesh: but envy the rottenness of the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 31, E'He that oppresseth the poor reproacheth his Maker: but he that honoureth him hath mercy on the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 32, E'The wicked is driven away in his wickedness: but the righteous hath hope in his death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 33, E'Wisdom resteth in the heart of him that hath understanding: but that which is in the midst of fools is made known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 34, E'Righteousness exalteth a nation: but sin is a reproach to any people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 35, E'The king’s favour is toward a wise servant: but his wrath is against him that causeth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 1, E'A soft answer turneth away wrath: but grievous words stir up anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 2, E'The tongue of the wise useth knowledge aright: but the mouth of fools poureth out foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 3, E'The eyes of the LORD are in every place, beholding the evil and the good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 4, E'A wholesome tongue is a tree of life: but perverseness therein is a breach in the spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 5, E'A fool despiseth his father’s instruction: but he that regardeth reproof is prudent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 6, E'In the house of the righteous is much treasure: but in the revenues of the wicked is trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 7, E'The lips of the wise disperse knowledge: but the heart of the foolish doeth not so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 8, E'The sacrifice of the wicked is an abomination to the LORD: but the prayer of the upright is his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 9, E'The way of the wicked is an abomination unto the LORD: but he loveth him that followeth after righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 10, E'Correction is grievous unto him that forsaketh the way: and he that hateth reproof shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 11, E'Hell and destruction are before the LORD: how much more then the hearts of the children of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 12, E'A scorner loveth not one that reproveth him: neither will he go unto the wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 13, E'A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 14, E'The heart of him that hath understanding seeketh knowledge: but the mouth of fools feedeth on foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 15, E'All the days of the afflicted are evil: but he that is of a merry heart hath a continual feast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 16, E'Better is little with the fear of the LORD than great treasure and trouble therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 17, E'Better is a dinner of herbs where love is, than a stalled ox and hatred therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 18, E'A wrathful man stirreth up strife: but he that is slow to anger appeaseth strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 19, E'The way of the slothful man is as an hedge of thorns: but the way of the righteous is made plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 20, E'A wise son maketh a glad father: but a foolish man despiseth his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 21, E'Folly is joy to him that is destitute of wisdom: but a man of understanding walketh uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 22, E'Without counsel purposes are disappointed: but in the multitude of counsellors they are established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 23, E'A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 24, E'The way of life is above to the wise, that he may depart from hell beneath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 25, E'The LORD will destroy the house of the proud: but he will establish the border of the widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 26, E'The thoughts of the wicked are an abomination to the LORD: but the words of the pure are pleasant words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 27, E'He that is greedy of gain troubleth his own house; but he that hateth gifts shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 28, E'The heart of the righteous studieth to answer: but the mouth of the wicked poureth out evil things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 29, E'The LORD is far from the wicked: but he heareth the prayer of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 30, E'The light of the eyes rejoiceth the heart: and a good report maketh the bones fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 31, E'The ear that heareth the reproof of life abideth among the wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 32, E'He that refuseth instruction despiseth his own soul: but he that heareth reproof getteth understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 33, E'The fear of the LORD is the instruction of wisdom; and before honour is humility.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 1, E'The preparations of the heart in man, and the answer of the tongue, is from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 2, E'All the ways of a man are clean in his own eyes; but the LORD weigheth the spirits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 3, E'Commit thy works unto the LORD, and thy thoughts shall be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 4, E'The LORD hath made all things for himself: yea, even the wicked for the day of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 5, E'Every one that is proud in heart is an abomination to the LORD: though hand join in hand, he shall not be unpunished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 6, E'By mercy and truth iniquity is purged: and by the fear of the LORD men depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 7, E'When a man’s ways please the LORD, he maketh even his enemies to be at peace with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 8, E'Better is a little with righteousness than great revenues without right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 9, E'A man’s heart deviseth his way: but the LORD directeth his steps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 10, E'A divine sentence is in the lips of the king: his mouth transgresseth not in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 11, E'A just weight and balance are the LORD’s: all the weights of the bag are his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 12, E'It is an abomination to kings to commit wickedness: for the throne is established by righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 13, E'Righteous lips are the delight of kings; and they love him that speaketh right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 14, E'The wrath of a king is as messengers of death: but a wise man will pacify it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 15, E'In the light of the king’s countenance is life; and his favour is as a cloud of the latter rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 16, E'How much better is it to get wisdom than gold! and to get understanding rather to be chosen than silver!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 17, E'The highway of the upright is to depart from evil: he that keepeth his way preserveth his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 18, E'Pride goeth before destruction, and an haughty spirit before a fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 19, E'Better it is to be of an humble spirit with the lowly, than to divide the spoil with the proud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 20, E'He that handleth a matter wisely shall find good: and whoso trusteth in the LORD, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 21, E'The wise in heart shall be called prudent: and the sweetness of the lips increaseth learning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 22, E'Understanding is a wellspring of life unto him that hath it: but the instruction of fools is folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 23, E'The heart of the wise teacheth his mouth, and addeth learning to his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 24, E'Pleasant words are as an honeycomb, sweet to the soul, and health to the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 25, E'There is a way that seemeth right unto a man, but the end thereof are the ways of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 26, E'He that laboureth laboureth for himself; for his mouth craveth it of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 27, E'An ungodly man diggeth up evil: and in his lips there is as a burning fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 28, E'A froward man soweth strife: and a whisperer separateth chief friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 29, E'A violent man enticeth his neighbour, and leadeth him into the way that is not good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 30, E'He shutteth his eyes to devise froward things: moving his lips he bringeth evil to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 31, E'The hoary head is a crown of glory, if it be found in the way of righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 32, E'He that is slow to anger is better than the mighty; and he that ruleth his spirit than he that taketh a city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 33, E'The lot is cast into the lap; but the whole disposing thereof is of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 1, E'Better is a dry morsel, and quietness therewith, than an house full of sacrifices with strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 2, E'A wise servant shall have rule over a son that causeth shame, and shall have part of the inheritance among the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 3, E'The fining pot is for silver, and the furnace for gold: but the LORD trieth the hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 4, E'A wicked doer giveth heed to false lips; and a liar giveth ear to a naughty tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 5, E'Whoso mocketh the poor reproacheth his Maker: and he that is glad at calamities shall not be unpunished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 6, E'Children’s children are the crown of old men; and the glory of children are their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 7, E'Excellent speech becometh not a fool: much less do lying lips a prince.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 8, E'A gift is as a precious stone in the eyes of him that hath it: whithersoever it turneth, it prospereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 9, E'He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 10, E'A reproof entereth more into a wise man than an hundred stripes into a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 11, E'An evil man seeketh only rebellion: therefore a cruel messenger shall be sent against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 12, E'Let a bear robbed of her whelps meet a man, rather than a fool in his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 13, E'Whoso rewardeth evil for good, evil shall not depart from his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 14, E'The beginning of strife is as when one letteth out water: therefore leave off contention, before it be meddled with.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 15, E'He that justifieth the wicked, and he that condemneth the just, even they both are abomination to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 16, E'Wherefore is there a price in the hand of a fool to get wisdom, seeing he hath no heart to it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 17, E'A friend loveth at all times, and a brother is born for adversity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 18, E'A man void of understanding striketh hands, and becometh surety in the presence of his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 19, E'He loveth transgression that loveth strife: and he that exalteth his gate seeketh destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 20, E'He that hath a froward heart findeth no good: and he that hath a perverse tongue falleth into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 21, E'He that begetteth a fool doeth it to his sorrow: and the father of a fool hath no joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 22, E'A merry heart doeth good like a medicine: but a broken spirit drieth the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 23, E'A wicked man taketh a gift out of the bosom to pervert the ways of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 24, E'Wisdom is before him that hath understanding; but the eyes of a fool are in the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 25, E'A foolish son is a grief to his father, and bitterness to her that bare him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 26, E'Also to punish the just is not good, nor to strike princes for equity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 27, E'He that hath knowledge spareth his words: and a man of understanding is of an excellent spirit.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 28, E'Even a fool, when he holdeth his peace, is counted wise: and he that shutteth his lips is esteemed a man of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 1, E'Through desire a man, having separated himself, seeketh and intermeddleth with all wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 2, E'A fool hath no delight in understanding, but that his heart may discover itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 3, E'When the wicked cometh, then cometh also contempt, and with ignominy reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 4, E'The words of a man’s mouth are as deep waters, and the wellspring of wisdom as a flowing brook.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 5, E'It is not good to accept the person of the wicked, to overthrow the righteous in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 6, E'A fool’s lips enter into contention, and his mouth calleth for strokes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 7, E'A fool’s mouth is his destruction, and his lips are the snare of his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 8, E'The words of a talebearer are as wounds, and they go down into the innermost parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 9, E'He also that is slothful in his work is brother to him that is a great waster.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 10, E'The name of the LORD is a strong tower: the righteous runneth into it, and is safe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 11, E'The rich man’s wealth is his strong city, and as an high wall in his own conceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 12, E'Before destruction the heart of man is haughty, and before honour is humility.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 13, E'He that answereth a matter before he heareth it, it is folly and shame unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 14, E'The spirit of a man will sustain his infirmity; but a wounded spirit who can bear?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 15, E'The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 16, E'A man’s gift maketh room for him, and bringeth him before great men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 17, E'He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 18, E'The lot causeth contentions to cease, and parteth between the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 19, E'A brother offended is harder to be won than a strong city: and their contentions are like the bars of a castle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 20, E'A man’s belly shall be satisfied with the fruit of his mouth; and with the increase of his lips shall he be filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 21, E'Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 22, E'Whoso findeth a wife findeth a good thing, and obtaineth favour of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 23, E'The poor useth intreaties; but the rich answereth roughly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 24, E'A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 1, E'Better is the poor that walketh in his integrity, than he that is perverse in his lips, and is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 2, E'Also, that the soul be without knowledge, it is not good; and he that hasteth with his feet sinneth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 3, E'The foolishness of man perverteth his way: and his heart fretteth against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 4, E'Wealth maketh many friends; but the poor is separated from his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 5, E'A false witness shall not be unpunished, and he that speaketh lies shall not escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 6, E'Many will intreat the favour of the prince: and every man is a friend to him that giveth gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 7, E'All the brethren of the poor do hate him: how much more do his friends go far from him? he pursueth them with words, yet they are wanting to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 8, E'He that getteth wisdom loveth his own soul: he that keepeth understanding shall find good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 9, E'A false witness shall not be unpunished, and he that speaketh lies shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 10, E'Delight is not seemly for a fool; much less for a servant to have rule over princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 11, E'The discretion of a man deferreth his anger; and it is his glory to pass over a transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 12, E'The king’s wrath is as the roaring of a lion; but his favour is as dew upon the grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 13, E'A foolish son is the calamity of his father: and the contentions of a wife are a continual dropping.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 14, E'House and riches are the inheritance of fathers: and a prudent wife is from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 15, E'Slothfulness casteth into a deep sleep; and an idle soul shall suffer hunger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 16, E'He that keepeth the commandment keepeth his own soul; but he that despiseth his ways shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 17, E'He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 18, E'Chasten thy son while there is hope, and let not thy soul spare for his crying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 19, E'A man of great wrath shall suffer punishment: for if thou deliver him, yet thou must do it again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 20, E'Hear counsel, and receive instruction, that thou mayest be wise in thy latter end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 21, E'There are many devices in a man’s heart; nevertheless the counsel of the LORD, that shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 22, E'The desire of a man is his kindness: and a poor man is better than a liar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 23, E'The fear of the LORD tendeth to life: and he that hath it shall abide satisfied; he shall not be visited with evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 24, E'A slothful man hideth his hand in his bosom, and will not so much as bring it to his mouth again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 25, E'Smite a scorner, and the simple will beware: and reprove one that hath understanding, and he will understand knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 26, E'He that wasteth his father, and chaseth away his mother, is a son that causeth shame, and bringeth reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 27, E'Cease, my son, to hear the instruction that causeth to err from the words of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 28, E'An ungodly witness scorneth judgment: and the mouth of the wicked devoureth iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 29, E'Judgments are prepared for scorners, and stripes for the back of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 1, E'Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 2, E'The fear of a king is as the roaring of a lion: whoso provoketh him to anger sinneth against his own soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 3, E'It is an honour for a man to cease from strife: but every fool will be meddling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 4, E'The sluggard will not plow by reason of the cold; therefore shall he beg in harvest, and have nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 5, E'Counsel in the heart of man is like deep water; but a man of understanding will draw it out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 6, E'Most men will proclaim every one his own goodness: but a faithful man who can find?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 7, E'The just man walketh in his integrity: his children are blessed after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 8, E'A king that sitteth in the throne of judgment scattereth away all evil with his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 9, E'Who can say, I have made my heart clean, I am pure from my sin?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 10, E'Divers weights, and divers measures, both of them are alike abomination to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 11, E'Even a child is known by his doings, whether his work be pure, and whether it be right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 12, E'The hearing ear, and the seeing eye, the LORD hath made even both of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 13, E'Love not sleep, lest thou come to poverty; open thine eyes, and thou shalt be satisfied with bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 14, E'It is naught, it is naught, saith the buyer: but when he is gone his way, then he boasteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 15, E'There is gold, and a multitude of rubies: but the lips of knowledge are a precious jewel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 16, E'Take his garment that is surety for a stranger: and take a pledge of him for a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 17, E'Bread of deceit is sweet to a man; but afterwards his mouth shall be filled with gravel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 18, E'Every purpose is established by counsel: and with good advice make war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 19, E'He that goeth about as a talebearer revealeth secrets: therefore meddle not with him that flattereth with his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 20, E'Whoso curseth his father or his mother, his lamp shall be put out in obscure darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 21, E'An inheritance may be gotten hastily at the beginning; but the end thereof shall not be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 22, E'Say not thou, I will recompense evil; but wait on the LORD, and he shall save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 23, E'Divers weights are an abomination unto the LORD; and a false balance is not good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 24, E'Man’s goings are of the LORD; how can a man then understand his own way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 25, E'It is a snare to the man who devoureth that which is holy, and after vows to make enquiry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 26, E'A wise king scattereth the wicked, and bringeth the wheel over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 27, E'The spirit of man is the candle of the LORD, searching all the inward parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 28, E'Mercy and truth preserve the king: and his throne is upholden by mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 29, E'The glory of young men is their strength: and the beauty of old men is the grey head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 30, E'The blueness of a wound cleanseth away evil: so do stripes the inward parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 1, E'The king’s heart is in the hand of the LORD, as the rivers of water: he turneth it whithersoever he will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 2, E'Every way of a man is right in his own eyes: but the LORD pondereth the hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 3, E'To do justice and judgment is more acceptable to the LORD than sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 4, E'An high look, and a proud heart, and the plowing of the wicked, is sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 5, E'The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 6, E'The getting of treasures by a lying tongue is a vanity tossed to and fro of them that seek death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 7, E'The robbery of the wicked shall destroy them; because they refuse to do judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 8, E'The way of man is froward and strange: but as for the pure, his work is right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 9, E'It is better to dwell in a corner of the housetop, than with a brawling woman in a wide house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 10, E'The soul of the wicked desireth evil: his neighbour findeth no favour in his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 11, E'When the scorner is punished, the simple is made wise: and when the wise is instructed, he receiveth knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 12, E'The righteous man wisely considereth the house of the wicked: but God overthroweth the wicked for their wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 13, E'Whoso stoppeth his ears at the cry of the poor, he also shall cry himself, but shall not be heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 14, E'A gift in secret pacifieth anger: and a reward in the bosom strong wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 15, E'It is joy to the just to do judgment: but destruction shall be to the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 16, E'The man that wandereth out of the way of understanding shall remain in the congregation of the dead.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 17, E'He that loveth pleasure shall be a poor man: he that loveth wine and oil shall not be rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 18, E'The wicked shall be a ransom for the righteous, and the transgressor for the upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 19, E'It is better to dwell in the wilderness, than with a contentious and an angry woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 20, E'There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 21, E'He that followeth after righteousness and mercy findeth life, righteousness, and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 22, E'A wise man scaleth the city of the mighty, and casteth down the strength of the confidence thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 23, E'Whoso keepeth his mouth and his tongue keepeth his soul from troubles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 24, E'Proud and haughty scorner is his name, who dealeth in proud wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 25, E'The desire of the slothful killeth him; for his hands refuse to labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 26, E'He coveteth greedily all the day long: but the righteous giveth and spareth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 27, E'The sacrifice of the wicked is abomination: how much more, when he bringeth it with a wicked mind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 28, E'A false witness shall perish: but the man that heareth speaketh constantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 29, E'A wicked man hardeneth his face: but as for the upright, he directeth his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 30, E'There is no wisdom nor understanding nor counsel against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 31, E'The horse is prepared against the day of battle: but safety is of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 1, E'A GOOD name is rather to be chosen than great riches, and loving favour rather than silver and gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 2, E'The rich and poor meet together: the LORD is the maker of them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 3, E'A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 4, E'By humility and the fear of the LORD are riches, and honour, and life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 5, E'Thorns and snares are in the way of the froward: he that doth keep his soul shall be far from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 6, E'Train up a child in the way he should go: and when he is old, he will not depart from it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 7, E'The rich ruleth over the poor, and the borrower is servant to the lender.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 8, E'He that soweth iniquity shall reap vanity: and the rod of his anger shall fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 9, E'He that hath a bountiful eye shall be blessed; for he giveth of his bread to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 10, E'Cast out the scorner, and contention shall go out; yea, strife and reproach shall cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 11, E'He that loveth pureness of heart, for the grace of his lips the king shall be his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 12, E'The eyes of the LORD preserve knowledge, and he overthroweth the words of the transgressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 13, E'The slothful man saith, There is a lion without, I shall be slain in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 14, E'The mouth of strange women is a deep pit: he that is abhorred of the LORD shall fall therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 15, E'Foolishness is bound in the heart of a child; but the rod of correction shall drive it far from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 16, E'He that oppresseth the poor to increase his riches, and he that giveth to the rich, shall surely come to want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 17, E'Bow down thine ear, and hear the words of the wise, and apply thine heart unto my knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 18, E'For it is a pleasant thing if thou keep them within thee; they shall withal be fitted in thy lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 19, E'That thy trust may be in the LORD, I have made known to thee this day, even to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 20, E'Have not I written to thee excellent things in counsels and knowledge,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 21, E'That I might make thee know the certainty of the words of truth; that thou mightest answer the words of truth to them that send unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 22, E'Rob not the poor, because he is poor: neither oppress the afflicted in the gate:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 23, E'For the LORD will plead their cause, and spoil the soul of those that spoiled them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 24, E'Make no friendship with an angry man; and with a furious man thou shalt not go:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 25, E'Lest thou learn his ways, and get a snare to thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 26, E'Be not thou one of them that strike hands, or of them that are sureties for debts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 27, E'If thou hast nothing to pay, why should he take away thy bed from under thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 28, E'Remove not the ancient landmark, which thy fathers have set.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 29, E'Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 1, E'When thou sittest to eat with a ruler, consider diligently what is before thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 2, E'And put a knife to thy throat, if thou be a man given to appetite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 3, E'Be not desirous of his dainties: for they are deceitful meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 4, E'Labour not to be rich: cease from thine own wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 5, E'Wilt thou set thine eyes upon that which is not? for riches certainly make themselves wings; they fly away as an eagle toward heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 6, E'Eat thou not the bread of him that hath an evil eye, neither desire thou his dainty meats:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 7, E'For as he thinketh in his heart, so is he: Eat and drink, saith he to thee; but his heart is not with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 8, E'The morsel which thou hast eaten shalt thou vomit up, and lose thy sweet words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 9, E'Speak not in the ears of a fool: for he will despise the wisdom of thy words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 10, E'Remove not the old landmark; and enter not into the fields of the fatherless:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 11, E'For their redeemer is mighty; he shall plead their cause with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 12, E'Apply thine heart unto instruction, and thine ears to the words of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 13, E'Withhold not correction from the child: for if thou beatest him with the rod, he shall not die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 14, E'Thou shalt beat him with the rod, and shalt deliver his soul from hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 15, E'My son, if thine heart be wise, my heart shall rejoice, even mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 16, E'Yea, my reins shall rejoice, when thy lips speak right things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 17, E'Let not thine heart envy sinners: but be thou in the fear of the LORD all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 18, E'For surely there is an end; and thine expectation shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 19, E'Hear thou, my son, and be wise, and guide thine heart in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 20, E'Be not among winebibbers; among riotous eaters of flesh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 21, E'For the drunkard and the glutton shall come to poverty: and drowsiness shall clothe a man with rags.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 22, E'Hearken unto thy father that begat thee, and despise not thy mother when she is old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 23, E'Buy the truth, and sell it not; also wisdom, and instruction, and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 24, E'The father of the righteous shall greatly rejoice: and he that begetteth a wise child shall have joy of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 25, E'Thy father and thy mother shall be glad, and she that bare thee shall rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 26, E'My son, give me thine heart, and let thine eyes observe my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 27, E'For a whore is a deep ditch; and a strange woman is a narrow pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 28, E'She also lieth in wait as for a prey, and increaseth the transgressors among men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 29, E'Who hath woe? who hath sorrow? who hath contentions? who hath babbling? who hath wounds without cause? who hath redness of eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 30, E'They that tarry long at the wine; they that go to seek mixed wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 31, E'Look not thou upon the wine when it is red, when it giveth his colour in the cup, when it moveth itself aright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 32, E'At the last it biteth like a serpent, and stingeth like an adder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 33, E'Thine eyes shall behold strange women, and thine heart shall utter perverse things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 34, E'Yea, thou shalt be as he that lieth down in the midst of the sea, or as he that lieth upon the top of a mast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 35, E'They have stricken me, shalt thou say, and I was not sick; they have beaten me, and I felt it not: when shall I awake? I will seek it yet again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 1, E'Be not thou envious against evil men, neither desire to be with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 2, E'For their heart studieth destruction, and their lips talk of mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 3, E'Through wisdom is an house builded; and by understanding it is established:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 4, E'And by knowledge shall the chambers be filled with all precious and pleasant riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 5, E'A wise man is strong; yea, a man of knowledge increaseth strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 6, E'For by wise counsel thou shalt make thy war: and in multitude of counsellors there is safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 7, E'Wisdom is too high for a fool: he openeth not his mouth in the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 8, E'He that deviseth to do evil shall be called a mischievous person.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 9, E'The thought of foolishness is sin: and the scorner is an abomination to men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 10, E'If thou faint in the day of adversity, thy strength is small.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 11, E'If thou forbear to deliver them that are drawn unto death, and those that are ready to be slain;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 12, E'If thou sayest, Behold, we knew it not; doth not he that pondereth the heart consider it? and he that keepeth thy soul, doth not he know it? and shall not he render to every man according to his works?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 13, E'My son, eat thou honey, because it is good; and the honeycomb, which is sweet to thy taste:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 14, E'So shall the knowledge of wisdom be unto thy soul: when thou hast found it, then there shall be a reward, and thy expectation shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 15, E'Lay not wait, O wicked man, against the dwelling of the righteous; spoil not his resting place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 16, E'For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 17, E'Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 18, E'Lest the LORD see it, and it displease him, and he turn away his wrath from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 19, E'Fret not thyself because of evil men, neither be thou envious at the wicked;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 20, E'For there shall be no reward to the evil man; the candle of the wicked shall be put out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 21, E'My son, fear thou the LORD and the king: and meddle not with them that are given to change:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 22, E'For their calamity shall rise suddenly; and who knoweth the ruin of them both?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 23, E'These things also belong to the wise. It is not good to have respect of persons in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 24, E'He that saith unto the wicked, Thou art righteous; him shall the people curse, nations shall abhor him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 25, E'But to them that rebuke him shall be delight, and a good blessing shall come upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 26, E'Every man shall kiss his lips that giveth a right answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 27, E'Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 28, E'Be not a witness against thy neighbour without cause; and deceive not with thy lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 29, E'Say not, I will do so to him as he hath done to me: I will render to the man according to his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 30, E'I went by the field of the slothful, and by the vineyard of the man void of understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 31, E'And, lo, it was all grown over with thorns, and nettles had covered the face thereof, and the stone wall thereof was broken down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 32, E'Then I saw, and considered it well: I looked upon it, and received instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 33, E'Yet a little sleep, a little slumber, a little folding of the hands to sleep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 34, E'So shall thy poverty come as one that travelleth; and thy want as an armed man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 1, E'These are also proverbs of Solomon, which the men of Hezekiah king of Judah copied out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 2, E'It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 3, E'The heaven for height, and the earth for depth, and the heart of kings is unsearchable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 4, E'Take away the dross from the silver, and there shall come forth a vessel for the finer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 5, E'Take away the wicked from before the king, and his throne shall be established in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 6, E'Put not forth thyself in the presence of the king, and stand not in the place of great men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 7, E'For better it is that it be said unto thee, Come up hither; than that thou shouldest be put lower in the presence of the prince whom thine eyes have seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 8, E'Go not forth hastily to strive, lest thou know not what to do in the end thereof, when thy neighbour hath put thee to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 9, E'Debate thy cause with thy neighbour himself; and discover not a secret to another:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 10, E'Lest he that heareth it put thee to shame, and thine infamy turn not away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 11, E'A word fitly spoken is like apples of gold in pictures of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 12, E'As an earring of gold, and an ornament of fine gold, so is a wise reprover upon an obedient ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 13, E'As the cold of snow in the time of harvest, so is a faithful messenger to them that send him: for he refresheth the soul of his masters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 14, E'Whoso boasteth himself of a false gift is like clouds and wind without rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 15, E'By long forbearing is a prince persuaded, and a soft tongue breaketh the bone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 16, E'Hast thou found honey? eat so much as is sufficient for thee, lest thou be filled therewith, and vomit it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 17, E'Withdraw thy foot from thy neighbour’s house; lest he be weary of thee, and so hate thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 18, E'A man that beareth false witness against his neighbour is a maul, and a sword, and a sharp arrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 19, E'Confidence in an unfaithful man in time of trouble is like a broken tooth, and a foot out of joint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 20, E'As he that taketh away a garment in cold weather, and as vinegar upon nitre, so is he that singeth songs to an heavy heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 21, E'If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 22, E'For thou shalt heap coals of fire upon his head, and the LORD shall reward thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 23, E'The north wind driveth away rain: so doth an angry countenance a backbiting tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 24, E'It is better to dwell in the corner of the housetop, than with a brawling woman and in a wide house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 25, E'As cold waters to a thirsty soul, so is good news from a far country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 26, E'A righteous man falling down before the wicked is as a troubled fountain, and a corrupt spring.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 27, E'It is not good to eat much honey: so for men to search their own glory is not glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 28, E'He that hath no rule over his own spirit is like a city that is broken down, and without walls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 1, E'As snow in summer, and as rain in harvest, so honour is not seemly for a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 2, E'As the bird by wandering, as the swallow by flying, so the curse causeless shall not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 3, E'A whip for the horse, a bridle for the ass, and a rod for the fool’s back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 4, E'Answer not a fool according to his folly, lest thou also be like unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 5, E'Answer a fool according to his folly, lest he be wise in his own conceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 6, E'He that sendeth a message by the hand of a fool cutteth off the feet, and drinketh damage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 7, E'The legs of the lame are not equal: so is a parable in the mouth of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 8, E'As he that bindeth a stone in a sling, so is he that giveth honour to a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 9, E'As a thorn goeth up into the hand of a drunkard, so is a parable in the mouth of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 10, E'The great God that formed all things both rewardeth the fool, and rewardeth transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 11, E'As a dog returneth to his vomit, so a fool returneth to his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 12, E'Seest thou a man wise in his own conceit? there is more hope of a fool than of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 13, E'The slothful man saith, There is a lion in the way; a lion is in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 14, E'As the door turneth upon his hinges, so doth the slothful upon his bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 15, E'The slothful hideth his hand in his bosom; it grieveth him to bring it again to his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 16, E'The sluggard is wiser in his own conceit than seven men that can render a reason.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 17, E'He that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 18, E'As a mad man who casteth firebrands, arrows, and death,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 19, E'So is the man that deceiveth his neighbour, and saith, Am not I in sport?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 20, E'Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 21, E'As coals are to burning coals, and wood to fire; so is a contentious man to kindle strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 22, E'The words of a talebearer are as wounds, and they go down into the innermost parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 23, E'Burning lips and a wicked heart are like a potsherd covered with silver dross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 24, E'He that hateth dissembleth with his lips, and layeth up deceit within him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 25, E'When he speaketh fair, believe him not: for there are seven abominations in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 26, E'Whose hatred is covered by deceit, his wickedness shall be shewed before the whole congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 27, E'Whoso diggeth a pit shall fall therein: and he that rolleth a stone, it will return upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 28, E'A lying tongue hateth those that are afflicted by it; and a flattering mouth worketh ruin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 1, E'Boast not thyself of to morrow; for thou knowest not what a day may bring forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 2, E'Let another man praise thee, and not thine own mouth; a stranger, and not thine own lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 3, E'A stone is heavy, and the sand weighty; but a fool’s wrath is heavier than them both.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 4, E'Wrath is cruel, and anger is outrageous; but who is able to stand before envy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 5, E'Open rebuke is better than secret love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 6, E'Faithful are the wounds of a friend; but the kisses of an enemy are deceitful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 7, E'The full soul loatheth an honeycomb; but to the hungry soul every bitter thing is sweet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 8, E'As a bird that wandereth from her nest, so is a man that wandereth from his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 9, E'Ointment and perfume rejoice the heart: so doth the sweetness of a man’s friend by hearty counsel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 10, E'Thine own friend, and thy father’s friend, forsake not; neither go into thy brother’s house in the day of thy calamity: for better is a neighbour that is near than a brother far off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 11, E'My son, be wise, and make my heart glad, that I may answer him that reproacheth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 12, E'A prudent man foreseeth the evil, and hideth himself; but the simple pass on, and are punished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 13, E'Take his garment that is surety for a stranger, and take a pledge of him for a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 14, E'He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 15, E'A continual dropping in a very rainy day and a contentious woman are alike.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 16, E'Whosoever hideth her hideth the wind, and the ointment of his right hand, which bewrayeth itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 17, E'Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 18, E'Whoso keepeth the fig tree shall eat the fruit thereof: so he that waiteth on his master shall be honoured.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 19, E'As in water face answereth to face, so the heart of man to man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 20, E'Hell and destruction are never full; so the eyes of man are never satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 21, E'As the fining pot for silver, and the furnace for gold; so is a man to his praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 22, E'Though thou shouldest bray a fool in a mortar among wheat with a pestle, yet will not his foolishness depart from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 23, E'Be thou diligent to know the state of thy flocks, and look well to thy herds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 24, E'For riches are not for ever: and doth the crown endure to every generation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 25, E'The hay appeareth, and the tender grass sheweth itself, and herbs of the mountains are gathered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 26, E'The lambs are for thy clothing, and the goats are the price of the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 27, E'And thou shalt have goats’ milk enough for thy food, for the food of thy household, and for the maintenance for thy maidens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 1, E'The wicked flee when no man pursueth: but the righteous are bold as a lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 2, E'For the transgression of a land many are the princes thereof: but by a man of understanding and knowledge the state thereof shall be prolonged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 3, E'A poor man that oppresseth the poor is like a sweeping rain which leaveth no food.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 4, E'They that forsake the law praise the wicked: but such as keep the law contend with them.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 5, E'Evil men understand not judgment: but they that seek the LORD understand all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 6, E'Better is the poor that walketh in his uprightness, than he that is perverse in his ways, though he be rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 7, E'Whoso keepeth the law is a wise son: but he that is a companion of riotous men shameth his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 8, E'He that by usury and unjust gain increaseth his substance, he shall gather it for him that will pity the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 9, E'He that turneth away his ear from hearing the law, even his prayer shall be abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 10, E'Whoso causeth the righteous to go astray in an evil way, he shall fall himself into his own pit: but the upright shall have good things in possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 11, E'The rich man is wise in his own conceit; but the poor that hath understanding searcheth him out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 12, E'When righteous men do rejoice, there is great glory: but when the wicked rise, a man is hidden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 13, E'He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 14, E'Happy is the man that feareth alway: but he that hardeneth his heart shall fall into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 15, E'As a roaring lion, and a ranging bear; so is a wicked ruler over the poor people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 16, E'The prince that wanteth understanding is also a great oppressor: but he that hateth covetousness shall prolong his days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 17, E'A man that doeth violence to the blood of any person shall flee to the pit; let no man stay him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 18, E'Whoso walketh uprightly shall be saved: but he that is perverse in his ways shall fall at once.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 19, E'He that tilleth his land shall have plenty of bread: but he that followeth after vain persons shall have poverty enough.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 20, E'A faithful man shall abound with blessings: but he that maketh haste to be rich shall not be innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 21, E'To have respect of persons is not good: for for a piece of bread that man will transgress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 22, E'He that hasteth to be rich hath an evil eye, and considereth not that poverty shall come upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 23, E'He that rebuketh a man afterwards shall find more favour than he that flattereth with the tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 24, E'Whoso robbeth his father or his mother, and saith, It is no transgression; the same is the companion of a destroyer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 25, E'He that is of a proud heart stirreth up strife: but he that putteth his trust in the LORD shall be made fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 26, E'He that trusteth in his own heart is a fool: but whoso walketh wisely, he shall be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 27, E'He that giveth unto the poor shall not lack: but he that hideth his eyes shall have many a curse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 28, E'When the wicked rise, men hide themselves: but when they perish, the righteous increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 1, E'He, that being often reproved hardeneth his neck, shall suddenly be destroyed, and that without remedy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 2, E'When the righteous are in authority, the people rejoice: but when the wicked beareth rule, the people mourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 3, E'Whoso loveth wisdom rejoiceth his father: but he that keepeth company with harlots spendeth his substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 4, E'The king by judgment establisheth the land: but he that receiveth gifts overthroweth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 5, E'A man that flattereth his neighbour spreadeth a net for his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 6, E'In the transgression of an evil man there is a snare: but the righteous doth sing and rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 7, E'The righteous considereth the cause of the poor: but the wicked regardeth not to know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 8, E'Scornful men bring a city into a snare: but wise men turn away wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 9, E'If a wise man contendeth with a foolish man, whether he rage or laugh, there is no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 10, E'The bloodthirsty hate the upright: but the just seek his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 11, E'A fool uttereth all his mind: but a wise man keepeth it in till afterwards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 12, E'If a ruler hearken to lies, all his servants are wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 13, E'The poor and the deceitful man meet together: the LORD lighteneth both their eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 14, E'The king that faithfully judgeth the poor, his throne shall be established for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 15, E'The rod and reproof give wisdom: but a child left to himself bringeth his mother to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 16, E'When the wicked are multiplied, transgression increaseth: but the righteous shall see their fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 17, E'Correct thy son, and he shall give thee rest; yea, he shall give delight unto thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 18, E'Where there is no vision, the people perish: but he that keepeth the law, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 19, E'A servant will not be corrected by words: for though he understand he will not answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 20, E'Seest thou a man that is hasty in his words? there is more hope of a fool than of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 21, E'He that delicately bringeth up his servant from a child shall have him become his son at the length.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 22, E'An angry man stirreth up strife, and a furious man aboundeth in transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 23, E'A man’s pride shall bring him low: but honour shall uphold the humble in spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 24, E'Whoso is partner with a thief hateth his own soul: he heareth cursing, and bewrayeth it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 25, E'The fear of man bringeth a snare: but whoso putteth his trust in the LORD shall be safe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 26, E'Many seek the ruler’s favour; but every man’s judgment cometh from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 27, E'An unjust man is an abomination to the just: and he that is upright in the way is abomination to the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 1, E'The words of Agur the son of Jakeh, even the prophecy: the man spake unto Ithiel, even unto Ithiel and Ucal,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 2, E'Surely I am more brutish than any man, and have not the understanding of a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 3, E'I neither learned wisdom, nor have the knowledge of the holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 4, E'Who hath ascended up into heaven, or descended? who hath gathered the wind in his fists? who hath bound the waters in a garment? who hath established all the ends of the earth? what is his name, and what is his son’s name, if thou canst tell?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 5, E'Every word of God is pure: he is a shield unto them that put their trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 6, E'Add thou not unto his words, lest he reprove thee, and thou be found a liar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 7, E'Two things have I required of thee; deny me them not before I die:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 8, E'Remove far from me vanity and lies: give me neither poverty nor riches; feed me with food convenient for me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 9, E'Lest I be full, and deny thee, and say, Who is the LORD? or lest I be poor, and steal, and take the name of my God in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 10, E'Accuse not a servant unto his master, lest he curse thee, and thou be found guilty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 11, E'There is a generation that curseth their father, and doth not bless their mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 12, E'There is a generation that are pure in their own eyes, and yet is not washed from their filthiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 13, E'There is a generation, O how lofty are their eyes! and their eyelids are lifted up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 14, E'There is a generation, whose teeth are as swords, and their jaw teeth as knives, to devour the poor from off the earth, and the needy from among men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 15, E'The horseleach hath two daughters, crying, Give, give. There are three things that are never satisfied, yea, four things say not, It is enough:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 16, E'The grave; and the barren womb; the earth that is not filled with water; and the fire that saith not, It is enough.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 17, E'The eye that mocketh at his father, and despiseth to obey his mother, the ravens of the valley shall pick it out, and the young eagles shall eat it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 18, E'There be three things which are too wonderful for me, yea, four which I know not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 19, E'The way of an eagle in the air; the way of a serpent upon a rock; the way of a ship in the midst of the sea; and the way of a man with a maid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 20, E'Such is the way of an adulterous woman; she eateth, and wipeth her mouth, and saith, I have done no wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 21, E'For three things the earth is disquieted, and for four which it cannot bear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 22, E'For a servant when he reigneth; and a fool when he is filled with meat;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 23, E'For an odious woman when she is married; and an handmaid that is heir to her mistress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 24, E'There be four things which are little upon the earth, but they are exceeding wise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 25, E'The ants are a people not strong, yet they prepare their meat in the summer;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 26, E'The conies are but a feeble folk, yet make they their houses in the rocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 27, E'The locusts have no king, yet go they forth all of them by bands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 28, E'The spider taketh hold with her hands, and is in kings’ palaces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 29, E'There be three things which go well, yea, four are comely in going:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 30, E'A lion which is strongest among beasts, and turneth not away for any;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 31, E'A greyhound; an he goat also; and a king, against whom there is no rising up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 32, E'If thou hast done foolishly in lifting up thyself, or if thou hast thought evil, lay thine hand upon thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 33, E'Surely the churning of milk bringeth forth butter, and the wringing of the nose bringeth forth blood: so the forcing of wrath bringeth forth strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 1, E'The words of king Lemuel, the prophecy that his mother taught him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 2, E'What, my son? and what, the son of my womb? and what, the son of my vows?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 3, E'Give not thy strength unto women, nor thy ways to that which destroyeth kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 4, E'It is not for kings, O Lemuel, it is not for kings to drink wine; nor for princes strong drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 5, E'Lest they drink, and forget the law, and pervert the judgment of any of the afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 6, E'Give strong drink unto him that is ready to perish, and wine unto those that be of heavy hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 7, E'Let him drink, and forget his poverty, and remember his misery no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 8, E'Open thy mouth for the dumb in the cause of all such as are appointed to destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 9, E'Open thy mouth, judge righteously, and plead the cause of the poor and needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 10, E'Who can find a virtuous woman? for her price is far above rubies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 11, E'The heart of her husband doth safely trust in her, so that he shall have no need of spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 12, E'She will do him good and not evil all the days of her life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 13, E'She seeketh wool, and flax, and worketh willingly with her hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 14, E'She is like the merchants’ ships; she bringeth her food from afar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 15, E'She riseth also while it is yet night, and giveth meat to her household, and a portion to her maidens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 16, E'She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 17, E'She girdeth her loins with strength, and strengtheneth her arms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 18, E'She perceiveth that her merchandise is good: her candle goeth not out by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 19, E'She layeth her hands to the spindle, and her hands hold the distaff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 20, E'She stretcheth out her hand to the poor; yea, she reacheth forth her hands to the needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 21, E'She is not afraid of the snow for her household: for all her household are clothed with scarlet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 22, E'She maketh herself coverings of tapestry; her clothing is silk and purple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 23, E'Her husband is known in the gates, when he sitteth among the elders of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 24, E'She maketh fine linen, and selleth it; and delivereth girdles unto the merchant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 25, E'Strength and honour are her clothing; and she shall rejoice in time to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 26, E'She openeth her mouth with wisdom; and in her tongue is the law of kindness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 27, E'She looketh well to the ways of her household, and eateth not the bread of idleness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 28, E'Her children arise up, and call her blessed; her husband also, and he praiseth her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 29, E'Many daughters have done virtuously, but thou excellest them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 30, E'Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 31, E'Give her of the fruit of her hands; and let her own works praise her in the gates.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 1, E'The words of the Preacher, the son of David, king in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 2, E'Vanity of vanities, saith the Preacher, vanity of vanities; all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 3, E'What profit hath a man of all his labour which he taketh under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 4, E'One generation passeth away, and another generation cometh: but the earth abideth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 5, E'The sun also ariseth, and the sun goeth down, and hasteth to his place where he arose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 6, E'The wind goeth toward the south, and turneth about unto the north; it whirleth about continually, and the wind returneth again according to his circuits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 7, E'All the rivers run into the sea; yet the sea is not full; unto the place from whence the rivers come, thither they return again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 8, E'All things are full of labour; man cannot utter it: the eye is not satisfied with seeing, nor the ear filled with hearing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 9, E'The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 10, E'Is there any thing whereof it may be said, See, this is new? it hath been already of old time, which was before us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 11, E'There is no remembrance of former things; neither shall there be any remembrance of things that are to come with those that shall come after.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 12, E'I the Preacher was king over Israel in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 13, E'And I gave my heart to seek and search out by wisdom concerning all things that are done under heaven: this sore travail hath God given to the sons of man to be exercised therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 14, E'I have seen all the works that are done under the sun; and, behold, all is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 15, E'That which is crooked cannot be made straight: and that which is wanting cannot be numbered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 16, E'I communed with mine own heart, saying, Lo, I am come to great estate, and have gotten more wisdom than all they that have been before me in Jerusalem: yea, my heart had great experience of wisdom and knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 17, E'And I gave my heart to know wisdom, and to know madness and folly: I perceived that this also is vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 18, E'For in much wisdom is much grief: and he that increaseth knowledge increaseth sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 1, E'I said in mine heart, Go to now, I will prove thee with mirth, therefore enjoy pleasure: and, behold, this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 2, E'I said of laughter, It is mad: and of mirth, What doeth it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 3, E'I sought in mine heart to give myself unto wine, yet acquainting mine heart with wisdom; and to lay hold on folly, till I might see what was that good for the sons of men, which they should do under the heaven all the days of their life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 4, E'I made me great works; I builded me houses; I planted me vineyards:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 5, E'I made me gardens and orchards, and I planted trees in them of all kind of fruits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 6, E'I made me pools of water, to water therewith the wood that bringeth forth trees:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 7, E'I got me servants and maidens, and had servants born in my house; also I had great possessions of great and small cattle above all that were in Jerusalem before me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 8, E'I gathered me also silver and gold, and the peculiar treasure of kings and of the provinces: I gat me men singers and women singers, and the delights of the sons of men, as musical instruments, and that of all sorts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 9, E'So I was great, and increased more than all that were before me in Jerusalem: also my wisdom remained with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 10, E'And whatsoever mine eyes desired I kept not from them, I withheld not my heart from any joy; for my heart rejoiced in all my labour: and this was my portion of all my labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 11, E'Then I looked on all the works that my hands had wrought, and on the labour that I had laboured to do: and, behold, all was vanity and vexation of spirit, and there was no profit under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 12, E'And I turned myself to behold wisdom, and madness, and folly: for what can the man do that cometh after the king? even that which hath been already done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 13, E'Then I saw that wisdom excelleth folly, as far as light excelleth darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 14, E'The wise man’s eyes are in his head; but the fool walketh in darkness: and I myself perceived also that one event happeneth to them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 15, E'Then said I in my heart, As it happeneth to the fool, so it happeneth even to me; and why was I then more wise? Then I said in my heart, that this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 16, E'For there is no remembrance of the wise more than of the fool for ever; seeing that which now is in the days to come shall all be forgotten. And how dieth the wise man? as the fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 17, E'Therefore I hated life; because the work that is wrought under the sun is grievous unto me: for all is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 18, E'Yea, I hated all my labour which I had taken under the sun: because I should leave it unto the man that shall be after me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 19, E'And who knoweth whether he shall be a wise man or a fool? yet shall he have rule over all my labour wherein I have laboured, and wherein I have shewed myself wise under the sun. This is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 20, E'Therefore I went about to cause my heart to despair of all the labour which I took under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 21, E'For there is a man whose labour is in wisdom, and in knowledge, and in equity; yet to a man that hath not laboured therein shall he leave it for his portion. This also is vanity and a great evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 22, E'For what hath man of all his labour, and of the vexation of his heart, wherein he hath laboured under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 23, E'For all his days are sorrows, and his travail grief; yea, his heart taketh not rest in the night. This is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 24, E'There is nothing better for a man, than that he should eat and drink, and that he should make his soul enjoy good in his labour. This also I saw, that it was from the hand of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 25, E'For who can eat, or who else can hasten hereunto, more than I?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 26, E'For God giveth to a man that is good in his sight wisdom, and knowledge, and joy: but to the sinner he giveth travail, to gather and to heap up, that he may give to him that is good before God. This also is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 1, E'To every thing there is a season, and a time to every purpose under the heaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 2, E'A time to be born, and a time to die; a time to plant, and a time to pluck up that which is planted;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 3, E'A time to kill, and a time to heal; a time to break down, and a time to build up;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 4, E'A time to weep, and a time to laugh; a time to mourn, and a time to dance;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 5, E'A time to cast away stones, and a time to gather stones together; a time to embrace, and a time to refrain from embracing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 6, E'A time to get, and a time to lose; a time to keep, and a time to cast away;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 7, E'A time to rend, and a time to sew; a time to keep silence, and a time to speak;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 8, E'A time to love, and a time to hate; a time of war, and a time of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 9, E'What profit hath he that worketh in that wherein he laboureth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 10, E'I have seen the travail, which God hath given to the sons of men to be exercised in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 11, E'He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 12, E'I know that there is no good in them, but for a man to rejoice, and to do good in his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 13, E'And also that every man should eat and drink, and enjoy the good of all his labour, it is the gift of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 14, E'I know that, whatsoever God doeth, it shall be for ever: nothing can be put to it, nor any thing taken from it: and God doeth it, that men should fear before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 15, E'That which hath been is now; and that which is to be hath already been; and God requireth that which is past.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 16, E'And moreover I saw under the sun the place of judgment, that wickedness was there; and the place of righteousness, that iniquity was there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 17, E'I said in mine heart, God shall judge the righteous and the wicked: for there is a time there for every purpose and for every work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 18, E'I said in mine heart concerning the estate of the sons of men, that God might manifest them, and that they might see that they themselves are beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 19, E'For that which befalleth the sons of men befalleth beasts; even one thing befalleth them: as the one dieth, so dieth the other; yea, they have all one breath; so that a man hath no preeminence above a beast: for all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 20, E'All go unto one place; all are of the dust, and all turn to dust again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 21, E'Who knoweth the spirit of man that goeth upward, and the spirit of the beast that goeth downward to the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 22, E'Wherefore I perceive that there is nothing better, than that a man should rejoice in his own works; for that is his portion: for who shall bring him to see what shall be after him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 1, E'So I returned, and considered all the oppressions that are done under the sun: and behold the tears of such as were oppressed, and they had no comforter; and on the side of their oppressors there was power; but they had no comforter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 2, E'Wherefore I praised the dead which are already dead more than the living which are yet alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 3, E'Yea, better is he than both they, which hath not yet been, who hath not seen the evil work that is done under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 4, E'Again, I considered all travail, and every right work, that for this a man is envied of his neighbour. This is also vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 5, E'The fool foldeth his hands together, and eateth his own flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 6, E'Better is an handful with quietness, than both the hands full with travail and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 7, E'Then I returned, and I saw vanity under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 8, E'There is one alone, and there is not a second; yea, he hath neither child nor brother: yet is there no end of all his labour; neither is his eye satisfied with riches; neither saith he, For whom do I labour, and bereave my soul of good? This is also vanity, yea, it is a sore travail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 9, E'Two are better than one; because they have a good reward for their labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 10, E'For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 11, E'Again, if two lie together, then they have heat: but how can one be warm alone?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 12, E'And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 13, E'Better is a poor and a wise child than an old and foolish king, who will no more be admonished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 14, E'For out of prison he cometh to reign; whereas also he that is born in his kingdom becometh poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 15, E'I considered all the living which walk under the sun, with the second child that shall stand up in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 16, E'There is no end of all the people, even of all that have been before them: they also that come after shall not rejoice in him. Surely this also is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 1, E'Keep thy foot when thou goest to the house of God, and be more ready to hear, than to give the sacrifice of fools: for they consider not that they do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 2, E'Be not rash with thy mouth, and let not thine heart be hasty to utter any thing before God: for God is in heaven, and thou upon earth: therefore let thy words be few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 3, E'For a dream cometh through the multitude of business; and a fool’s voice is known by multitude of words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 4, E'When thou vowest a vow unto God, defer not to pay it; for he hath no pleasure in fools: pay that which thou hast vowed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 5, E'Better is it that thou shouldest not vow, than that thou shouldest vow and not pay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 6, E'Suffer not thy mouth to cause thy flesh to sin; neither say thou before the angel, that it was an error: wherefore should God be angry at thy voice, and destroy the work of thine hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 7, E'For in the multitude of dreams and many words there are also divers vanities: but fear thou God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 8, E'If thou seest the oppression of the poor, and violent perverting of judgment and justice in a province, marvel not at the matter: for he that is higher than the highest regardeth; and there be higher than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 9, E'Moreover the profit of the earth is for all: the king himself is served by the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 10, E'He that loveth silver shall not be satisfied with silver; nor he that loveth abundance with increase: this is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 11, E'When goods increase, they are increased that eat them: and what good is there to the owners thereof, saving the beholding of them with their eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 12, E'The sleep of a labouring man is sweet, whether he eat little or much: but the abundance of the rich will not suffer him to sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 13, E'There is a sore evil which I have seen under the sun, namely, riches kept for the owners thereof to their hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 14, E'But those riches perish by evil travail: and he begetteth a son, and there is nothing in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 15, E'As he came forth of his mother’s womb, naked shall he return to go as he came, and shall take nothing of his labour, which he may carry away in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 16, E'And this also is a sore evil, that in all points as he came, so shall he go: and what profit hath he that hath laboured for the wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 17, E'All his days also he eateth in darkness, and he hath much sorrow and wrath with his sickness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 18, E'Behold that which I have seen: it is good and comely for one to eat and to drink, and to enjoy the good of all his labour that he taketh under the sun all the days of his life, which God giveth him: for it is his portion.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 19, E'Every man also to whom God hath given riches and wealth, and hath given him power to eat thereof, and to take his portion, and to rejoice in his labour; this is the gift of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 20, E'For he shall not much remember the days of his life; because God answereth him in the joy of his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 1, E'There is an evil which I have seen under the sun, and it is common among men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 2, E'A man to whom God hath given riches, wealth, and honour, so that he wanteth nothing for his soul of all that he desireth, yet God giveth him not power to eat thereof, but a stranger eateth it: this is vanity, and it is an evil disease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 3, E'If a man beget an hundred children, and live many years, so that the days of his years be many, and his soul be not filled with good, and also that he have no burial; I say, that an untimely birth is better than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 4, E'For he cometh in with vanity, and departeth in darkness, and his name shall be covered with darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 5, E'Moreover he hath not seen the sun, nor known any thing: this hath more rest than the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 6, E'Yea, though he live a thousand years twice told, yet hath he seen no good: do not all go to one place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 7, E'All the labour of man is for his mouth, and yet the appetite is not filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 8, E'For what hath the wise more than the fool? what hath the poor, that knoweth to walk before the living?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 9, E'Better is the sight of the eyes than the wandering of the desire: this is also vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 10, E'That which hath been is named already, and it is known that it is man: neither may he contend with him that is mightier than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 11, E'Seeing there be many things that increase vanity, what is man the better?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 12, E'For who knoweth what is good for man in this life, all the days of his vain life which he spendeth as a shadow? for who can tell a man what shall be after him under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 1, E'A good name is better than precious ointment; and the day of death than the day of one’s birth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 2, E'It is better to go to the house of mourning, than to go to the house of feasting: for that is the end of all men; and the living will lay it to his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 3, E'Sorrow is better than laughter: for by the sadness of the countenance the heart is made better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 4, E'The heart of the wise is in the house of mourning; but the heart of fools is in the house of mirth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 5, E'It is better to hear the rebuke of the wise, than for a man to hear the song of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 6, E'For as the crackling of thorns under a pot, so is the laughter of the fool: this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 7, E'Surely oppression maketh a wise man mad; and a gift destroyeth the heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 8, E'Better is the end of a thing than the beginning thereof: and the patient in spirit is better than the proud in spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 9, E'Be not hasty in thy spirit to be angry: for anger resteth in the bosom of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 10, E'Say not thou, What is the cause that the former days were better than these? for thou dost not enquire wisely concerning this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 11, E'Wisdom is good with an inheritance: and by it there is profit to them that see the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 12, E'For wisdom is a defence, and money is a defence: but the excellency of knowledge is, that wisdom giveth life to them that have it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 13, E'Consider the work of God: for who can make that straight, which he hath made crooked?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 14, E'In the day of prosperity be joyful, but in the day of adversity consider: God also hath set the one over against the other, to the end that man should find nothing after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 15, E'All things have I seen in the days of my vanity: there is a just man that perisheth in his righteousness, and there is a wicked man that prolongeth his life in his wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 16, E'Be not righteous over much; neither make thyself over wise: why shouldest thou destroy thyself ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 17, E'Be not over much wicked, neither be thou foolish: why shouldest thou die before thy time?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 18, E'It is good that thou shouldest take hold of this; yea, also from this withdraw not thine hand: for he that feareth God shall come forth of them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 19, E'Wisdom strengtheneth the wise more than ten mighty men which are in the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 20, E'For there is not a just man upon earth, that doeth good, and sinneth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 21, E'Also take no heed unto all words that are spoken; lest thou hear thy servant curse thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 22, E'For oftentimes also thine own heart knoweth that thou thyself likewise hast cursed others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 23, E'All this have I proved by wisdom: I said, I will be wise; but it was far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 24, E'That which is far off, and exceeding deep, who can find it out?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 25, E'I applied mine heart to know, and to search, and to seek out wisdom, and the reason of things, and to know the wickedness of folly, even of foolishness and madness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 26, E'And I find more bitter than death the woman, whose heart is snares and nets, and her hands as bands: whoso pleaseth God shall escape from her; but the sinner shall be taken by her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 27, E'Behold, this have I found, saith the preacher, counting one by one, to find out the account:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 28, E'Which yet my soul seeketh, but I find not: one man among a thousand have I found; but a woman among all those have I not found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 29, E'Lo, this only have I found, that God hath made man upright; but they have sought out many inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 1, E'Who is as the wise man? and who knoweth the interpretation of a thing? a man’s wisdom maketh his face to shine, and the boldness of his face shall be changed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 2, E'I counsel thee to keep the king’s commandment, and that in regard of the oath of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 3, E'Be not hasty to go out of his sight: stand not in an evil thing; for he doeth whatsoever pleaseth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 4, E'Where the word of a king is, there is power: and who may say unto him, What doest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 5, E'Whoso keepeth the commandment shall feel no evil thing: and a wise man’s heart discerneth both time and judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 6, E'Because to every purpose there is time and judgment, therefore the misery of man is great upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 7, E'For he knoweth not that which shall be: for who can tell him when it shall be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 8, E'There is no man that hath power over the spirit to retain the spirit; neither hath he power in the day of death: and there is no discharge in that war; neither shall wickedness deliver those that are given to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 9, E'All this have I seen, and applied my heart unto every work that is done under the sun: there is a time wherein one man ruleth over another to his own hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 10, E'And so I saw the wicked buried, who had come and gone from the place of the holy, and they were forgotten in the city where they had so done: this is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 11, E'Because sentence against an evil work is not executed speedily, therefore the heart of the sons of men is fully set in them to do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 12, E'Though a sinner do evil an hundred times, and his days be prolonged, yet surely I know that it shall be well with them that fear God, which fear before him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 13, E'But it shall not be well with the wicked, neither shall he prolong his days, which are as a shadow; because he feareth not before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 14, E'There is a vanity which is done upon the earth; that there be just men, unto whom it happeneth according to the work of the wicked; again, there be wicked men, to whom it happeneth according to the work of the righteous: I said that this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 15, E'Then I commended mirth, because a man hath no better thing under the sun, than to eat, and to drink, and to be merry: for that shall abide with him of his labour the days of his life, which God giveth him under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 16, E'When I applied mine heart to know wisdom, and to see the business that is done upon the earth: (for also there is that neither day nor night seeth sleep with his eyes:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 17, E'Then I beheld all the work of God, that a man cannot find out the work that is done under the sun: because though a man labour to seek it out, yet he shall not find it; yea farther; though a wise man think to know it, yet shall he not be able to find it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 1, E'For all this I considered in my heart even to declare all this, that the righteous, and the wise, and their works, are in the hand of God: no man knoweth either love or hatred by all that is before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 2, E'All things come alike to all: there is one event to the righteous, and to the wicked; to the good and to the clean, and to the unclean; to him that sacrificeth, and to him that sacrificeth not: as is the good, so is the sinner; and he that sweareth, as he that feareth an oath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 3, E'This is an evil among all things that are done under the sun, that there is one event unto all: yea, also the heart of the sons of men is full of evil, and madness is in their heart while they live, and after that they go to the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 4, E'For to him that is joined to all the living there is hope: for a living dog is better than a dead lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 5, E'For the living know that they shall die: but the dead know not any thing, neither have they any more a reward; for the memory of them is forgotten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 6, E'Also their love, and their hatred, and their envy, is now perished; neither have they any more a portion for ever in any thing that is done under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 7, E'Go thy way, eat thy bread with joy, and drink thy wine with a merry heart; for God now accepteth thy works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 8, E'Let thy garments be always white; and let thy head lack no ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 9, E'Live joyfully with the wife whom thou lovest all the days of the life of thy vanity, which he hath given thee under the sun, all the days of thy vanity: for that is thy portion in this life, and in thy labour which thou takest under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 10, E'Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 11, E'I returned, and saw under the sun, that the race is not to the swift, nor the battle to the strong, neither yet bread to the wise, nor yet riches to men of understanding, nor yet favour to men of skill; but time and chance happeneth to them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 12, E'For man also knoweth not his time: as the fishes that are taken in an evil net, and as the birds that are caught in the snare; so are the sons of men snared in an evil time, when it falleth suddenly upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 13, E'This wisdom have I seen also under the sun, and it seemed great unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 14, E'There was a little city, and few men within it; and there came a great king against it, and besieged it, and built great bulwarks against it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 15, E'Now there was found in it a poor wise man, and he by his wisdom delivered the city; yet no man remembered that same poor man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 16, E'Then said I, Wisdom is better than strength: nevertheless the poor man’s wisdom is despised, and his words are not heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 17, E'The words of wise men are heard in quiet more than the cry of him that ruleth among fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 18, E'Wisdom is better than weapons of war: but one sinner destroyeth much good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 1, E'Dead flies cause the ointment of the apothecary to send forth a stinking savour: so doth a little folly him that is in reputation for wisdom and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 2, E'A wise man’s heart is at his right hand; but a fool’s heart at his left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 3, E'Yea also, when he that is a fool walketh by the way, his wisdom faileth him, and he saith to every one that he is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 4, E'If the spirit of the ruler rise up against thee, leave not thy place; for yielding pacifieth great offences.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 5, E'There is an evil which I have seen under the sun, as an error which proceedeth from the ruler:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 6, E'Folly is set in great dignity, and the rich sit in low place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 7, E'I have seen servants upon horses, and princes walking as servants upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 8, E'He that diggeth a pit shall fall into it; and whoso breaketh an hedge, a serpent shall bite him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 9, E'Whoso removeth stones shall be hurt therewith; and he that cleaveth wood shall be endangered thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 10, E'If the iron be blunt, and he do not whet the edge, then must he put to more strength: but wisdom is profitable to direct.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 11, E'Surely the serpent will bite without enchantment; and a babbler is no better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 12, E'The words of a wise man’s mouth are gracious; but the lips of a fool will swallow up himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 13, E'The beginning of the words of his mouth is foolishness: and the end of his talk is mischievous madness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 14, E'A fool also is full of words: a man cannot tell what shall be; and what shall be after him, who can tell him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 15, E'The labour of the foolish wearieth every one of them, because he knoweth not how to go to the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 16, E'Woe to thee, O land, when thy king is a child, and thy princes eat in the morning!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 17, E'Blessed art thou, O land, when thy king is the son of nobles, and thy princes eat in due season, for strength, and not for drunkenness!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 18, E'By much slothfulness the building decayeth; and through idleness of the hands the house droppeth through.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 19, E'A feast is made for laughter, and wine maketh merry: but money answereth all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 20, E'Curse not the king, no not in thy thought; and curse not the rich in thy bedchamber: for a bird of the air shall carry the voice, and that which hath wings shall tell the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 1, E'Cast thy bread upon the waters: for thou shalt find it after many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 2, E'Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 3, E'If the clouds be full of rain, they empty themselves upon the earth: and if the tree fall toward the south, or toward the north, in the place where the tree falleth, there it shall be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 4, E'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 5, E'As thou knowest not what is the way of the spirit, nor how the bones do grow in the womb of her that is with child: even so thou knowest not the works of God who maketh all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 6, E'In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 7, E'Truly the light is sweet, and a pleasant thing it is for the eyes to behold the sun:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 8, E'But if a man live many years, and rejoice in them all; yet let him remember the days of darkness; for they shall be many. All that cometh is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 9, E'Rejoice, O young man, in thy youth; and let thy heart cheer thee in the days of thy youth, and walk in the ways of thine heart, and in the sight of thine eyes: but know thou, that for all these things God will bring thee into judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 10, E'Therefore remove sorrow from thy heart, and put away evil from thy flesh: for childhood and youth are vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 1, E'Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 2, E'While the sun, or the light, or the moon, or the stars, be not darkened, nor the clouds return after the rain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 3, E'In the day when the keepers of the house shall tremble, and the strong men shall bow themselves, and the grinders cease because they are few, and those that look out of the windows be darkened,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 4, E'And the doors shall be shut in the streets, when the sound of the grinding is low, and he shall rise up at the voice of the bird, and all the daughters of musick shall be brought low;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 5, E'Also when they shall be afraid of that which is high, and fears shall be in the way, and the almond tree shall flourish, and the grasshopper shall be a burden, and desire shall fail: because man goeth to his long home, and the mourners go about the streets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 6, E'Or ever the silver cord be loosed, or the golden bowl be broken, or the pitcher be broken at the fountain, or the wheel broken at the cistern.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 7, E'Then shall the dust return to the earth as it was: and the spirit shall return unto God who gave it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 8, E'Vanity of vanities, saith the preacher; all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 9, E'And moreover, because the preacher was wise, he still taught the people knowledge; yea, he gave good heed, and sought out, and set in order many proverbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 10, E'The preacher sought to find out acceptable words: and that which was written was upright, even words of truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 11, E'The words of the wise are as goads, and as nails fastened by the masters of assemblies, which are given from one shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 12, E'And further, by these, my son, be admonished: of making many books there is no end; and much study is a weariness of the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 13, E'Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 14, E'For God shall bring every work into judgment, with every secret thing, whether it be good, or whether it be evil.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 1, E'The song of songs, which is Solomon’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 2, E'Let him kiss me with the kisses of his mouth: for thy love is better than wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 3, E'Because of the savour of thy good ointments thy name is as ointment poured forth, therefore do the virgins love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 4, E'Draw me, we will run after thee: the king hath brought me into his chambers: we will be glad and rejoice in thee, we will remember thy love more than wine: the upright love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 5, E'I am black, but comely, O ye daughters of Jerusalem, as the tents of Kedar, as the curtains of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 6, E'Look not upon me, because I am black, because the sun hath looked upon me: my mother’s children were angry with me; they made me the keeper of the vineyards; but mine own vineyard have I not kept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 7, E'Tell me, O thou whom my soul loveth, where thou feedest, where thou makest thy flock to rest at noon: for why should I be as one that turneth aside by the flocks of thy companions?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 8, E'If thou know not, O thou fairest among women, go thy way forth by the footsteps of the flock, and feed thy kids beside the shepherds’ tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 9, E'I have compared thee, O my love, to a company of horses in Pharaoh’s chariots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 10, E'Thy cheeks are comely with rows of jewels, thy neck with chains of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 11, E'We will make thee borders of gold with studs of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 12, E'While the king sitteth at his table, my spikenard sendeth forth the smell thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 13, E'A bundle of myrrh is my well-beloved unto me; he shall lie all night betwixt my breasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 14, E'My beloved is unto me as a cluster of camphire in the vineyards of Engedi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 15, E'Behold, thou art fair, my love; behold, thou art fair; thou hast doves’ eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 16, E'Behold, thou art fair, my beloved, yea, pleasant: also our bed is green.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 17, E'The beams of our house are cedar, and our rafters of fir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 1, E'I am the rose of Sharon, and the lily of the valleys.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 2, E'As the lily among thorns, so is my love among the daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 3, E'As the apple tree among the trees of the wood, so is my beloved among the sons. I sat down under his shadow with great delight, and his fruit was sweet to my taste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 4, E'He brought me to the banqueting house, and his banner over me was love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 5, E'Stay me with flagons, comfort me with apples: for I am sick of love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 6, E'His left hand is under my head, and his right hand doth embrace me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 7, E'I charge you, O ye daughters of Jerusalem, by the roes, and by the hinds of the field, that ye stir not up, nor awake my love, till he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 8, E'The voice of my beloved! behold, he cometh leaping upon the mountains, skipping upon the hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 9, E'My beloved is like a roe or a young hart: behold, he standeth behind our wall, he looketh forth at the windows, shewing himself through the lattice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 10, E'My beloved spake, and said unto me, Rise up, my love, my fair one, and come away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 11, E'For, lo, the winter is past, the rain is over and gone;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 12, E'The flowers appear on the earth; the time of the singing of birds is come, and the voice of the turtle is heard in our land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 13, E'The fig tree putteth forth her green figs, and the vines with the tender grape give a good smell. Arise, my love, my fair one, and come away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 14, E'O my dove, that art in the clefts of the rock, in the secret places of the stairs, let me see thy countenance, let me hear thy voice; for sweet is thy voice, and thy countenance is comely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 15, E'Take us the foxes, the little foxes, that spoil the vines: for our vines have tender grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 16, E'My beloved is mine, and I am his: he feedeth among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 17, E'Until the day break, and the shadows flee away, turn, my beloved, and be thou like a roe or a young hart upon the mountains of Bether.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 1, E'By night on my bed I sought him whom my soul loveth: I sought him, but I found him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 2, E'I will rise now, and go about the city in the streets, and in the broad ways I will seek him whom my soul loveth: I sought him, but I found him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 3, E'The watchmen that go about the city found me: to whom I said, Saw ye him whom my soul loveth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 4, E'It was but a little that I passed from them, but I found him whom my soul loveth: I held him, and would not let him go, until I had brought him into my mother’s house, and into the chamber of her that conceived me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 5, E'I charge you, O ye daughters of Jerusalem, by the roes, and by the hinds of the field, that ye stir not up, nor awake my love, till he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 6, E'Who is this that cometh out of the wilderness like pillars of smoke, perfumed with myrrh and frankincense, with all powders of the merchant?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 7, E'Behold his bed, which is Solomon’s; threescore valiant men are about it, of the valiant of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 8, E'They all hold swords, being expert in war: every man hath his sword upon his thigh because of fear in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 9, E'King Solomon made himself a chariot of the wood of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 10, E'He made the pillars thereof of silver, the bottom thereof of gold, the covering of it of purple, the midst thereof being paved with love, for the daughters of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 11, E'Go forth, O ye daughters of Zion, and behold king Solomon with the crown wherewith his mother crowned him in the day of his espousals, and in the day of the gladness of his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 1, E'Behold, thou art fair, my love; behold, thou art fair; thou hast doves’ eyes within thy locks: thy hair is as a flock of goats, that appear from mount Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 2, E'Thy teeth are like a flock of sheep that are even shorn, which came up from the washing; whereof every one bear twins, and none is barren among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 3, E'Thy lips are like a thread of scarlet, and thy speech is comely: thy temples are like a piece of a pomegranate within thy locks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 4, E'Thy neck is like the tower of David builded for an armoury, whereon there hang a thousand bucklers, all shields of mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 5, E'Thy two breasts are like two young roes that are twins, which feed among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 6, E'Until the day break, and the shadows flee away, I will get me to the mountain of myrrh, and to the hill of frankincense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 7, E'Thou art all fair, my love; there is no spot in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 8, E'Come with me from Lebanon, my spouse, with me from Lebanon: look from the top of Amana, from the top of Shenir and Hermon, from the lions’ dens, from the mountains of the leopards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 9, E'Thou hast ravished my heart, my sister, my spouse; thou hast ravished my heart with one of thine eyes, with one chain of thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 10, E'How fair is thy love, my sister, my spouse! how much better is thy love than wine! and the smell of thine ointments than all spices!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 11, E'Thy lips, O my spouse, drop as the honeycomb: honey and milk are under thy tongue; and the smell of thy garments is like the smell of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 12, E'A garden inclosed is my sister, my spouse; a spring shut up, a fountain sealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 13, E'Thy plants are an orchard of pomegranates, with pleasant fruits; camphire, with spikenard,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 14, E'Spikenard and saffron; calamus and cinnamon, with all trees of frankincense; myrrh and aloes, with all the chief spices:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 15, E'A fountain of gardens, a well of living waters, and streams from Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 16, E'Awake, O north wind; and come, thou south; blow upon my garden, that the spices thereof may flow out. Let my beloved come into his garden, and eat his pleasant fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 1, E'I am come into my garden, my sister, my spouse: I have gathered my myrrh with my spice; I have eaten my honeycomb with my honey; I have drunk my wine with my milk: eat, O friends; drink, yea, drink abundantly, O beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 2, E'I sleep, but my heart waketh: it is the voice of my beloved that knocketh, saying, Open to me, my sister, my love, my dove, my undefiled: for my head is filled with dew, and my locks with the drops of the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 3, E'I have put off my coat; how shall I put it on? I have washed my feet; how shall I defile them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 4, E'My beloved put in his hand by the hole of the door, and my bowels were moved for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 5, E'I rose up to open to my beloved; and my hands dropped with myrrh, and my fingers with sweet smelling myrrh, upon the handles of the lock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 6, E'I opened to my beloved; but my beloved had withdrawn himself, and was gone: my soul failed when he spake: I sought him, but I could not find him; I called him, but he gave me no answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 7, E'The watchmen that went about the city found me, they smote me, they wounded me; the keepers of the walls took away my veil from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 8, E'I charge you, O daughters of Jerusalem, if ye find my beloved, that ye tell him, that I am sick of love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 9, E'What is thy beloved more than another beloved, O thou fairest among women? what is thy beloved more than another beloved, that thou dost so charge us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 10, E'My beloved is white and ruddy, the chiefest among ten thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 11, E'His head is as the most fine gold, his locks are bushy, and black as a raven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 12, E'His eyes are as the eyes of doves by the rivers of waters, washed with milk, and fitly set.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 13, E'His cheeks are as a bed of spices, as sweet flowers: his lips like lilies, dropping sweet smelling myrrh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 14, E'His hands are as gold rings set with the beryl: his belly is as bright ivory overlaid with sapphires.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 15, E'His legs are as pillars of marble, set upon sockets of fine gold: his countenance is as Lebanon, excellent as the cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 16, E'His mouth is most sweet: yea, he is altogether lovely. This is my beloved, and this is my friend, O daughters of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 1, E'Whither is thy beloved gone, O thou fairest among women? whither is thy beloved turned aside? that we may seek him with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 2, E'My beloved is gone down into his garden, to the beds of spices, to feed in the gardens, and to gather lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 3, E'I am my beloved’s, and my beloved is mine: he feedeth among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 4, E'Thou art beautiful, O my love, as Tirzah, comely as Jerusalem, terrible as an army with banners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 5, E'Turn away thine eyes from me, for they have overcome me: thy hair is as a flock of goats that appear from Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 6, E'Thy teeth are as a flock of sheep which go up from the washing, whereof every one beareth twins, and there is not one barren among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 7, E'As a piece of a pomegranate are thy temples within thy locks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 8, E'There are threescore queens, and fourscore concubines, and virgins without number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 9, E'My dove, my undefiled is but one; she is the only one of her mother, she is the choice one of her that bare her. The daughters saw her, and blessed her; yea, the queens and the concubines, and they praised her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 10, E'Who is she that looketh forth as the morning, fair as the moon, clear as the sun, and terrible as an army with banners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 11, E'I went down into the garden of nuts to see the fruits of the valley, and to see whether the vine flourished, and the pomegranates budded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 12, E'Or ever I was aware, my soul made me like the chariots of Amminadib.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 13, E'Return, return, O Shulamite; return, return, that we may look upon thee. What will ye see in the Shulamite? As it were the company of two armies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 1, E'How beautiful are thy feet with shoes, O prince’s daughter! the joints of thy thighs are like jewels, the work of the hands of a cunning workman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 2, E'Thy navel is like a round goblet, which wanteth not liquor: thy belly is like an heap of wheat set about with lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 3, E'Thy two breasts are like two young roes that are twins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 4, E'Thy neck is as a tower of ivory; thine eyes like the fishpools in Heshbon, by the gate of Bathrabbim: thy nose is as the tower of Lebanon which looketh toward Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 5, E'Thine head upon thee is like Carmel, and the hair of thine head like purple; the king is held in the galleries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 6, E'How fair and how pleasant art thou, O love, for delights!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 7, E'This thy stature is like to a palm tree, and thy breasts to clusters of grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 8, E'I said, I will go up to the palm tree, I will take hold of the boughs thereof: now also thy breasts shall be as clusters of the vine, and the smell of thy nose like apples;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 9, E'And the roof of thy mouth like the best wine for my beloved, that goeth down sweetly, causing the lips of those that are asleep to speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 10, E'I am my beloved’s, and his desire is toward me.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Song of Solomon') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 11, E'Come, my beloved, let us go forth into the field; let us lodge in the villages.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 12, E'Let us get up early to the vineyards; let us see if the vine flourish, whether the tender grape appear, and the pomegranates bud forth: there will I give thee my loves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 13, E'The mandrakes give a smell, and at our gates are all manner of pleasant fruits, new and old, which I have laid up for thee, O my beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 1, E'O that thou wert as my brother, that sucked the breasts of my mother! when I should find thee without, I would kiss thee; yea, I should not be despised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 2, E'I would lead thee, and bring thee into my mother’s house, who would instruct me: I would cause thee to drink of spiced wine of the juice of my pomegranate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 3, E'His left hand should be under my head, and his right hand should embrace me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 4, E'I charge you, O daughters of Jerusalem, that ye stir not up, nor awake my love, until he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 5, E'Who is this that cometh up from the wilderness, leaning upon her beloved? I raised thee up under the apple tree: there thy mother brought thee forth: there she brought thee forth that bare thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 6, E'Set me as a seal upon thine heart, as a seal upon thine arm: for love is strong as death; jealousy is cruel as the grave: the coals thereof are coals of fire, which hath a most vehement flame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 7, E'Many waters cannot quench love, neither can the floods drown it: if a man would give all the substance of his house for love, it would utterly be contemned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 8, E'We have a little sister, and she hath no breasts: what shall we do for our sister in the day when she shall be spoken for?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 9, E'If she be a wall, we will build upon her a palace of silver: and if she be a door, we will inclose her with boards of cedar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 10, E'I am a wall, and my breasts like towers: then was I in his eyes as one that found favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 11, E'Solomon had a vineyard at Baalhamon; he let out the vineyard unto keepers; every one for the fruit thereof was to bring a thousand pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 12, E'My vineyard, which is mine, is before me: thou, O Solomon, must have a thousand, and those that keep the fruit thereof two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 13, E'Thou that dwellest in the gardens, the companions hearken to thy voice: cause me to hear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 14, E'Make haste, my beloved, and be thou like to a roe or to a young hart upon the mountains of spices.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Song of Solomon') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 1, E'The vision of Isaiah the son of Amoz, which he saw concerning Judah and Jerusalem in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 2, E'Hear, O heavens, and give ear, O earth: for the LORD hath spoken, I have nourished and brought up children, and they have rebelled against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 3, E'The ox knoweth his owner, and the ass his master’s crib: but Israel doth not know, my people doth not consider.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 4, E'Ah sinful nation, a people laden with iniquity, a seed of evildoers, children that are corrupters: they have forsaken the LORD, they have provoked the Holy One of Israel unto anger, they are gone away backward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 5, E'Why should ye be stricken any more? ye will revolt more and more: the whole head is sick, and the whole heart faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 6, E'From the sole of the foot even unto the head there is no soundness in it; but wounds, and bruises, and putrifying sores: they have not been closed, neither bound up, neither mollified with ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 7, E'Your country is desolate, your cities are burned with fire: your land, strangers devour it in your presence, and it is desolate, as overthrown by strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 8, E'And the daughter of Zion is left as a cottage in a vineyard, as a lodge in a garden of cucumbers, as a besieged city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 9, E'Except the LORD of hosts had left unto us a very small remnant, we should have been as Sodom, and we should have been like unto Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 10, E'Hear the word of the LORD, ye rulers of Sodom; give ear unto the law of our God, ye people of Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 11, E'To what purpose is the multitude of your sacrifices unto me? saith the LORD: I am full of the burnt offerings of rams, and the fat of fed beasts; and I delight not in the blood of bullocks, or of lambs, or of he goats.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 12, E'When ye come to appear before me, who hath required this at your hand, to tread my courts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 13, E'Bring no more vain oblations; incense is an abomination unto me; the new moons and sabbaths, the calling of assemblies, I cannot away with; it is iniquity, even the solemn meeting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 14, E'Your new moons and your appointed feasts my soul hateth: they are a trouble unto me; I am weary to bear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 15, E'And when ye spread forth your hands, I will hide mine eyes from you: yea, when ye make many prayers, I will not hear: your hands are full of blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 16, E'Wash you, make you clean; put away the evil of your doings from before mine eyes; cease to do evil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 17, E'Learn to do well; seek judgment, relieve the oppressed, judge the fatherless, plead for the widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 18, E'Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 19, E'If ye be willing and obedient, ye shall eat the good of the land:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 20, E'But if ye refuse and rebel, ye shall be devoured with the sword: for the mouth of the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 21, E'How is the faithful city become an harlot! it was full of judgment; righteousness lodged in it; but now murderers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 22, E'Thy silver is become dross, thy wine mixed with water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 23, E'Thy princes are rebellious, and companions of thieves: every one loveth gifts, and followeth after rewards: they judge not the fatherless, neither doth the cause of the widow come unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 24, E'Therefore saith the LORD, the LORD of hosts, the mighty One of Israel, Ah, I will ease me of mine adversaries, and avenge me of mine enemies:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 25, E'And I will turn my hand upon thee, and purely purge away thy dross, and take away all thy tin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 26, E'And I will restore thy judges as at the first, and thy counsellors as at the beginning: afterward thou shalt be called, The city of righteousness, the faithful city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 27, E'Zion shall be redeemed with judgment, and her converts with righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 28, E'And the destruction of the transgressors and of the sinners shall be together, and they that forsake the LORD shall be consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 29, E'For they shall be ashamed of the oaks which ye have desired, and ye shall be confounded for the gardens that ye have chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 30, E'For ye shall be as an oak whose leaf fadeth, and as a garden that hath no water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 31, E'And the strong shall be as tow, and the maker of it as a spark, and they shall both burn together, and none shall quench them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 1, E'The word that Isaiah the son of Amoz saw concerning Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 2, E'And it shall come to pass in the last days, that the mountain of the LORD’s house shall be established in the top of the mountains, and shall be exalted above the hills; and all nations shall flow unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 3, E'And many people shall go and say, Come ye, and let us go up to the mountain of the LORD, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths: for out of Zion shall go forth the law, and the word of the LORD from Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 4, E'And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 5, E'O house of Jacob, come ye, and let us walk in the light of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 6, E'Therefore thou hast forsaken thy people the house of Jacob, because they be replenished from the east, and are soothsayers like the Philistines, and they please themselves in the children of strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 7, E'Their land also is full of silver and gold, neither is there any end of their treasures; their land is also full of horses, neither is there any end of their chariots:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 8, E'Their land also is full of idols; they worship the work of their own hands, that which their own fingers have made:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 9, E'And the mean man boweth down, and the great man humbleth himself: therefore forgive them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 10, E'Enter into the rock, and hide thee in the dust, for fear of the LORD, and for the glory of his majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 11, E'The lofty looks of man shall be humbled, and the haughtiness of men shall be bowed down, and the LORD alone shall be exalted in that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 12, E'For the day of the LORD of hosts shall be upon every one that is proud and lofty, and upon every one that is lifted up; and he shall be brought low:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 13, E'And upon all the cedars of Lebanon, that are high and lifted up, and upon all the oaks of Bashan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 14, E'And upon all the high mountains, and upon all the hills that are lifted up,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 15, E'And upon every high tower, and upon every fenced wall,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 16, E'And upon all the ships of Tarshish, and upon all pleasant pictures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 17, E'And the loftiness of man shall be bowed down, and the haughtiness of men shall be made low: and the LORD alone shall be exalted in that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 18, E'And the idols he shall utterly abolish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 19, E'And they shall go into the holes of the rocks, and into the caves of the earth, for fear of the LORD, and for the glory of his majesty, when he ariseth to shake terribly the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 20, E'In that day a man shall cast his idols of silver, and his idols of gold, which they made each one for himself to worship, to the moles and to the bats;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 21, E'To go into the clefts of the rocks, and into the tops of the ragged rocks, for fear of the LORD, and for the glory of his majesty, when he ariseth to shake terribly the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 22, E'Cease ye from man, whose breath is in his nostrils: for wherein is he to be accounted of ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 1, E'For, behold, the Lord, the LORD of hosts, doth take away from Jerusalem and from Judah the stay and the staff, the whole stay of bread, and the whole stay of water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 2, E'The mighty man, and the man of war, the judge, and the prophet, and the prudent, and the ancient,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 3, E'The captain of fifty, and the honourable man, and the counsellor, and the cunning artificer, and the eloquent orator.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 4, E'And I will give children to be their princes, and babes shall rule over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 5, E'And the people shall be oppressed, every one by another, and every one by his neighbour: the child shall behave himself proudly against the ancient, and the base against the honourable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 6, E'When a man shall take hold of his brother of the house of his father, saying, Thou hast clothing, be thou our ruler, and let this ruin be under thy hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 7, E'In that day shall he swear, saying, I will not be an healer; for in my house is neither bread nor clothing: make me not a ruler of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 8, E'For Jerusalem is ruined, and Judah is fallen: because their tongue and their doings are against the LORD, to provoke the eyes of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 9, E'The shew of their countenance doth witness against them; and they declare their sin as Sodom, they hide it not. Woe unto their soul! for they have rewarded evil unto themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 10, E'Say ye to the righteous, that it shall be well with him: for they shall eat the fruit of their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 11, E'Woe unto the wicked! it shall be ill with him: for the reward of his hands shall be given him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 12, E'As for my people, children are their oppressors, and women rule over them. O my people, they which lead thee cause thee to err, and destroy the way of thy paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 13, E'The LORD standeth up to plead, and standeth to judge the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 14, E'The LORD will enter into judgment with the ancients of his people, and the princes thereof: for ye have eaten up the vineyard; the spoil of the poor is in your houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 15, E'What mean ye that ye beat my people to pieces, and grind the faces of the poor? saith the Lord GOD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 16, E'Moreover the LORD saith, Because the daughters of Zion are haughty, and walk with stretched forth necks and wanton eyes, walking and mincing as they go, and making a tinkling with their feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 17, E'Therefore the LORD will smite with a scab the crown of the head of the daughters of Zion, and the LORD will discover their secret parts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 18, E'In that day the Lord will take away the bravery of their tinkling ornaments about their feet, and their cauls, and their round tires like the moon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 19, E'The chains, and the bracelets, and the mufflers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 20, E'The bonnets, and the ornaments of the legs, and the headbands, and the tablets, and the earrings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 21, E'The rings, and nose jewels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 22, E'The changeable suits of apparel, and the mantles, and the wimples, and the crisping pins,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 23, E'The glasses, and the fine linen, and the hoods, and the vails.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 24, E'And it shall come to pass, that instead of sweet smell there shall be stink; and instead of a girdle a rent; and instead of well set hair baldness; and instead of a stomacher a girding of sackcloth; and burning instead of beauty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 25, E'Thy men shall fall by the sword, and thy mighty in the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 26, E'And her gates shall lament and mourn; and she being desolate shall sit upon the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 1, E'And in that day seven women shall take hold of one man, saying, We will eat our own bread, and wear our own apparel: only let us be called by thy name, to take away our reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 2, E'In that day shall the branch of the LORD be beautiful and glorious, and the fruit of the earth shall be excellent and comely for them that are escaped of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 3, E'And it shall come to pass, that he that is left in Zion, and he that remaineth in Jerusalem, shall be called holy, even every one that is written among the living in Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 4, E'When the Lord shall have washed away the filth of the daughters of Zion, and shall have purged the blood of Jerusalem from the midst thereof by the spirit of judgment, and by the spirit of burning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 5, E'And the LORD will create upon every dwelling place of mount Zion, and upon her assemblies, a cloud and smoke by day, and the shining of a flaming fire by night: for upon all the glory shall be a defence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 6, E'And there shall be a tabernacle for a shadow in the day time from the heat, and for a place of refuge, and for a covert from storm and from rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 1, E'Now will I sing to my wellbeloved a song of my beloved touching his vineyard. My wellbeloved hath a vineyard in a very fruitful hill:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 2, E'And he fenced it, and gathered out the stones thereof, and planted it with the choicest vine, and built a tower in the midst of it, and also made a winepress therein: and he looked that it should bring forth grapes, and it brought forth wild grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 3, E'And now, O inhabitants of Jerusalem, and men of Judah, judge, I pray you, betwixt me and my vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 4, E'What could have been done more to my vineyard, that I have not done in it? wherefore, when I looked that it should bring forth grapes, brought it forth wild grapes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 5, E'And now go to; I will tell you what I will do to my vineyard: I will take away the hedge thereof, and it shall be eaten up; and break down the wall thereof, and it shall be trodden down:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 6, E'And I will lay it waste: it shall not be pruned, nor digged; but there shall come up briers and thorns: I will also command the clouds that they rain no rain upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 7, E'For the vineyard of the LORD of hosts is the house of Israel, and the men of Judah his pleasant plant: and he looked for judgment, but behold oppression; for righteousness, but behold a cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 8, E'Woe unto them that join house to house, that lay field to field, till there be no place, that they may be placed alone in the midst of the earth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 9, E'In mine ears said the LORD of hosts, Of a truth many houses shall be desolate, even great and fair, without inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 10, E'Yea, ten acres of vineyard shall yield one bath, and the seed of an homer shall yield an ephah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 11, E'Woe unto them that rise up early in the morning, that they may follow strong drink; that continue until night, till wine inflame them!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 12, E'And the harp, and the viol, the tabret, and pipe, and wine, are in their feasts: but they regard not the work of the LORD, neither consider the operation of his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 13, E'Therefore my people are gone into captivity, because they have no knowledge: and their honourable men are famished, and their multitude dried up with thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 14, E'Therefore hell hath enlarged herself, and opened her mouth without measure: and their glory, and their multitude, and their pomp, and he that rejoiceth, shall descend into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 15, E'And the mean man shall be brought down, and the mighty man shall be humbled, and the eyes of the lofty shall be humbled:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 16, E'But the LORD of hosts shall be exalted in judgment, and God that is holy shall be sanctified in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 17, E'Then shall the lambs feed after their manner, and the waste places of the fat ones shall strangers eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 18, E'Woe unto them that draw iniquity with cords of vanity, and sin as it were with a cart rope:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 19, E'That say, Let him make speed, and hasten his work, that we may see it: and let the counsel of the Holy One of Israel draw nigh and come, that we may know it!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 20, E'Woe unto them that call evil good, and good evil; that put darkness for light, and light for darkness; that put bitter for sweet, and sweet for bitter!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 21, E'Woe unto them that are wise in their own eyes, and prudent in their own sight!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 22, E'Woe unto them that are mighty to drink wine, and men of strength to mingle strong drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 23, E'Which justify the wicked for reward, and take away the righteousness of the righteous from him!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 24, E'Therefore as the fire devoureth the stubble, and the flame consumeth the chaff, so their root shall be as rottenness, and their blossom shall go up as dust: because they have cast away the law of the LORD of hosts, and despised the word of the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 25, E'Therefore is the anger of the LORD kindled against his people, and he hath stretched forth his hand against them, and hath smitten them: and the hills did tremble, and their carcases were torn in the midst of the streets. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 26, E'And he will lift up an ensign to the nations from far, and will hiss unto them from the end of the earth: and, behold, they shall come with speed swiftly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 27, E'None shall be weary nor stumble among them; none shall slumber nor sleep; neither shall the girdle of their loins be loosed, nor the latchet of their shoes be broken:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 28, E'Whose arrows are sharp, and all their bows bent, their horses’ hoofs shall be counted like flint, and their wheels like a whirlwind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 29, E'Their roaring shall be like a lion, they shall roar like young lions: yea, they shall roar, and lay hold of the prey, and shall carry it away safe, and none shall deliver it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 30, E'And in that day they shall roar against them like the roaring of the sea: and if one look unto the land, behold darkness and sorrow, and the light is darkened in the heavens thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 1, E'In the year that king Uzziah died I saw also the LORD sitting upon a throne, high and lifted up, and his train filled the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 2, E'Above it stood the seraphims: each one had six wings; with twain he covered his face, and with twain he covered his feet, and with twain he did fly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 3, E'And one cried unto another, and said, Holy, holy, holy, is the LORD of hosts: the whole earth is full of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 4, E'And the posts of the door moved at the voice of him that cried, and the house was filled with smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 5, E'Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for mine eyes have seen the King, the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 6, E'Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 7, E'And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 8, E'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 9, E'And he said, Go, and tell this people, Hear ye indeed, but understand not; and see ye indeed, but perceive not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 10, E'Make the heart of this people fat, and make their ears heavy, and shut their eyes; lest they see with their eyes, and hear with their ears, and understand with their heart, and convert, and be healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 11, E'Then said I, Lord, how long? And he answered, Until the cities be wasted without inhabitant, and the houses without man, and the land be utterly desolate,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 12, E'And the LORD have removed men far away, and there be a great forsaking in the midst of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 13, E'But yet in it shall be a tenth, and it shall return, and shall be eaten: as a teil tree, and as an oak, whose substance is in them, when they cast their leaves: so the holy seed shall be the substance thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 1, E'And it came to pass in the days of Ahaz the son of Jotham, the son of Uzziah, king of Judah, that Rezin the king of Syria, and Pekah the son of Remaliah, king of Israel, went up toward Jerusalem to war against it, but could not prevail against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 2, E'And it was told the house of David, saying, Syria is confederate with Ephraim. And his heart was moved, and the heart of his people, as the trees of the wood are moved with the wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 3, E'Then said the LORD unto Isaiah, Go forth now to meet Ahaz, thou, and Shearjashub thy son, at the end of the conduit of the upper pool in the highway of the fuller’s field;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 4, E'And say unto him, Take heed, and be quiet; fear not, neither be fainthearted for the two tails of these smoking firebrands, for the fierce anger of Rezin with Syria, and of the son of Remaliah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 5, E'Because Syria, Ephraim, and the son of Remaliah, have taken evil counsel against thee, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 6, E'Let us go up against Judah, and vex it, and let us make a breach therein for us, and set a king in the midst of it, even the son of Tabeal:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 7, E'Thus saith the Lord GOD, It shall not stand, neither shall it come to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 8, E'For the head of Syria is Damascus, and the head of Damascus is Rezin; and within threescore and five years shall Ephraim be broken, that it be not a people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 9, E'And the head of Ephraim is Samaria, and the head of Samaria is Remaliah’s son. If ye will not believe, surely ye shall not be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 10, E'Moreover the LORD spake again unto Ahaz, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 11, E'Ask thee a sign of the LORD thy God; ask it either in the depth, or in the height above.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 12, E'But Ahaz said, I will not ask, neither will I tempt the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 13, E'And he said, Hear ye now, O house of David; Is it a small thing for you to weary men, but will ye weary my God also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 14, E'Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 15, E'Butter and honey shall he eat, that he may know to refuse the evil, and choose the good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 16, E'For before the child shall know to refuse the evil, and choose the good, the land that thou abhorrest shall be forsaken of both her kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 17, E'The LORD shall bring upon thee, and upon thy people, and upon thy father’s house, days that have not come, from the day that Ephraim departed from Judah; even the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 18, E'And it shall come to pass in that day, that the LORD shall hiss for the fly that is in the uttermost part of the rivers of Egypt, and for the bee that is in the land of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 19, E'And they shall come, and shall rest all of them in the desolate valleys, and in the holes of the rocks, and upon all thorns, and upon all bushes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 20, E'In the same day shall the Lord shave with a razor that is hired, namely, by them beyond the river, by the king of Assyria, the head, and the hair of the feet: and it shall also consume the beard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 21, E'And it shall come to pass in that day, that a man shall nourish a young cow, and two sheep;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 22, E'And it shall come to pass, for the abundance of milk that they shall give he shall eat butter: for butter and honey shall every one eat that is left in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 23, E'And it shall come to pass in that day, that every place shall be, where there were a thousand vines at a thousand silverlings, it shall even be for briers and thorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 24, E'With arrows and with bows shall men come thither; because all the land shall become briers and thorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 25, E'And on all hills that shall be digged with the mattock, there shall not come thither the fear of briers and thorns: but it shall be for the sending forth of oxen, and for the treading of lesser cattle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 1, E'Moreover the LORD said unto me, Take thee a great roll, and write in it with a man’s pen concerning Mahershalalhashbaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 2, E'And I took unto me faithful witnesses to record, Uriah the priest, and Zechariah the son of Jeberechiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 3, E'And I went unto the prophetess; and she conceived, and bare a son. Then said the LORD to me, Call his name Mahershalalhashbaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 4, E'For before the child shall have knowledge to cry, My father, and my mother, the riches of Damascus and the spoil of Samaria shall be taken away before the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 5, E'The LORD spake also unto me again, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 6, E'Forasmuch as this people refuseth the waters of Shiloah that go softly, and rejoice in Rezin and Remaliah’s son;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 7, E'Now therefore, behold, the Lord bringeth up upon them the waters of the river, strong and many, even the king of Assyria, and all his glory: and he shall come up over all his channels, and go over all his banks:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 8, E'And he shall pass through Judah; he shall overflow and go over, he shall reach even to the neck; and the stretching out of his wings shall fill the breadth of thy land, O Immanuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 9, E'Associate yourselves, O ye people, and ye shall be broken in pieces; and give ear, all ye of far countries: gird yourselves, and ye shall be broken in pieces; gird yourselves, and ye shall be broken in pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 10, E'Take counsel together, and it shall come to nought; speak the word, and it shall not stand: for God is with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 11, E'For the LORD spake thus to me with a strong hand, and instructed me that I should not walk in the way of this people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 12, E'Say ye not, A confederacy, to all them to whom this people shall say, A confederacy; neither fear ye their fear, nor be afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 13, E'Sanctify the LORD of hosts himself; and let him be your fear, and let him be your dread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 14, E'And he shall be for a sanctuary; but for a stone of stumbling and for a rock of offence to both the houses of Israel, for a gin and for a snare to the inhabitants of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 15, E'And many among them shall stumble, and fall, and be broken, and be snared, and be taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 16, E'Bind up the testimony, seal the law among my disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 17, E'And I will wait upon the LORD, that hideth his face from the house of Jacob, and I will look for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 18, E'Behold, I and the children whom the LORD hath given me are for signs and for wonders in Israel from the LORD of hosts, which dwelleth in mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 19, E'And when they shall say unto you, Seek unto them that have familiar spirits, and unto wizards that peep, and that mutter: should not a people seek unto their God? for the living to the dead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 20, E'To the law and to the testimony: if they speak not according to this word, it is because there is no light in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 21, E'And they shall pass through it, hardly bestead and hungry: and it shall come to pass, that when they shall be hungry, they shall fret themselves, and curse their king and their God, and look upward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 22, E'And they shall look unto the earth; and behold trouble and darkness, dimness of anguish; and they shall be driven to darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 1, E'Nevertheless the dimness shall not be such as was in her vexation, when at the first he lightly afflicted the land of Zebulun and the land of Naphtali, and afterward did more grievously afflict her by the way of the sea, beyond Jordan, in Galilee of the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 2, E'The people that walked in darkness have seen a great light: they that dwell in the land of the shadow of death, upon them hath the light shined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 3, E'Thou hast multiplied the nation, and not increased the joy: they joy before thee according to the joy in harvest, and as men rejoice when they divide the spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 4, E'For thou hast broken the yoke of his burden, and the staff of his shoulder, the rod of his oppressor, as in the day of Midian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 5, E'For every battle of the warrior is with confused noise, and garments rolled in blood; but this shall be with burning and fuel of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 6, E'For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 7, E'Of the increase of his government and peace there shall be no end, upon the throne of David, and upon his kingdom, to order it, and to establish it with judgment and with justice from henceforth even for ever. The zeal of the LORD of hosts will perform this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 8, E'The Lord sent a word into Jacob, and it hath lighted upon Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 9, E'And all the people shall know, even Ephraim and the inhabitant of Samaria, that say in the pride and stoutness of heart,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 10, E'The bricks are fallen down, but we will build with hewn stones: the sycomores are cut down, but we will change them into cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 11, E'Therefore the LORD shall set up the adversaries of Rezin against him, and join his enemies together;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 12, E'The Syrians before, and the Philistines behind; and they shall devour Israel with open mouth. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 13, E'For the people turneth not unto him that smiteth them, neither do they seek the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 14, E'Therefore the LORD will cut off from Israel head and tail, branch and rush, in one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 15, E'The ancient and honourable, he is the head; and the prophet that teacheth lies, he is the tail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 16, E'For the leaders of this people cause them to err; and they that are led of them are destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 17, E'Therefore the LORD shall have no joy in their young men, neither shall have mercy on their fatherless and widows: for every one is an hypocrite and an evildoer, and every mouth speaketh folly. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 18, E'For wickedness burneth as the fire: it shall devour the briers and thorns, and shall kindle in the thickets of the forest, and they shall mount up like the lifting up of smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 19, E'Through the wrath of the LORD of hosts is the land darkened, and the people shall be as the fuel of the fire: no man shall spare his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 20, E'And he shall snatch on the right hand, and be hungry; and he shall eat on the left hand, and they shall not be satisfied: they shall eat every man the flesh of his own arm:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 21, E'Manasseh, Ephraim; and Ephraim, Manasseh: and they together shall be against Judah. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 1, E'Woe unto them that decree unrighteous decrees, and that write grievousness which they have prescribed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 2, E'To turn aside the needy from judgment, and to take away the right from the poor of my people, that widows may be their prey, and that they may rob the fatherless!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 3, E'And what will ye do in the day of visitation, and in the desolation which shall come from far? to whom will ye flee for help? and where will ye leave your glory?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 4, E'Without me they shall bow down under the prisoners, and they shall fall under the slain. For all this his anger is not turned away, but his hand is stretched out still.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 5, E'O Assyrian, the rod of mine anger, and the staff in their hand is mine indignation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 6, E'I will send him against an hypocritical nation, and against the people of my wrath will I give him a charge, to take the spoil, and to take the prey, and to tread them down like the mire of the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 7, E'Howbeit he meaneth not so, neither doth his heart think so; but it is in his heart to destroy and cut off nations not a few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 8, E'For he saith, Are not my princes altogether kings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 9, E'Is not Calno as Carchemish? is not Hamath as Arpad? is not Samaria as Damascus?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 10, E'As my hand hath found the kingdoms of the idols, and whose graven images did excel them of Jerusalem and of Samaria;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 11, E'Shall I not, as I have done unto Samaria and her idols, so do to Jerusalem and her idols?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 12, E'Wherefore it shall come to pass, that when the Lord hath performed his whole work upon mount Zion and on Jerusalem, I will punish the fruit of the stout heart of the king of Assyria, and the glory of his high looks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 13, E'For he saith, By the strength of my hand I have done it, and by my wisdom; for I am prudent: and I have removed the bounds of the people, and have robbed their treasures, and I have put down the inhabitants like a valiant man:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 14, E'And my hand hath found as a nest the riches of the people: and as one gathereth eggs that are left, have I gathered all the earth; and there was none that moved the wing, or opened the mouth, or peeped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 15, E'Shall the axe boast itself against him that heweth therewith? or shall the saw magnify itself against him that shaketh it? as if the rod should shake itself against them that lift it up, or as if the staff should lift up itself, as if it were no wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 16, E'Therefore shall the Lord, the Lord of hosts, send among his fat ones leanness; and under his glory he shall kindle a burning like the burning of a fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 17, E'And the light of Israel shall be for a fire, and his Holy One for a flame: and it shall burn and devour his thorns and his briers in one day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 18, E'And shall consume the glory of his forest, and of his fruitful field, both soul and body: and they shall be as when a standard-bearer fainteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 19, E'And the rest of the trees of his forest shall be few, that a child may write them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 20, E'And it shall come to pass in that day, that the remnant of Israel, and such as are escaped of the house of Jacob, shall no more again stay upon him that smote them; but shall stay upon the LORD, the Holy One of Israel, in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 21, E'The remnant shall return, even the remnant of Jacob, unto the mighty God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 22, E'For though thy people Israel be as the sand of the sea, yet a remnant of them shall return: the consumption decreed shall overflow with righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 23, E'For the Lord GOD of hosts shall make a consumption, even determined, in the midst of all the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 24, E'Therefore thus saith the Lord GOD of hosts, O my people that dwellest in Zion, be not afraid of the Assyrian: he shall smite thee with a rod, and shall lift up his staff against thee, after the manner of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 25, E'For yet a very little while, and the indignation shall cease, and mine anger in their destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 26, E'And the LORD of hosts shall stir up a scourge for him according to the slaughter of Midian at the rock of Oreb: and as his rod was upon the sea, so shall he lift it up after the manner of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 27, E'And it shall come to pass in that day, that his burden shall be taken away from off thy shoulder, and his yoke from off thy neck, and the yoke shall be destroyed because of the anointing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 28, E'He is come to Aiath, he is passed to Migron; at Michmash he hath laid up his carriages:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 29, E'They are gone over the passage: they have taken up their lodging at Geba; Ramah is afraid; Gibeah of Saul is fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 30, E'Lift up thy voice, O daughter of Gallim: cause it to be heard unto Laish, O poor Anathoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 31, E'Madmenah is removed; the inhabitants of Gebim gather themselves to flee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 32, E'As yet shall he remain at Nob that day: he shall shake his hand against the mount of the daughter of Zion, the hill of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 33, E'Behold, the Lord, the LORD of hosts, shall lop the bough with terror: and the high ones of stature shall be hewn down, and the haughty shall be humbled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 34, E'And he shall cut down the thickets of the forest with iron, and Lebanon shall fall by a mighty one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 1, E'And there shall come forth a rod out of the stem of Jesse, and a Branch shall grow out of his roots:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 2, E'And the spirit of the LORD shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the LORD;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 3, E'And shall make him of quick understanding in the fear of the LORD: and he shall not judge after the sight of his eyes, neither reprove after the hearing of his ears:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 4, E'But with righteousness shall he judge the poor, and reprove with equity for the meek of the earth: and he shall smite the earth with the rod of his mouth, and with the breath of his lips shall he slay the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 5, E'And righteousness shall be the girdle of his loins, and faithfulness the girdle of his reins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 6, E'The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 7, E'And the cow and the bear shall feed; their young ones shall lie down together: and the lion shall eat straw like the ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 8, E'And the sucking child shall play on the hole of the asp, and the weaned child shall put his hand on the cockatrice’ den.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 9, E'They shall not hurt nor destroy in all my holy mountain: for the earth shall be full of the knowledge of the LORD, as the waters cover the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 10, E'And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 11, E'And it shall come to pass in that day, that the Lord shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 12, E'And he shall set up an ensign for the nations, and shall assemble the outcasts of Israel, and gather together the dispersed of Judah from the four corners of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 13, E'The envy also of Ephraim shall depart, and the adversaries of Judah shall be cut off: Ephraim shall not envy Judah, and Judah shall not vex Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 14, E'But they shall fly upon the shoulders of the Philistines toward the west; they shall spoil them of the east together: they shall lay their hand upon Edom and Moab; and the children of Ammon shall obey them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 15, E'And the LORD shall utterly destroy the tongue of the Egyptian sea; and with his mighty wind shall he shake his hand over the river, and shall smite it in the seven streams, and make men go over dryshod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 16, E'And there shall be an highway for the remnant of his people, which shall be left, from Assyria; like as it was to Israel in the day that he came up out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 1, E'And in that day thou shalt say, O LORD, I will praise thee: though thou wast angry with me, thine anger is turned away, and thou comfortedst me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 2, E'Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 3, E'Therefore with joy shall ye draw water out of the wells of salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 4, E'And in that day shall ye say, Praise the LORD, call upon his name, declare his doings among the people, make mention that his name is exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 5, E'Sing unto the LORD; for he hath done excellent things: this is known in all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 6, E'Cry out and shout, thou inhabitant of Zion: for great is the Holy One of Israel in the midst of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 1, E'The burden of Babylon, which Isaiah the son of Amoz did see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 2, E'Lift ye up a banner upon the high mountain, exalt the voice unto them, shake the hand, that they may go into the gates of the nobles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 3, E'I have commanded my sanctified ones, I have also called my mighty ones for mine anger, even them that rejoice in my highness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 4, E'The noise of a multitude in the mountains, like as of a great people; a tumultuous noise of the kingdoms of nations gathered together: the LORD of hosts mustereth the host of the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 5, E'They come from a far country, from the end of heaven, even the LORD, and the weapons of his indignation, to destroy the whole land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 6, E'Howl ye; for the day of the LORD is at hand; it shall come as a destruction from the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 7, E'Therefore shall all hands be faint, and every man’s heart shall melt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 8, E'And they shall be afraid: pangs and sorrows shall take hold of them; they shall be in pain as a woman that travaileth: they shall be amazed one at another; their faces shall be as flames.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 9, E'Behold, the day of the LORD cometh, cruel both with wrath and fierce anger, to lay the land desolate: and he shall destroy the sinners thereof out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 10, E'For the stars of heaven and the constellations thereof shall not give their light: the sun shall be darkened in his going forth, and the moon shall not cause her light to shine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 11, E'And I will punish the world for their evil, and the wicked for their iniquity; and I will cause the arrogancy of the proud to cease, and will lay low the haughtiness of the terrible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 12, E'I will make a man more precious than fine gold; even a man than the golden wedge of Ophir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 13, E'Therefore I will shake the heavens, and the earth shall remove out of her place, in the wrath of the LORD of hosts, and in the day of his fierce anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 14, E'And it shall be as the chased roe, and as a sheep that no man taketh up: they shall every man turn to his own people, and flee every one into his own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 15, E'Every one that is found shall be thrust through; and every one that is joined unto them shall fall by the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 16, E'Their children also shall be dashed to pieces before their eyes; their houses shall be spoiled, and their wives ravished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 17, E'Behold, I will stir up the Medes against them, which shall not regard silver; and as for gold, they shall not delight in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 18, E'Their bows also shall dash the young men to pieces; and they shall have no pity on the fruit of the womb; their eye shall not spare children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 19, E'And Babylon, the glory of kingdoms, the beauty of the Chaldees’ excellency, shall be as when God overthrew Sodom and Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 20, E'It shall never be inhabited, neither shall it be dwelt in from generation to generation: neither shall the Arabian pitch tent there; neither shall the shepherds make their fold there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 21, E'But wild beasts of the desert shall lie there; and their houses shall be full of doleful creatures; and owls shall dwell there, and satyrs shall dance there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 22, E'And the wild beasts of the islands shall cry in their desolate houses, and dragons in their pleasant palaces: and her time is near to come, and her days shall not be prolonged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 1, E'For the LORD will have mercy on Jacob, and will yet choose Israel, and set them in their own land: and the strangers shall be joined with them, and they shall cleave to the house of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 2, E'And the people shall take them, and bring them to their place: and the house of Israel shall possess them in the land of the LORD for servants and handmaids: and they shall take them captives, whose captives they were; and they shall rule over their oppressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 3, E'And it shall come to pass in the day that the LORD shall give thee rest from thy sorrow, and from thy fear, and from the hard bondage wherein thou wast made to serve,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 4, E'That thou shalt take up this proverb against the king of Babylon, and say, How hath the oppressor ceased! the golden city ceased!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 5, E'The LORD hath broken the staff of the wicked, and the sceptre of the rulers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 6, E'He who smote the people in wrath with a continual stroke, he that ruled the nations in anger, is persecuted, and none hindereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 7, E'The whole earth is at rest, and is quiet: they break forth into singing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 8, E'Yea, the fir trees rejoice at thee, and the cedars of Lebanon, saying, Since thou art laid down, no feller is come up against us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 9, E'Hell from beneath is moved for thee to meet thee at thy coming: it stirreth up the dead for thee, even all the chief ones of the earth; it hath raised up from their thrones all the kings of the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 10, E'All they shall speak and say unto thee, Art thou also become weak as we? art thou become like unto us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 11, E'Thy pomp is brought down to the grave, and the noise of thy viols: the worm is spread under thee, and the worms cover thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 12, E'How art thou fallen from heaven, O Lucifer, son of the morning! how art thou cut down to the ground, which didst weaken the nations!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 13, E'For thou hast said in thine heart, I will ascend into heaven, I will exalt my throne above the stars of God: I will sit also upon the mount of the congregation, in the sides of the north:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 14, E'I will ascend above the heights of the clouds; I will be like the most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 15, E'Yet thou shalt be brought down to hell, to the sides of the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 16, E'They that see thee shall narrowly look upon thee, and consider thee, saying, Is this the man that made the earth to tremble, that did shake kingdoms;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 17, E'That made the world as a wilderness, and destroyed the cities thereof; that opened not the house of his prisoners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 18, E'All the kings of the nations, even all of them, lie in glory, every one in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 19, E'But thou art cast out of thy grave like an abominable branch, and as the raiment of those that are slain, thrust through with a sword, that go down to the stones of the pit; as a carcase trodden under feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 20, E'Thou shalt not be joined with them in burial, because thou hast destroyed thy land, and slain thy people: the seed of evildoers shall never be renowned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 21, E'Prepare slaughter for his children for the iniquity of their fathers; that they do not rise, nor possess the land, nor fill the face of the world with cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 22, E'For I will rise up against them, saith the LORD of hosts, and cut off from Babylon the name, and remnant, and son, and nephew, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 23, E'I will also make it a possession for the bittern, and pools of water: and I will sweep it with the besom of destruction, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 24, E'The LORD of hosts hath sworn, saying, Surely as I have thought, so shall it come to pass; and as I have purposed, so shall it stand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 25, E'That I will break the Assyrian in my land, and upon my mountains tread him under foot: then shall his yoke depart from off them, and his burden depart from off their shoulders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 26, E'This is the purpose that is purposed upon the whole earth: and this is the hand that is stretched out upon all the nations.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 27, E'For the LORD of hosts hath purposed, and who shall disannul it? and his hand is stretched out, and who shall turn it back?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 28, E'In the year that king Ahaz died was this burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 29, E'Rejoice not thou, whole Palestina, because the rod of him that smote thee is broken: for out of the serpent’s root shall come forth a cockatrice, and his fruit shall be a fiery flying serpent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 30, E'And the firstborn of the poor shall feed, and the needy shall lie down in safety: and I will kill thy root with famine, and he shall slay thy remnant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 31, E'Howl, O gate; cry, O city; thou, whole Palestina, art dissolved: for there shall come from the north a smoke, and none shall be alone in his appointed times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 32, E'What shall one then answer the messengers of the nation? That the LORD hath founded Zion, and the poor of his people shall trust in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 1, E'The burden of Moab. Because in the night Ar of Moab is laid waste, and brought to silence; because in the night Kir of Moab is laid waste, and brought to silence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 2, E'He is gone up to Bajith, and to Dibon, the high places, to weep: Moab shall howl over Nebo, and over Medeba: on all their heads shall be baldness, and every beard cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 3, E'In their streets they shall gird themselves with sackcloth: on the tops of their houses, and in their streets, every one shall howl, weeping abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 4, E'And Heshbon shall cry, and Elealeh: their voice shall be heard even unto Jahaz: therefore the armed soldiers of Moab shall cry out; his life shall be grievous unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 5, E'My heart shall cry out for Moab; his fugitives shall flee unto Zoar, an heifer of three years old: for by the mounting up of Luhith with weeping shall they go it up; for in the way of Horonaim they shall raise up a cry of destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 6, E'For the waters of Nimrim shall be desolate: for the hay is withered away, the grass faileth, there is no green thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 7, E'Therefore the abundance they have gotten, and that which they have laid up, shall they carry away to the brook of the willows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 8, E'For the cry is gone round about the borders of Moab; the howling thereof unto Eglaim, and the howling thereof unto Beerelim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 9, E'For the waters of Dimon shall be full of blood: for I will bring more upon Dimon, lions upon him that escapeth of Moab, and upon the remnant of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 1, E'Send ye the lamb to the ruler of the land from Sela to the wilderness, unto the mount of the daughter of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 2, E'For it shall be, that, as a wandering bird cast out of the nest, so the daughters of Moab shall be at the fords of Arnon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 3, E'Take counsel, execute judgment; make thy shadow as the night in the midst of the noonday; hide the outcasts; bewray not him that wandereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 4, E'Let mine outcasts dwell with thee, Moab; be thou a covert to them from the face of the spoiler: for the extortioner is at an end, the spoiler ceaseth, the oppressors are consumed out of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 5, E'And in mercy shall the throne be established: and he shall sit upon it in truth in the tabernacle of David, judging, and seeking judgment, and hasting righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 6, E'We have heard of the pride of Moab; he is very proud: even of his haughtiness, and his pride, and his wrath: but his lies shall not be so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 7, E'Therefore shall Moab howl for Moab, every one shall howl: for the foundations of Kirhareseth shall ye mourn; surely they are stricken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 8, E'For the fields of Heshbon languish, and the vine of Sibmah: the lords of the heathen have broken down the principal plants thereof, they are come even unto Jazer, they wandered through the wilderness: her branches are stretched out, they are gone over the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 9, E'Therefore I will bewail with the weeping of Jazer the vine of Sibmah: I will water thee with my tears, O Heshbon, and Elealeh: for the shouting for thy summer fruits and for thy harvest is fallen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 10, E'And gladness is taken away, and joy out of the plentiful field; and in the vineyards there shall be no singing, neither shall there be shouting: the treaders shall tread out no wine in their presses; I have made their vintage shouting to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 11, E'Wherefore my bowels shall sound like an harp for Moab, and mine inward parts for Kirharesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 12, E'And it shall come to pass, when it is seen that Moab is weary on the high place, that he shall come to his sanctuary to pray; but he shall not prevail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 13, E'This is the word that the LORD hath spoken concerning Moab since that time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 14, E'But now the LORD hath spoken, saying, Within three years, as the years of an hireling, and the glory of Moab shall be contemned, with all that great multitude; and the remnant shall be very small and feeble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 1, E'The burden of Damascus. Behold, Damascus is taken away from being a city, and it shall be a ruinous heap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 2, E'The cities of Aroer are forsaken: they shall be for flocks, which shall lie down, and none shall make them afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 3, E'The fortress also shall cease from Ephraim, and the kingdom from Damascus, and the remnant of Syria: they shall be as the glory of the children of Israel, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 4, E'And in that day it shall come to pass, that the glory of Jacob shall be made thin, and the fatness of his flesh shall wax lean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 5, E'And it shall be as when the harvestman gathereth the corn, and reapeth the ears with his arm; and it shall be as he that gathereth ears in the valley of Rephaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 6, E'Yet gleaning grapes shall be left in it, as the shaking of an olive tree, two or three berries in the top of the uppermost bough, four or five in the outmost fruitful branches thereof, saith the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 7, E'At that day shall a man look to his Maker, and his eyes shall have respect to the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 8, E'And he shall not look to the altars, the work of his hands, neither shall respect that which his fingers have made, either the groves, or the images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 9, E'In that day shall his strong cities be as a forsaken bough, and an uppermost branch, which they left because of the children of Israel: and there shall be desolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 10, E'Because thou hast forgotten the God of thy salvation, and hast not been mindful of the rock of thy strength, therefore shalt thou plant pleasant plants, and shalt set it with strange slips:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 11, E'In the day shalt thou make thy plant to grow, and in the morning shalt thou make thy seed to flourish: but the harvest shall be a heap in the day of grief and of desperate sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 12, E'Woe to the multitude of many people, which make a noise like the noise of the seas; and to the rushing of nations, that make a rushing like the rushing of mighty waters!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 13, E'The nations shall rush like the rushing of many waters: but God shall rebuke them, and they shall flee far off, and shall be chased as the chaff of the mountains before the wind, and like a rolling thing before the whirlwind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 14, E'And behold at eveningtide trouble; and before the morning he is not. This is the portion of them that spoil us, and the lot of them that rob us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 1, E'Woe to the land shadowing with wings, which is beyond the rivers of Ethiopia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 2, E'That sendeth ambassadors by the sea, even in vessels of bulrushes upon the waters, saying, Go, ye swift messengers, to a nation scattered and peeled, to a people terrible from their beginning hitherto; a nation meted out and trodden down, whose land the rivers have spoiled!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 3, E'All ye inhabitants of the world, and dwellers on the earth, see ye, when he lifteth up an ensign on the mountains; and when he bloweth a trumpet, hear ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 4, E'For so the LORD said unto me, I will take my rest, and I will consider in my dwelling place like a clear heat upon herbs, and like a cloud of dew in the heat of harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 5, E'For afore the harvest, when the bud is perfect, and the sour grape is ripening in the flower, he shall both cut off the sprigs with pruning hooks, and take away and cut down the branches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 6, E'They shall be left together unto the fowls of the mountains, and to the beasts of the earth: and the fowls shall summer upon them, and all the beasts of the earth shall winter upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 7, E'In that time shall the present be brought unto the LORD of hosts of a people scattered and peeled, and from a people terrible from their beginning hitherto; a nation meted out and trodden under foot, whose land the rivers have spoiled, to the place of the name of the LORD of hosts, the mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 1, E'The burden of Egypt. Behold, the LORD rideth upon a swift cloud, and shall come into Egypt: and the idols of Egypt shall be moved at his presence, and the heart of Egypt shall melt in the midst of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 2, E'And I will set the Egyptians against the Egyptians: and they shall fight every one against his brother, and every one against his neighbour; city against city, and kingdom against kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 3, E'And the spirit of Egypt shall fail in the midst thereof; and I will destroy the counsel thereof: and they shall seek to the idols, and to the charmers, and to them that have familiar spirits, and to the wizards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 4, E'And the Egyptians will I give over into the hand of a cruel lord; and a fierce king shall rule over them, saith the Lord, the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 5, E'And the waters shall fail from the sea, and the river shall be wasted and dried up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 6, E'And they shall turn the rivers far away; and the brooks of defence shall be emptied and dried up: the reeds and flags shall wither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 7, E'The paper reeds by the brooks, by the mouth of the brooks, and every thing sown by the brooks, shall wither, be driven away, and be no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 8, E'The fishers also shall mourn, and all they that cast angle into the brooks shall lament, and they that spread nets upon the waters shall languish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 9, E'Moreover they that work in fine flax, and they that weave networks, shall be confounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 10, E'And they shall be broken in the purposes thereof, all that make sluices and ponds for fish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 11, E'Surely the princes of Zoan are fools, the counsel of the wise counsellors of Pharaoh is become brutish: how say ye unto Pharaoh, I am the son of the wise, the son of ancient kings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 12, E'Where are they? where are thy wise men? and let them tell thee now, and let them know what the LORD of hosts hath purposed upon Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 13, E'The princes of Zoan are become fools, the princes of Noph are deceived; they have also seduced Egypt, even they that are the stay of the tribes thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 14, E'The LORD hath mingled a perverse spirit in the midst thereof: and they have caused Egypt to err in every work thereof, as a drunken man staggereth in his vomit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 15, E'Neither shall there be any work for Egypt, which the head or tail, branch or rush, may do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 16, E'In that day shall Egypt be like unto women: and it shall be afraid and fear because of the shaking of the hand of the LORD of hosts, which he shaketh over it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 17, E'And the land of Judah shall be a terror unto Egypt, every one that maketh mention thereof shall be afraid in himself, because of the counsel of the LORD of hosts, which he hath determined against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 18, E'In that day shall five cities in the land of Egypt speak the language of Canaan, and swear to the LORD of hosts; one shall be called, The city of destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 19, E'In that day shall there be an altar to the LORD in the midst of the land of Egypt, and a pillar at the border thereof to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 20, E'And it shall be for a sign and for a witness unto the LORD of hosts in the land of Egypt: for they shall cry unto the LORD because of the oppressors, and he shall send them a saviour, and a great one, and he shall deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 21, E'And the LORD shall be known to Egypt, and the Egyptians shall know the LORD in that day, and shall do sacrifice and oblation; yea, they shall vow a vow unto the LORD, and perform it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 22, E'And the LORD shall smite Egypt: he shall smite and heal it: and they shall return even to the LORD, and he shall be intreated of them, and shall heal them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 23, E'In that day shall there be a highway out of Egypt to Assyria, and the Assyrian shall come into Egypt, and the Egyptian into Assyria, and the Egyptians shall serve with the Assyrians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 24, E'In that day shall Israel be the third with Egypt and with Assyria, even a blessing in the midst of the land:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 25, E'Whom the LORD of hosts shall bless, saying, Blessed be Egypt my people, and Assyria the work of my hands, and Israel mine inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 1, E'In the year that Tartan came unto Ashdod, (when Sargon the king of Assyria sent him,) and fought against Ashdod, and took it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 2, E'At the same time spake the LORD by Isaiah the son of Amoz, saying, Go and loose the sackcloth from off thy loins, and put off thy shoe from thy foot. And he did so, walking naked and barefoot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 3, E'And the LORD said, Like as my servant Isaiah hath walked naked and barefoot three years for a sign and wonder upon Egypt and upon Ethiopia;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 4, E'So shall the king of Assyria lead away the Egyptians prisoners, and the Ethiopians captives, young and old, naked and barefoot, even with their buttocks uncovered, to the shame of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 5, E'And they shall be afraid and ashamed of Ethiopia their expectation, and of Egypt their glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 6, E'And the inhabitant of this isle shall say in that day, Behold, such is our expectation, whither we flee for help to be delivered from the king of Assyria: and how shall we escape?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 1, E'The burden of the desert of the sea. As whirlwinds in the south pass through; so it cometh from the desert, from a terrible land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 2, E'A grievous vision is declared unto me; the treacherous dealer dealeth treacherously, and the spoiler spoileth. Go up, O Elam: besiege, O Media; all the sighing thereof have I made to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 3, E'Therefore are my loins filled with pain: pangs have taken hold upon me, as the pangs of a woman that travaileth: I was bowed down at the hearing of it; I was dismayed at the seeing of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 4, E'My heart panted, fearfulness affrighted me: the night of my pleasure hath he turned into fear unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 5, E'Prepare the table, watch in the watchtower, eat, drink: arise, ye princes, and anoint the shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 6, E'For thus hath the LORD said unto me, Go, set a watchman, let him declare what he seeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 7, E'And he saw a chariot with a couple of horsemen, a chariot of asses, and a chariot of camels; and he hearkened diligently with much heed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 8, E'And he cried, A lion: My lord, I stand continually upon the watchtower in the daytime, and I am set in my ward whole nights:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 9, E'And, behold, here cometh a chariot of men, with a couple of horsemen. And he answered and said, Babylon is fallen, is fallen; and all the graven images of her gods he hath broken unto the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 10, E'O my threshing, and the corn of my floor: that which I have heard of the LORD of hosts, the God of Israel, have I declared unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 11, E'The burden of Dumah. He calleth to me out of Seir, Watchman, what of the night? Watchman, what of the night?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 12, E'The watchman said, The morning cometh, and also the night: if ye will enquire, enquire ye: return, come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 13, E'The burden upon Arabia. In the forest in Arabia shall ye lodge, O ye travelling companies of Dedanim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 14, E'The inhabitants of the land of Tema brought water to him that was thirsty, they prevented with their bread him that fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 15, E'For they fled from the swords, from the drawn sword, and from the bent bow, and from the grievousness of war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 16, E'For thus hath the LORD said unto me, Within a year, according to the years of an hireling, and all the glory of Kedar shall fail:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 17, E'And the residue of the number of archers, the mighty men of the children of Kedar, shall be diminished: for the LORD God of Israel hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 1, E'The burden of the valley of vision. What aileth thee now, that thou art wholly gone up to the housetops?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 2, E'Thou that art full of stirs, a tumultuous city, a joyous city: thy slain men are not slain with the sword, nor dead in battle.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 3, E'All thy rulers are fled together, they are bound by the archers: all that are found in thee are bound together, which have fled from far.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 4, E'Therefore said I, Look away from me; I will weep bitterly, labour not to comfort me, because of the spoiling of the daughter of my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 5, E'For it is a day of trouble, and of treading down, and of perplexity by the Lord GOD of hosts in the valley of vision, breaking down the walls, and of crying to the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 6, E'And Elam bare the quiver with chariots of men and horsemen, and Kir uncovered the shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 7, E'And it shall come to pass, that thy choicest valleys shall be full of chariots, and the horsemen shall set themselves in array at the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 8, E'And he discovered the covering of Judah, and thou didst look in that day to the armour of the house of the forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 9, E'Ye have seen also the breaches of the city of David, that they are many: and ye gathered together the waters of the lower pool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 10, E'And ye have numbered the houses of Jerusalem, and the houses have ye broken down to fortify the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 11, E'Ye made also a ditch between the two walls for the water of the old pool: but ye have not looked unto the maker thereof, neither had respect unto him that fashioned it long ago.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 12, E'And in that day did the Lord GOD of hosts call to weeping, and to mourning, and to baldness, and to girding with sackcloth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 13, E'And behold joy and gladness, slaying oxen, and killing sheep, eating flesh, and drinking wine: let us eat and drink; for to morrow we shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 14, E'And it was revealed in mine ears by the LORD of hosts, Surely this iniquity shall not be purged from you till ye die, saith the Lord GOD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 15, E'Thus saith the Lord GOD of hosts, Go, get thee unto this treasurer, even unto Shebna, which is over the house, and say,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 16, E'What hast thou here? and whom hast thou here, that thou hast hewed thee out a sepulchre here, as he that heweth him out a sepulchre on high, and that graveth an habitation for himself in a rock?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 17, E'Behold, the LORD will carry thee away with a mighty captivity, and will surely cover thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 18, E'He will surely violently turn and toss thee like a ball into a large country: there shalt thou die, and there the chariots of thy glory shall be the shame of thy lord’s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 19, E'And I will drive thee from thy station, and from thy state shall he pull thee down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 20, E'And it shall come to pass in that day, that I will call my servant Eliakim the son of Hilkiah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 21, E'And I will clothe him with thy robe, and strengthen him with thy girdle, and I will commit thy government into his hand: and he shall be a father to the inhabitants of Jerusalem, and to the house of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 22, E'And the key of the house of David will I lay upon his shoulder; so he shall open, and none shall shut; and he shall shut, and none shall open.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 23, E'And I will fasten him as a nail in a sure place; and he shall be for a glorious throne to his father’s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 24, E'And they shall hang upon him all the glory of his father’s house, the offspring and the issue, all vessels of small quantity, from the vessels of cups, even to all the vessels of flagons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 25, E'In that day, saith the LORD of hosts, shall the nail that is fastened in the sure place be removed, and be cut down, and fall; and the burden that was upon it shall be cut off: for the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 1, E'The burden of Tyre. Howl, ye ships of Tarshish; for it is laid waste, so that there is no house, no entering in: from the land of Chittim it is revealed to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 2, E'Be still, ye inhabitants of the isle; thou whom the merchants of Zidon, that pass over the sea, have replenished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 3, E'And by great waters the seed of Sihor, the harvest of the river, is her revenue; and she is a mart of nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 4, E'Be thou ashamed, O Zidon: for the sea hath spoken, even the strength of the sea, saying, I travail not, nor bring forth children, neither do I nourish up young men, nor bring up virgins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 5, E'As at the report concerning Egypt, so shall they be sorely pained at the report of Tyre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 6, E'Pass ye over to Tarshish; howl, ye inhabitants of the isle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 7, E'Is this your joyous city, whose antiquity is of ancient days? her own feet shall carry her afar off to sojourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 8, E'Who hath taken this counsel against Tyre, the crowning city, whose merchants are princes, whose traffickers are the honourable of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 9, E'The LORD of hosts hath purposed it, to stain the pride of all glory, and to bring into contempt all the honourable of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 10, E'Pass through thy land as a river, O daughter of Tarshish: there is no more strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 11, E'He stretched out his hand over the sea, he shook the kingdoms: the LORD hath given a commandment against the merchant city, to destroy the strong holds thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 12, E'And he said, Thou shalt no more rejoice, O thou oppressed virgin, daughter of Zidon: arise, pass over to Chittim; there also shalt thou have no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 13, E'Behold the land of the Chaldeans; this people was not, till the Assyrian founded it for them that dwell in the wilderness: they set up the towers thereof, they raised up the palaces thereof; and he brought it to ruin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 14, E'Howl, ye ships of Tarshish: for your strength is laid waste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 15, E'And it shall come to pass in that day, that Tyre shall be forgotten seventy years, according to the days of one king: after the end of seventy years shall Tyre sing as an harlot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 16, E'Take an harp, go about the city, thou harlot that hast been forgotten; make sweet melody, sing many songs, that thou mayest be remembered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 17, E'And it shall come to pass after the end of seventy years, that the LORD will visit Tyre, and she shall turn to her hire, and shall commit fornication with all the kingdoms of the world upon the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 18, E'And her merchandise and her hire shall be holiness to the LORD: it shall not be treasured nor laid up; for her merchandise shall be for them that dwell before the LORD, to eat sufficiently, and for durable clothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 1, E'Behold, the LORD maketh the earth empty, and maketh it waste, and turneth it upside down, and scattereth abroad the inhabitants thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 2, E'And it shall be, as with the people, so with the priest; as with the servant, so with his master; as with the maid, so with her mistress; as with the buyer, so with the seller; as with the lender, so with the borrower; as with the taker of usury, so with the giver of usury to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 3, E'The land shall be utterly emptied, and utterly spoiled: for the LORD hath spoken this word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 4, E'The earth mourneth and fadeth away, the world languisheth and fadeth away, the haughty people of the earth do languish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 5, E'The earth also is defiled under the inhabitants thereof; because they have transgressed the laws, changed the ordinance, broken the everlasting covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 6, E'Therefore hath the curse devoured the earth, and they that dwell therein are desolate: therefore the inhabitants of the earth are burned, and few men left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 7, E'The new wine mourneth, the vine languisheth, all the merryhearted do sigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 8, E'The mirth of tabrets ceaseth, the noise of them that rejoice endeth, the joy of the harp ceaseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 9, E'They shall not drink wine with a song; strong drink shall be bitter to them that drink it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 10, E'The city of confusion is broken down: every house is shut up, that no man may come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 11, E'There is a crying for wine in the streets; all joy is darkened, the mirth of the land is gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 12, E'In the city is left desolation, and the gate is smitten with destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 13, E'When thus it shall be in the midst of the land among the people, there shall be as the shaking of an olive tree, and as the gleaning grapes when the vintage is done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 14, E'They shall lift up their voice, they shall sing for the majesty of the LORD, they shall cry aloud from the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 15, E'Wherefore glorify ye the LORD in the fires, even the name of the LORD God of Israel in the isles of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 16, E'From the uttermost part of the earth have we heard songs, even glory to the righteous. But I said, My leanness, my leanness, woe unto me! the treacherous dealers have dealt treacherously; yea, the treacherous dealers have dealt very treacherously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 17, E'Fear, and the pit, and the snare, are upon thee, O inhabitant of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 18, E'And it shall come to pass, that he who fleeth from the noise of the fear shall fall into the pit; and he that cometh up out of the midst of the pit shall be taken in the snare: for the windows from on high are open, and the foundations of the earth do shake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 19, E'The earth is utterly broken down, the earth is clean dissolved, the earth is moved exceedingly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 20, E'The earth shall reel to and fro like a drunkard, and shall be removed like a cottage; and the transgression thereof shall be heavy upon it; and it shall fall, and not rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 21, E'And it shall come to pass in that day, that the LORD shall punish the host of the high ones that are on high, and the kings of the earth upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 22, E'And they shall be gathered together, as prisoners are gathered in the pit, and shall be shut up in the prison, and after many days shall they be visited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 23, E'Then the moon shall be confounded, and the sun ashamed, when the LORD of hosts shall reign in mount Zion, and in Jerusalem, and before his ancients gloriously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 1, E'O Lord, thou art my God; I will exalt thee, I will praise thy name; for thou hast done wonderful things; thy counsels of old are faithfulness and truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 2, E'For thou hast made of a city an heap; of a defenced city a ruin: a palace of strangers to be no city; it shall never be built.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 3, E'Therefore shall the strong people glorify thee, the city of the terrible nations shall fear thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 4, E'For thou hast been a strength to the poor, a strength to the needy in his distress, a refuge from the storm, a shadow from the heat, when the blast of the terrible ones is as a storm against the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 5, E'Thou shalt bring down the noise of strangers, as the heat in a dry place; even the heat with the shadow of a cloud: the branch of the terrible ones shall be brought low.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 6, E'And in this mountain shall the LORD of hosts make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 7, E'And he will destroy in this mountain the face of the covering cast over all people, and the vail that is spread over all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 8, E'He will swallow up death in victory; and the Lord GOD will wipe away tears from off all faces; and the rebuke of his people shall he take away from off all the earth: for the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 9, E'And it shall be said in that day, Lo, this is our God; we have waited for him, and he will save us: this is the LORD; we have waited for him, we will be glad and rejoice in his salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 10, E'For in this mountain shall the hand of the LORD rest, and Moab shall be trodden down under him, even as straw is trodden down for the dunghill.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 11, E'And he shall spread forth his hands in the midst of them, as he that swimmeth spreadeth forth his hands to swim: and he shall bring down their pride together with the spoils of their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 12, E'And the fortress of the high fort of thy walls shall he bring down, lay low, and bring to the ground, even to the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 1, E'In that day shall this song be sung in the land of Judah; We have a strong city; salvation will God appoint for walls and bulwarks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 2, E'Open ye the gates, that the righteous nation which keepeth the truth may enter in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 3, E'Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 4, E'Trust ye in the LORD for ever: for in the LORD JEHOVAH is everlasting strength:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 5, E'For he bringeth down them that dwell on high; the lofty city, he layeth it low; he layeth it low, even to the ground; he bringeth it even to the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 6, E'The foot shall tread it down, even the feet of the poor, and the steps of the needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 7, E'The way of the just is uprightness: thou, most upright, dost weigh the path of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 8, E'Yea, in the way of thy judgments, O LORD, have we waited for thee; the desire of our soul is to thy name, and to the remembrance of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 9, E'With my soul have I desired thee in the night; yea, with my spirit within me will I seek thee early: for when thy judgments are in the earth, the inhabitants of the world will learn righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 10, E'Let favour be shewed to the wicked, yet will he not learn righteousness: in the land of uprightness will he deal unjustly, and will not behold the majesty of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 11, E'LORD, when thy hand is lifted up, they will not see: but they shall see, and be ashamed for their envy at the people; yea, the fire of thine enemies shall devour them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 12, E'LORD, thou wilt ordain peace for us: for thou also hast wrought all our works in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 13, E'O LORD our God, other lords beside thee have had dominion over us: but by thee only will we make mention of thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 14, E'They are dead, they shall not live; they are deceased, they shall not rise: therefore hast thou visited and destroyed them, and made all their memory to perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 15, E'Thou hast increased the nation, O LORD, thou hast increased the nation: thou art glorified: thou hadst removed it far unto all the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 16, E'LORD, in trouble have they visited thee, they poured out a prayer when thy chastening was upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 17, E'Like as a woman with child, that draweth near the time of her delivery, is in pain, and crieth out in her pangs; so have we been in thy sight, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 18, E'We have been with child, we have been in pain, we have as it were brought forth wind; we have not wrought any deliverance in the earth; neither have the inhabitants of the world fallen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 19, E'Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 20, E'Come, my people, enter thou into thy chambers, and shut thy doors about thee: hide thyself as it were for a little moment, until the indignation be overpast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 21, E'For, behold, the LORD cometh out of his place to punish the inhabitants of the earth for their iniquity: the earth also shall disclose her blood, and shall no more cover her slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 1, E'In that day the LORD with his sore and great and strong sword shall punish leviathan the piercing serpent, even leviathan that crooked serpent; and he shall slay the dragon that is in the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 2, E'In that day sing ye unto her, A vineyard of red wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 3, E'I the LORD do keep it; I will water it every moment: lest any hurt it, I will keep it night and day.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 4, E'Fury is not in me: who would set the briers and thorns against me in battle? I would go through them, I would burn them together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 5, E'Or let him take hold of my strength, that he may make peace with me; and he shall make peace with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 6, E'He shall cause them that come of Jacob to take root: Israel shall blossom and bud, and fill the face of the world with fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 7, E'Hath he smitten him, as he smote those that smote him? or is he slain according to the slaughter of them that are slain by him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 8, E'In measure, when it shooteth forth, thou wilt debate with it: he stayeth his rough wind in the day of the east wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 9, E'By this therefore shall the iniquity of Jacob be purged; and this is all the fruit to take away his sin; when he maketh all the stones of the altar as chalkstones that are beaten in sunder, the groves and images shall not stand up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 10, E'Yet the defenced city shall be desolate, and the habitation forsaken, and left like a wilderness: there shall the calf feed, and there shall he lie down, and consume the branches thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 11, E'When the boughs thereof are withered, they shall be broken off: the women come, and set them on fire: for it is a people of no understanding: therefore he that made them will not have mercy on them, and he that formed them will shew them no favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 12, E'And it shall come to pass in that day, that the LORD shall beat off from the channel of the river unto the stream of Egypt, and ye shall be gathered one by one, O ye children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 13, E'And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship the LORD in the holy mount at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 1, E'Woe to the crown of pride, to the drunkards of Ephraim, whose glorious beauty is a fading flower, which are on the head of the fat valleys of them that are overcome with wine!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 2, E'Behold, the Lord hath a mighty and strong one, which as a tempest of hail and a destroying storm, as a flood of mighty waters overflowing, shall cast down to the earth with the hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 3, E'The crown of pride, the drunkards of Ephraim, shall be trodden under feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 4, E'And the glorious beauty, which is on the head of the fat valley, shall be a fading flower, and as the hasty fruit before the summer; which when he that looketh upon it seeth, while it is yet in his hand he eateth it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 5, E'In that day shall the LORD of hosts be for a crown of glory, and for a diadem of beauty, unto the residue of his people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 6, E'And for a spirit of judgment to him that sitteth in judgment, and for strength to them that turn the battle to the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 7, E'But they also have erred through wine, and through strong drink are out of the way; the priest and the prophet have erred through strong drink, they are swallowed up of wine, they are out of the way through strong drink; they err in vision, they stumble in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 8, E'For all tables are full of vomit and filthiness, so that there is no place clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 9, E'Whom shall he teach knowledge? and whom shall he make to understand doctrine? them that are weaned from the milk, and drawn from the breasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 10, E'For precept must be upon precept, precept upon precept; line upon line, line upon line; here a little, and there a little:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 11, E'For with stammering lips and another tongue will he speak to this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 12, E'To whom he said, This is the rest wherewith ye may cause the weary to rest; and this is the refreshing: yet they would not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 13, E'But the word of the LORD was unto them precept upon precept, precept upon precept; line upon line, line upon line; here a little, and there a little; that they might go, and fall backward, and be broken, and snared, and taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 14, E'Wherefore hear the word of the LORD, ye scornful men, that rule this people which is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 15, E'Because ye have said, We have made a covenant with death, and with hell are we at agreement; when the overflowing scourge shall pass through, it shall not come unto us: for we have made lies our refuge, and under falsehood have we hid ourselves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 16, E'Therefore thus saith the Lord GOD, Behold, I lay in Zion for a foundation a stone, a tried stone, a precious corner stone, a sure foundation: he that believeth shall not make haste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 17, E'Judgment also will I lay to the line, and righteousness to the plummet: and the hail shall sweep away the refuge of lies, and the waters shall overflow the hiding place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 18, E'And your covenant with death shall be disannulled, and your agreement with hell shall not stand; when the overflowing scourge shall pass through, then ye shall be trodden down by it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 19, E'From the time that it goeth forth it shall take you: for morning by morning shall it pass over, by day and by night: and it shall be a vexation only to understand the report.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 20, E'For the bed is shorter than that a man can stretch himself on it: and the covering narrower than that he can wrap himself in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 21, E'For the LORD shall rise up as in mount Perazim, he shall be wroth as in the valley of Gibeon, that he may do his work, his strange work; and bring to pass his act, his strange act.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 22, E'Now therefore be ye not mockers, lest your bands be made strong: for I have heard from the Lord GOD of hosts a consumption, even determined upon the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 23, E'Give ye ear, and hear my voice; hearken, and hear my speech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 24, E'Doth the plowman plow all day to sow? doth he open and break the clods of his ground?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 25, E'When he hath made plain the face thereof, doth he not cast abroad the fitches, and scatter the cummin, and cast in the principal wheat and the appointed barley and the rie in their place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 26, E'For his God doth instruct him to discretion, and doth teach him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 27, E'For the fitches are not threshed with a threshing instrument, neither is a cart wheel turned about upon the cummin; but the fitches are beaten out with a staff, and the cummin with a rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 28, E'Bread corn is bruised; because he will not ever be threshing it, nor break it with the wheel of his cart, nor bruise it with his horsemen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 29, E'This also cometh forth from the LORD of hosts, which is wonderful in counsel, and excellent in working.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 1, E'Woe to Ariel, to Ariel, the city where David dwelt! add ye year to year; let them kill sacrifices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 2, E'Yet I will distress Ariel, and there shall be heaviness and sorrow: and it shall be unto me as Ariel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 3, E'And I will camp against thee round about, and will lay siege against thee with a mount, and I will raise forts against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 4, E'And thou shalt be brought down, and shalt speak out of the ground, and thy speech shall be low out of the dust, and thy voice shall be, as of one that hath a familiar spirit, out of the ground, and thy speech shall whisper out of the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 5, E'Moreover the multitude of thy strangers shall be like small dust, and the multitude of the terrible ones shall be as chaff that passeth away: yea, it shall be at an instant suddenly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 6, E'Thou shalt be visited of the LORD of hosts with thunder, and with earthquake, and great noise, with storm and tempest, and the flame of devouring fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 7, E'And the multitude of all the nations that fight against Ariel, even all that fight against her and her munition, and that distress her, shall be as a dream of a night vision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 8, E'It shall even be as when an hungry man dreameth, and, behold, he eateth; but he awaketh, and his soul is empty: or as when a thirsty man dreameth, and, behold, he drinketh; but he awaketh, and, behold, he is faint, and his soul hath appetite: so shall the multitude of all the nations be, that fight against mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 9, E'Stay yourselves, and wonder; cry ye out, and cry: they are drunken, but not with wine; they stagger, but not with strong drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 10, E'For the LORD hath poured out upon you the spirit of deep sleep, and hath closed your eyes: the prophets and your rulers, the seers hath he covered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 11, E'And the vision of all is become unto you as the words of a book that is sealed, which men deliver to one that is learned, saying, Read this, I pray thee: and he saith, I cannot; for it is sealed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 12, E'And the book is delivered to him that is not learned, saying, Read this, I pray thee: and he saith, I am not learned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 13, E'Wherefore the Lord said, Forasmuch as this people draw near me with their mouth, and with their lips do honour me, but have removed their heart far from me, and their fear toward me is taught by the precept of men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 14, E'Therefore, behold, I will proceed to do a marvellous work among this people, even a marvellous work and a wonder: for the wisdom of their wise men shall perish, and the understanding of their prudent men shall be hid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 15, E'Woe unto them that seek deep to hide their counsel from the LORD, and their works are in the dark, and they say, Who seeth us? and who knoweth us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 16, E'Surely your turning of things upside down shall be esteemed as the potter’s clay: for shall the work say of him that made it, He made me not? or shall the thing framed say of him that framed it, He had no understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 17, E'Is it not yet a very little while, and Lebanon shall be turned into a fruitful field, and the fruitful field shall be esteemed as a forest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 18, E'And in that day shall the deaf hear the words of the book, and the eyes of the blind shall see out of obscurity, and out of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 19, E'The meek also shall increase their joy in the LORD, and the poor among men shall rejoice in the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 20, E'For the terrible one is brought to nought, and the scorner is consumed, and all that watch for iniquity are cut off:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 21, E'That make a man an offender for a word, and lay a snare for him that reproveth in the gate, and turn aside the just for a thing of nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 22, E'Therefore thus saith the LORD, who redeemed Abraham, concerning the house of Jacob, Jacob shall not now be ashamed, neither shall his face now wax pale.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 23, E'But when he seeth his children, the work of mine hands, in the midst of him, they shall sanctify my name, and sanctify the Holy One of Jacob, and shall fear the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 24, E'They also that erred in spirit shall come to understanding, and they that murmured shall learn doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 1, E'Woe to the rebellious children, saith the LORD, that take counsel, but not of me; and that cover with a covering, but not of my spirit, that they may add sin to sin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 2, E'That walk to go down into Egypt, and have not asked at my mouth; to strengthen themselves in the strength of Pharaoh, and to trust in the shadow of Egypt!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 3, E'Therefore shall the strength of Pharaoh be your shame, and the trust in the shadow of Egypt your confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 4, E'For his princes were at Zoan, and his ambassadors came to Hanes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 5, E'They were all ashamed of a people that could not profit them, nor be an help nor profit, but a shame, and also a reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 6, E'The burden of the beasts of the south: into the land of trouble and anguish, from whence come the young and old lion, the viper and fiery flying serpent, they will carry their riches upon the shoulders of young asses, and their treasures upon the bunches of camels, to a people that shall not profit them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 7, E'For the Egyptians shall help in vain, and to no purpose: therefore have I cried concerning this, Their strength is to sit still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 8, E'Now go, write it before them in a table, and note it in a book, that it may be for the time to come for ever and ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 9, E'That this is a rebellious people, lying children, children that will not hear the law of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 10, E'Which say to the seers, See not; and to the prophets, Prophesy not unto us right things, speak unto us smooth things, prophesy deceits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 11, E'Get you out of the way, turn aside out of the path, cause the Holy One of Israel to cease from before us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 12, E'Wherefore thus saith the Holy One of Israel, Because ye despise this word, and trust in oppression and perverseness, and stay thereon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 13, E'Therefore this iniquity shall be to you as a breach ready to fall, swelling out in a high wall, whose breaking cometh suddenly at an instant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 14, E'And he shall break it as the breaking of the potters’ vessel that is broken in pieces; he shall not spare: so that there shall not be found in the bursting of it a sherd to take fire from the hearth, or to take water withal out of the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 15, E'For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 16, E'But ye said, No; for we will flee upon horses; therefore shall ye flee: and, We will ride upon the swift; therefore shall they that pursue you be swift.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 17, E'One thousand shall flee at the rebuke of one; at the rebuke of five shall ye flee: till ye be left as a beacon upon the top of a mountain, and as an ensign on an hill.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 18, E'And therefore will the LORD wait, that he may be gracious unto you, and therefore will he be exalted, that he may have mercy upon you: for the LORD is a God of judgment: blessed are all they that wait for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 19, E'For the people shall dwell in Zion at Jerusalem: thou shalt weep no more: he will be very gracious unto thee at the voice of thy cry; when he shall hear it, he will answer thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 20, E'And though the Lord give you the bread of adversity, and the water of affliction, yet shall not thy teachers be removed into a corner any more, but thine eyes shall see thy teachers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 21, E'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 22, E'Ye shall defile also the covering of thy graven images of silver, and the ornament of thy molten images of gold: thou shalt cast them away as a menstruous cloth; thou shalt say unto it, Get thee hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 23, E'Then shall he give the rain of thy seed, that thou shalt sow the ground withal; and bread of the increase of the earth, and it shall be fat and plenteous: in that day shall thy cattle feed in large pastures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 24, E'The oxen likewise and the young asses that ear the ground shall eat clean provender, which hath been winnowed with the shovel and with the fan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 25, E'And there shall be upon every high mountain, and upon every high hill, rivers and streams of waters in the day of the great slaughter, when the towers fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 26, E'Moreover the light of the moon shall be as the light of the sun, and the light of the sun shall be sevenfold, as the light of seven days, in the day that the LORD bindeth up the breach of his people, and healeth the stroke of their wound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 27, E'Behold, the name of the LORD cometh from far, burning with his anger, and the burden thereof is heavy: his lips are full of indignation, and his tongue as a devouring fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 28, E'And his breath, as an overflowing stream, shall reach to the midst of the neck, to sift the nations with the sieve of vanity: and there shall be a bridle in the jaws of the people, causing them to err.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 29, E'Ye shall have a song, as in the night when a holy solemnity is kept; and gladness of heart, as when one goeth with a pipe to come into the mountain of the LORD, to the mighty One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 30, E'And the LORD shall cause his glorious voice to be heard, and shall shew the lighting down of his arm, with the indignation of his anger, and with the flame of a devouring fire, with scattering, and tempest, and hailstones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 31, E'For through the voice of the LORD shall the Assyrian be beaten down, which smote with a rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 32, E'And in every place where the grounded staff shall pass, which the LORD shall lay upon him, it shall be with tabrets and harps: and in battles of shaking will he fight with it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 33, E'For Tophet is ordained of old; yea, for the king it is prepared; he hath made it deep and large: the pile thereof is fire and much wood; the breath of the LORD, like a stream of brimstone, doth kindle it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 1, E'Woe to them that go down to Egypt for help; and stay on horses, and trust in chariots, because they are many; and in horsemen, because they are very strong; but they look not unto the Holy One of Israel, neither seek the LORD!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 2, E'Yet he also is wise, and will bring evil, and will not call back his words: but will arise against the house of the evildoers, and against the help of them that work iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 3, E'Now the Egyptians are men, and not God; and their horses flesh, and not spirit. When the LORD shall stretch out his hand, both he that helpeth shall fall, and he that is holpen shall fall down, and they all shall fail together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 4, E'For thus hath the LORD spoken unto me, Like as the lion and the young lion roaring on his prey, when a multitude of shepherds is called forth against him, he will not be afraid of their voice, nor abase himself for the noise of them: so shall the LORD of hosts come down to fight for mount Zion, and for the hill thereof.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 5, E'As birds flying, so will the LORD of hosts defend Jerusalem; defending also he will deliver it; and passing over he will preserve it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 6, E'Turn ye unto him from whom the children of Israel have deeply revolted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 7, E'For in that day every man shall cast away his idols of silver, and his idols of gold, which your own hands have made unto you for a sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 8, E'Then shall the Assyrian fall with the sword, not of a mighty man; and the sword, not of a mean man, shall devour him: but he shall flee from the sword, and his young men shall be discomfited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 9, E'And he shall pass over to his strong hold for fear, and his princes shall be afraid of the ensign, saith the LORD, whose fire is in Zion, and his furnace in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 1, E'Behold, a king shall reign in righteousness, and princes shall rule in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 2, E'And a man shall be as an hiding place from the wind, and a covert from the tempest; as rivers of water in a dry place, as the shadow of a great rock in a weary land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 3, E'And the eyes of them that see shall not be dim, and the ears of them that hear shall hearken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 4, E'The heart also of the rash shall understand knowledge, and the tongue of the stammerers shall be ready to speak plainly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 5, E'The vile person shall be no more called liberal, nor the churl said to be bountiful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 6, E'For the vile person will speak villany, and his heart will work iniquity, to practise hypocrisy, and to utter error against the LORD, to make empty the soul of the hungry, and he will cause the drink of the thirsty to fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 7, E'The instruments also of the churl are evil: he deviseth wicked devices to destroy the poor with lying words, even when the needy speaketh right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 8, E'But the liberal deviseth liberal things; and by liberal things shall he stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 9, E'Rise up, ye women that are at ease; hear my voice, ye careless daughters; give ear unto my speech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 10, E'Many days and years shall ye be troubled, ye careless women: for the vintage shall fail, the gathering shall not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 11, E'Tremble, ye women that are at ease; be troubled, ye careless ones: strip you, and make you bare, and gird sackcloth upon your loins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 12, E'They shall lament for the teats, for the pleasant fields, for the fruitful vine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 13, E'Upon the land of my people shall come up thorns and briers; yea, upon all the houses of joy in the joyous city:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 14, E'Because the palaces shall be forsaken; the multitude of the city shall be left; the forts and towers shall be for dens for ever, a joy of wild asses, a pasture of flocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 15, E'Until the spirit be poured upon us from on high, and the wilderness be a fruitful field, and the fruitful field be counted for a forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 16, E'Then judgment shall dwell in the wilderness, and righteousness remain in the fruitful field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 17, E'And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 18, E'And my people shall dwell in a peaceable habitation, and in sure dwellings, and in quiet resting places;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 19, E'When it shall hail, coming down on the forest; and the city shall be low in a low place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 20, E'Blessed are ye that sow beside all waters, that send forth thither the feet of the ox and the ass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 1, E'Woe to thee that spoilest, and thou wast not spoiled; and dealest treacherously, and they dealt not treacherously with thee! when thou shalt cease to spoil, thou shalt be spoiled; and when thou shalt make an end to deal treacherously, they shall deal treacherously with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 2, E'O LORD, be gracious unto us; we have waited for thee: be thou their arm every morning, our salvation also in the time of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 3, E'At the noise of the tumult the people fled; at the lifting up of thyself the nations were scattered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 4, E'And your spoil shall be gathered like the gathering of the caterpiller: as the running to and fro of locusts shall he run upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 5, E'The LORD is exalted; for he dwelleth on high: he hath filled Zion with judgment and righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 6, E'And wisdom and knowledge shall be the stability of thy times, and strength of salvation: the fear of the LORD is his treasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 7, E'Behold, their valiant ones shall cry without: the ambassadors of peace shall weep bitterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 8, E'The highways lie waste, the wayfaring man ceaseth: he hath broken the covenant, he hath despised the cities, he regardeth no man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 9, E'The earth mourneth and languisheth: Lebanon is ashamed and hewn down: Sharon is like a wilderness; and Bashan and Carmel shake off their fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 10, E'Now will I rise, saith the LORD; now will I be exalted; now will I lift up myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 11, E'Ye shall conceive chaff, ye shall bring forth stubble: your breath, as fire, shall devour you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 12, E'And the people shall be as the burnings of lime: as thorns cut up shall they be burned in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 13, E'Hear, ye that are far off, what I have done; and, ye that are near, acknowledge my might.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 14, E'The sinners in Zion are afraid; fearfulness hath surprised the hypocrites. Who among us shall dwell with the devouring fire? who among us shall dwell with everlasting burnings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 15, E'He that walketh righteously, and speaketh uprightly; he that despiseth the gain of oppressions, that shaketh his hands from holding of bribes, that stoppeth his ears from hearing of blood, and shutteth his eyes from seeing evil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 16, E'He shall dwell on high: his place of defence shall be the munitions of rocks: bread shall be given him; his waters shall be sure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 17, E'Thine eyes shall see the king in his beauty: they shall behold the land that is very far off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 18, E'Thine heart shall meditate terror. Where is the scribe? where is the receiver? where is he that counted the towers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 19, E'Thou shalt not see a fierce people, a people of a deeper speech than thou canst perceive; of a stammering tongue, that thou canst not understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 20, E'Look upon Zion, the city of our solemnities: thine eyes shall see Jerusalem a quiet habitation, a tabernacle that shall not be taken down; not one of the stakes thereof shall ever be removed, neither shall any of the cords thereof be broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 21, E'But there the glorious LORD will be unto us a place of broad rivers and streams; wherein shall go no galley with oars, neither shall gallant ship pass thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 22, E'For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 23, E'Thy tacklings are loosed; they could not well strengthen their mast, they could not spread the sail: then is the prey of a great spoil divided; the lame take the prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 24, E'And the inhabitant shall not say, I am sick: the people that dwell therein shall be forgiven their iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 1, E'Come near, ye nations, to hear; and hearken, ye people: let the earth hear, and all that is therein; the world, and all things that come forth of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 2, E'For the indignation of the LORD is upon all nations, and his fury upon all their armies: he hath utterly destroyed them, he hath delivered them to the slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 3, E'Their slain also shall be cast out, and their stink shall come up out of their carcases, and the mountains shall be melted with their blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 4, E'And all the host of heaven shall be dissolved, and the heavens shall be rolled together as a scroll: and all their host shall fall down, as the leaf falleth off from the vine, and as a falling fig from the fig tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 5, E'For my sword shall be bathed in heaven: behold, it shall come down upon Idumea, and upon the people of my curse, to judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 6, E'The sword of the LORD is filled with blood, it is made fat with fatness, and with the blood of lambs and goats, with the fat of the kidneys of rams: for the LORD hath a sacrifice in Bozrah, and a great slaughter in the land of Idumea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 7, E'And the unicorns shall come down with them, and the bullocks with the bulls; and their land shall be soaked with blood, and their dust made fat with fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 8, E'For it is the day of the LORD’s vengeance, and the year of recompences for the controversy of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 9, E'And the streams thereof shall be turned into pitch, and the dust thereof into brimstone, and the land thereof shall become burning pitch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 10, E'It shall not be quenched night nor day; the smoke thereof shall go up for ever: from generation to generation it shall lie waste; none shall pass through it for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 11, E'But the cormorant and the bittern shall possess it; the owl also and the raven shall dwell in it: and he shall stretch out upon it the line of confusion, and the stones of emptiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 12, E'They shall call the nobles thereof to the kingdom, but none shall be there, and all her princes shall be nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 13, E'And thorns shall come up in her palaces, nettles and brambles in the fortresses thereof: and it shall be an habitation of dragons, and a court for owls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 14, E'The wild beasts of the desert shall also meet with the wild beasts of the island, and the satyr shall cry to his fellow; the screech owl also shall rest there, and find for herself a place of rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 15, E'There shall the great owl make her nest, and lay, and hatch, and gather under her shadow: there shall the vultures also be gathered, every one with her mate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 16, E'Seek ye out of the book of the LORD, and read: no one of these shall fail, none shall want her mate: for my mouth it hath commanded, and his spirit it hath gathered them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 17, E'And he hath cast the lot for them, and his hand hath divided it unto them by line: they shall possess it for ever, from generation to generation shall they dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 1, E'The wilderness and the solitary place shall be glad for them; and the desert shall rejoice, and blossom as the rose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 2, E'It shall blossom abundantly, and rejoice even with joy and singing: the glory of Lebanon shall be given unto it, the excellency of Carmel and Sharon, they shall see the glory of the LORD, and the excellency of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 3, E'Strengthen ye the weak hands, and confirm the feeble knees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 4, E'Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 5, E'Then the eyes of the blind shall be opened, and the ears of the deaf shall be unstopped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 6, E'Then shall the lame man leap as an hart, and the tongue of the dumb sing: for in the wilderness shall waters break out, and streams in the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 7, E'And the parched ground shall become a pool, and the thirsty land springs of water: in the habitation of dragons, where each lay, shall be grass with reeds and rushes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 8, E'And an highway shall be there, and a way, and it shall be called The way of holiness; the unclean shall not pass over it; but it shall be for those: the wayfaring men, though fools, shall not err therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 9, E'No lion shall be there, nor any ravenous beast shall go up thereon, it shall not be found there; but the redeemed shall walk there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 10, E'And the ransomed of the LORD shall return, and come to Zion with songs and everlasting joy upon their heads: they shall obtain joy and gladness, and sorrow and sighing shall flee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 1, E'Now it came to pass in the fourteenth year of king Hezekiah, that Sennacherib king of Assyria came up against all the defenced cities of Judah, and took them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 2, E'And the king of Assyria sent Rabshakeh from Lachish to Jerusalem unto king Hezekiah with a great army. And he stood by the conduit of the upper pool in the highway of the fuller’s field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 3, E'Then came forth unto him Eliakim, Hilkiah’s son, which was over the house, and Shebna the scribe, and Joah, Asaph’s son, the recorder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 4, E'And Rabshakeh said unto them, Say ye now to Hezekiah, Thus saith the great king, the king of Assyria, What confidence is this wherein thou trustest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 5, E'I say, sayest thou, (but they are but vain words) I have counsel and strength for war: now on whom dost thou trust, that thou rebellest against me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 6, E'Lo, thou trustest in the staff of this broken reed, on Egypt; whereon if a man lean, it will go into his hand, and pierce it: so is Pharaoh king of Egypt to all that trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 7, E'But if thou say to me, We trust in the LORD our God: is it not he, whose high places and whose altars Hezekiah hath taken away, and said to Judah and to Jerusalem, Ye shall worship before this altar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 8, E'Now therefore give pledges, I pray thee, to my master the king of Assyria, and I will give thee two thousand horses, if thou be able on thy part to set riders upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 9, E'How then wilt thou turn away the face of one captain of the least of my master’s servants, and put thy trust on Egypt for chariots and for horsemen?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 10, E'And am I now come up without the LORD against this land to destroy it? the LORD said unto me, Go up against this land, and destroy it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 11, E'Then said Eliakim and Shebna and Joah unto Rabshakeh, Speak, I pray thee, unto thy servants in the Syrian language; for we understand it: and speak not to us in the Jews’ language, in the ears of the people that are on the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 12, E'But Rabshakeh said, Hath my master sent me to thy master and to thee to speak these words? hath he not sent me to the men that sit upon the wall, that they may eat their own dung, and drink their own piss with you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 13, E'Then Rabshakeh stood, and cried with a loud voice in the Jews’ language, and said, Hear ye the words of the great king, the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 14, E'Thus saith the king, Let not Hezekiah deceive you: for he shall not be able to deliver you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 15, E'Neither let Hezekiah make you trust in the LORD, saying, The LORD will surely deliver us: this city shall not be delivered into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 16, E'Hearken not to Hezekiah: for thus saith the king of Assyria, Make an agreement with me by a present, and come out to me: and eat ye every one of his vine, and every one of his fig tree, and drink ye every one the waters of his own cistern;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 17, E'Until I come and take you away to a land like your own land, a land of corn and wine, a land of bread and vineyards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 18, E'Beware lest Hezekiah persuade you, saying, The LORD will deliver us. Hath any of the gods of the nations delivered his land out of the hand of the king of Assyria?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 19, E'Where are the gods of Hamath and Arphad? where are the gods of Sepharvaim? and have they delivered Samaria out of my hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 20, E'Who are they among all the gods of these lands, that have delivered their land out of my hand, that the LORD should deliver Jerusalem out of my hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 21, E'But they held their peace, and answered him not a word: for the king’s commandment was, saying, Answer him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 22, E'Then came Eliakim, the son of Hilkiah, that was over the household, and Shebna the scribe, and Joah, the son of Asaph, the recorder, to Hezekiah with their clothes rent, and told him the words of Rabshakeh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 1, E'And it came to pass, when king Hezekiah heard it, that he rent his clothes, and covered himself with sackcloth, and went into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 2, E'And he sent Eliakim, who was over the household, and Shebna the scribe, and the elders of the priests covered with sackcloth, unto Isaiah the prophet the son of Amoz.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 3, E'And they said unto him, Thus saith Hezekiah, This day is a day of trouble, and of rebuke, and of blasphemy: for the children are come to the birth, and there is not strength to bring forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 4, E'It may be the LORD thy God will hear the words of Rabshakeh, whom the king of Assyria his master hath sent to reproach the living God, and will reprove the words which the LORD thy God hath heard: wherefore lift up thy prayer for the remnant that is left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 5, E'So the servants of king Hezekiah came to Isaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 6, E'And Isaiah said unto them, Thus shall ye say unto your master, Thus saith the LORD, Be not afraid of the words that thou hast heard, wherewith the servants of the king of Assyria have blasphemed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 7, E'Behold, I will send a blast upon him, and he shall hear a rumour, and return to his own land; and I will cause him to fall by the sword in his own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 8, E'So Rabshakeh returned, and found the king of Assyria warring against Libnah: for he had heard that he was departed from Lachish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 9, E'And he heard say concerning Tirhakah king of Ethiopia, He is come forth to make war with thee. And when he heard it, he sent messengers to Hezekiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 10, E'Thus shall ye speak to Hezekiah king of Judah, saying, Let not thy God, in whom thou trustest, deceive thee, saying, Jerusalem shall not be given into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 11, E'Behold, thou hast heard what the kings of Assyria have done to all lands by destroying them utterly; and shalt thou be delivered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 12, E'Have the gods of the nations delivered them which my fathers have destroyed, as Gozan, and Haran, and Rezeph, and the children of Eden which were in Telassar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 13, E'Where is the king of Hamath, and the king of Arphad, and the king of the city of Sepharvaim, Hena, and Ivah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 14, E'And Hezekiah received the letter from the hand of the messengers, and read it: and Hezekiah went up unto the house of the LORD, and spread it before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 15, E'And Hezekiah prayed unto the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 16, E'O LORD of hosts, God of Israel, that dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth: thou hast made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 17, E'Incline thine ear, O LORD, and hear; open thine eyes, O LORD, and see: and hear all the words of Sennacherib, which hath sent to reproach the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 18, E'Of a truth, LORD, the kings of Assyria have laid waste all the nations, and their countries,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 19, E'And have cast their gods into the fire: for they were no gods, but the work of men’s hands, wood and stone: therefore they have destroyed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 20, E'Now therefore, O LORD our God, save us from his hand, that all the kingdoms of the earth may know that thou art the LORD, even thou only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 21, E'Then Isaiah the son of Amoz sent unto Hezekiah, saying, Thus saith the LORD God of Israel, Whereas thou hast prayed to me against Sennacherib king of Assyria:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 22, E'This is the word which the LORD hath spoken concerning him; The virgin, the daughter of Zion, hath despised thee, and laughed thee to scorn; the daughter of Jerusalem hath shaken her head at thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 23, E'Whom hast thou reproached and blasphemed? and against whom hast thou exalted thy voice, and lifted up thine eyes on high? even against the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 24, E'By thy servants hast thou reproached the Lord, and hast said, By the multitude of my chariots am I come up to the height of the mountains, to the sides of Lebanon; and I will cut down the tall cedars thereof, and the choice fir trees thereof: and I will enter into the height of his border, and the forest of his Carmel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 25, E'I have digged, and drunk water; and with the sole of my feet have I dried up all the rivers of the besieged places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 26, E'Hast thou not heard long ago, how I have done it; and of ancient times, that I have formed it? now have I brought it to pass, that thou shouldest be to lay waste defenced cities into ruinous heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 27, E'Therefore their inhabitants were of small power, they were dismayed and confounded: they were as the grass of the field, and as the green herb, as the grass on the housetops, and as corn blasted before it be grown up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 28, E'But I know thy abode, and thy going out, and thy coming in, and thy rage against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 29, E'Because thy rage against me, and thy tumult, is come up into mine ears, therefore will I put my hook in thy nose, and my bridle in thy lips, and I will turn thee back by the way by which thou camest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 30, E'And this shall be a sign unto thee, Ye shall eat this year such as groweth of itself; and the second year that which springeth of the same: and in the third year sow ye, and reap, and plant vineyards, and eat the fruit thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 31, E'And the remnant that is escaped of the house of Judah shall again take root downward, and bear fruit upward:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 32, E'For out of Jerusalem shall go forth a remnant, and they that escape out of mount Zion: the zeal of the LORD of hosts shall do this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 33, E'Therefore thus saith the LORD concerning the king of Assyria, He shall not come into this city, nor shoot an arrow there, nor come before it with shields, nor cast a bank against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 34, E'By the way that he came, by the same shall he return, and shall not come into this city, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 35, E'For I will defend this city to save it for mine own sake, and for my servant David’s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 36, E'Then the angel of the LORD went forth, and smote in the camp of the Assyrians a hundred and fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 37, E'So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 38, E'And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword; and they escaped into the land of Armenia: and Esarhaddon his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 1, E'In those days was Hezekiah sick unto death. And Isaiah the prophet the son of Amoz came unto him, and said unto him, Thus saith the LORD, Set thine house in order: for thou shalt die, and not live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 2, E'Then Hezekiah turned his face toward the wall, and prayed unto the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 3, E'And said, Remember now, O LORD, I beseech thee, how I have walked before thee in truth and with a perfect heart, and have done that which is good in thy sight. And Hezekiah wept sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 4, E'Then came the word of the LORD to Isaiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 5, E'Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 6, E'And I will deliver thee and this city out of the hand of the king of Assyria: and I will defend this city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 7, E'And this shall be a sign unto thee from the LORD, that the LORD will do this thing that he hath spoken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 8, E'Behold, I will bring again the shadow of the degrees, which is gone down in the sun dial of Ahaz, ten degrees backward. So the sun returned ten degrees, by which degrees it was gone down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 9, E'The writing of Hezekiah king of Judah, when he had been sick, and was recovered of his sickness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 10, E'I said in the cutting off of my days, I shall go to the gates of the grave: I am deprived of the residue of my years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 11, E'I said, I shall not see the LORD, even the LORD, in the land of the living: I shall behold man no more with the inhabitants of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 12, E'Mine age is departed, and is removed from me as a shepherd’s tent: I have cut off like a weaver my life: he will cut me off with pining sickness: from day even to night wilt thou make an end of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 13, E'I reckoned till morning, that, as a lion, so will he break all my bones: from day even to night wilt thou make an end of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 14, E'Like a crane or a swallow, so did I chatter: I did mourn as a dove: mine eyes fail with looking upward: O LORD, I am oppressed; undertake for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 15, E'What shall I say? he hath both spoken unto me, and himself hath done it: I shall go softly all my years in the bitterness of my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 16, E'O LORD, by these things men live, and in all these things is the life of my spirit: so wilt thou recover me, and make me to live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 17, E'Behold, for peace I had great bitterness: but thou hast in love to my soul delivered it from the pit of corruption: for thou hast cast all my sins behind thy back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 18, E'For the grave cannot praise thee, death can not celebrate thee: they that go down into the pit cannot hope for thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 19, E'The living, the living, he shall praise thee, as I do this day: the father to the children shall make known thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 20, E'The LORD was ready to save me: therefore we will sing my songs to the stringed instruments all the days of our life in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 21, E'For Isaiah had said, Let them take a lump of figs, and lay it for a plaister upon the boil, and he shall recover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 22, E'Hezekiah also had said, What is the sign that I shall go up to the house of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 1, E'At that time Merodachbaladan, the son of Baladan, king of Babylon, sent letters and a present to Hezekiah: for he had heard that he had been sick, and was recovered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 2, E'And Hezekiah was glad of them, and shewed them the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and all the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 3, E'Then came Isaiah the prophet unto king Hezekiah, and said unto him, What said these men? and from whence came they unto thee? And Hezekiah said, They are come from a far country unto me, even from Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 4, E'Then said he, What have they seen in thine house? And Hezekiah answered, All that is in mine house have they seen: there is nothing among my treasures that I have not shewed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 5, E'Then said Isaiah to Hezekiah, Hear the word of the LORD of hosts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 6, E'Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store until this day, shall be carried to Babylon: nothing shall be left, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 7, E'And of thy sons that shall issue from thee, which thou shalt beget, shall they take away; and they shall be eunuchs in the palace of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 8, E'Then said Hezekiah to Isaiah, Good is the word of the LORD which thou hast spoken. He said moreover, For there shall be peace and truth in my days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 1, E'Comfort ye, comfort ye my people, saith your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 2, E'Speak ye comfortably to Jerusalem, and cry unto her, that her warfare is accomplished, that her iniquity is pardoned: for she hath received of the LORD’s hand double for all her sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 3, E'The voice of him that crieth in the wilderness, Prepare ye the way of the LORD, make straight in the desert a highway for our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 4, E'Every valley shall be exalted, and every mountain and hill shall be made low: and the crooked shall be made straight, and the rough places plain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 5, E'And the glory of the LORD shall be revealed, and all flesh shall see it together: for the mouth of the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 6, E'The voice said, Cry. And he said, What shall I cry? All flesh is grass, and all the goodliness thereof is as the flower of the field:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 7, E'The grass withereth, the flower fadeth: because the spirit of the LORD bloweth upon it: surely the people is grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 8, E'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 9, E'O Zion, that bringest good tidings, get thee up into the high mountain; O Jerusalem, that bringest good tidings, lift up thy voice with strength; lift it up, be not afraid; say unto the cities of Judah, Behold your God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 10, E'Behold, the Lord GOD will come with strong hand, and his arm shall rule for him: behold, his reward is with him, and his work before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 11, E'He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 12, E'Who hath measured the waters in the hollow of his hand, and meted out heaven with the span, and comprehended the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 13, E'Who hath directed the Spirit of the LORD, or being his counsellor hath taught him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 14, E'With whom took he counsel, and who instructed him, and taught him in the path of judgment, and taught him knowledge, and shewed to him the way of understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 15, E'Behold, the nations are as a drop of a bucket, and are counted as the small dust of the balance: behold, he taketh up the isles as a very little thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 16, E'And Lebanon is not sufficient to burn, nor the beasts thereof sufficient for a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 17, E'All nations before him are as nothing; and they are counted to him less than nothing, and vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 18, E'To whom then will ye liken God? or what likeness will ye compare unto him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 19, E'The workman melteth a graven image, and the goldsmith spreadeth it over with gold, and casteth silver chains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 20, E'He that is so impoverished that he hath no oblation chooseth a tree that will not rot; he seeketh unto him a cunning workman to prepare a graven image, that shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 21, E'Have ye not known? have ye not heard? hath it not been told you from the beginning? have ye not understood from the foundations of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 22, E'It is he that sitteth upon the circle of the earth, and the inhabitants thereof are as grasshoppers; that stretcheth out the heavens as a curtain, and spreadeth them out as a tent to dwell in:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 23, E'That bringeth the princes to nothing; he maketh the judges of the earth as vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 24, E'Yea, they shall not be planted; yea, they shall not be sown: yea, their stock shall not take root in the earth: and he shall also blow upon them, and they shall wither, and the whirlwind shall take them away as stubble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 25, E'To whom then will ye liken me, or shall I be equal? saith the Holy One.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 26, E'Lift up your eyes on high, and behold who hath created these things, that bringeth out their host by number: he calleth them all by names by the greatness of his might, for that he is strong in power; not one faileth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 27, E'Why sayest thou, O Jacob, and speakest, O Israel, My way is hid from the LORD, and my judgment is passed over from my God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 28, E'Hast thou not known? hast thou not heard, that the everlasting God, the LORD, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 29, E'He giveth power to the faint; and to them that have no might he increaseth strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 30, E'Even the youths shall faint and be weary, and the young men shall utterly fall:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 31, E'But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 1, E'Keep silence before me, O islands; and let the people renew their strength: let them come near; then let them speak: let us come near together to judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 2, E'Who raised up the righteous man from the east, called him to his foot, gave the nations before him, and made him rule over kings? he gave them as the dust to his sword, and as driven stubble to his bow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 3, E'He pursued them, and passed safely; even by the way that he had not gone with his feet.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 4, E'Who hath wrought and done it, calling the generations from the beginning? I the LORD, the first, and with the last; I am he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 5, E'The isles saw it, and feared; the ends of the earth were afraid, drew near, and came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 6, E'They helped every one his neighbour; and every one said to his brother, Be of good courage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 7, E'So the carpenter encouraged the goldsmith, and he that smootheth with the hammer him that smote the anvil, saying, It is ready for the sodering: and he fastened it with nails, that it should not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 8, E'But thou, Israel, art my servant, Jacob whom I have chosen, the seed of Abraham my friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 9, E'Thou whom I have taken from the ends of the earth, and called thee from the chief men thereof, and said unto thee, Thou art my servant; I have chosen thee, and not cast thee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 10, E'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 11, E'Behold, all they that were incensed against thee shall be ashamed and confounded: they shall be as nothing; and they that strive with thee shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 12, E'Thou shalt seek them, and shalt not find them, even them that contended with thee: they that war against thee shall be as nothing, and as a thing of nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 13, E'For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 14, E'Fear not, thou worm Jacob, and ye men of Israel; I will help thee, saith the LORD, and thy redeemer, the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 15, E'Behold, I will make thee a new sharp threshing instrument having teeth: thou shalt thresh the mountains, and beat them small, and shalt make the hills as chaff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 16, E'Thou shalt fan them, and the wind shall carry them away, and the whirlwind shall scatter them: and thou shalt rejoice in the LORD, and shalt glory in the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 17, E'When the poor and needy seek water, and there is none, and their tongue faileth for thirst, I the LORD will hear them, I the God of Israel will not forsake them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 18, E'I will open rivers in high places, and fountains in the midst of the valleys: I will make the wilderness a pool of water, and the dry land springs of water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 19, E'I will plant in the wilderness the cedar, the shittah tree, and the myrtle, and the oil tree; I will set in the desert the fir tree, and the pine, and the box tree together:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 20, E'That they may see, and know, and consider, and understand together, that the hand of the LORD hath done this, and the Holy One of Israel hath created it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 21, E'Produce your cause, saith the LORD; bring forth your strong reasons, saith the King of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 22, E'Let them bring them forth, and shew us what shall happen: let them shew the former things, what they be, that we may consider them, and know the latter end of them; or declare us things for to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 23, E'Shew the things that are to come hereafter, that we may know that ye are gods: yea, do good, or do evil, that we may be dismayed, and behold it together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 24, E'Behold, ye are of nothing, and your work of nought: an abomination is he that chooseth you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 25, E'I have raised up one from the north, and he shall come: from the rising of the sun shall he call upon my name: and he shall come upon princes as upon morter, and as the potter treadeth clay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 26, E'Who hath declared from the beginning, that we may know? and beforetime, that we may say, He is righteous? yea, there is none that sheweth, yea, there is none that declareth, yea, there is none that heareth your words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 27, E'The first shall say to Zion, Behold, behold them: and I will give to Jerusalem one that bringeth good tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 28, E'For I beheld, and there was no man; even among them, and there was no counsellor, that, when I asked of them, could answer a word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 29, E'Behold, they are all vanity; their works are nothing: their molten images are wind and confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 1, E'Behold my servant, whom I uphold; mine elect, in whom my soul delighteth; I have put my spirit upon him: he shall bring forth judgment to the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 2, E'He shall not cry, nor lift up, nor cause his voice to be heard in the street.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 3, E'A bruised reed shall he not break, and the smoking flax shall he not quench: he shall bring forth judgment unto truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 4, E'He shall not fail nor be discouraged, till he have set judgment in the earth: and the isles shall wait for his law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 5, E'Thus saith God the LORD, he that created the heavens, and stretched them out; he that spread forth the earth, and that which cometh out of it; he that giveth breath unto the people upon it, and spirit to them that walk therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 6, E'I the LORD have called thee in righteousness, and will hold thine hand, and will keep thee, and give thee for a covenant of the people, for a light of the Gentiles;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 7, E'To open the blind eyes, to bring out the prisoners from the prison, and them that sit in darkness out of the prison house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 8, E'I am the LORD: that is my name: and my glory will I not give to another, neither my praise to graven images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 9, E'Behold, the former things are come to pass, and new things do I declare: before they spring forth I tell you of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 10, E'Sing unto the LORD a new song, and his praise from the end of the earth, ye that go down to the sea, and all that is therein; the isles, and the inhabitants thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 11, E'Let the wilderness and the cities thereof lift up their voice, the villages that Kedar doth inhabit: let the inhabitants of the rock sing, let them shout from the top of the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 12, E'Let them give glory unto the LORD, and declare his praise in the islands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 13, E'The LORD shall go forth as a mighty man, he shall stir up jealousy like a man of war: he shall cry, yea, roar; he shall prevail against his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 14, E'I have long time holden my peace; I have been still, and refrained myself: now will I cry like a travailing woman; I will destroy and devour at once.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 15, E'I will make waste mountains and hills, and dry up all their herbs; and I will make the rivers islands, and I will dry up the pools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 16, E'And I will bring the blind by a way that they knew not; I will lead them in paths that they have not known: I will make darkness light before them, and crooked things straight. These things will I do unto them, and not forsake them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 17, E'They shall be turned back, they shall be greatly ashamed, that trust in graven images, that say to the molten images, Ye are our gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 18, E'Hear, ye deaf; and look, ye blind, that ye may see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 19, E'Who is blind, but my servant? or deaf, as my messenger that I sent? who is blind as he that is perfect, and blind as the LORD’s servant?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 20, E'Seeing many things, but thou observest not; opening the ears, but he heareth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 21, E'The LORD is well pleased for his righteousness’ sake; he will magnify the law, and make it honourable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 22, E'But this is a people robbed and spoiled; they are all of them snared in holes, and they are hid in prison houses: they are for a prey, and none delivereth; for a spoil, and none saith, Restore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 23, E'Who among you will give ear to this? who will hearken and hear for the time to come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 24, E'Who gave Jacob for a spoil, and Israel to the robbers? did not the LORD, he against whom we have sinned? for they would not walk in his ways, neither were they obedient unto his law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 25, E'Therefore he hath poured upon him the fury of his anger, and the strength of battle: and it hath set him on fire round about, yet he knew not; and it burned him, yet he laid it not to heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 1, E'But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 2, E'When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 3, E'For I am the LORD thy God, the Holy One of Israel, thy Saviour: I gave Egypt for thy ransom, Ethiopia and Seba for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 4, E'Since thou wast precious in my sight, thou hast been honourable, and I have loved thee: therefore will I give men for thee, and people for thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 5, E'Fear not: for I am with thee: I will bring thy seed from the east, and gather thee from the west;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 6, E'I will say to the north, Give up; and to the south, Keep not back: bring my sons from far, and my daughters from the ends of the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 7, E'Even every one that is called by my name: for I have created him for my glory, I have formed him; yea, I have made him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 8, E'Bring forth the blind people that have eyes, and the deaf that have ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 9, E'Let all the nations be gathered together, and let the people be assembled: who among them can declare this, and shew us former things? let them bring forth their witnesses, that they may be justified: or let them hear, and say, It is truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 10, E'Ye are my witnesses, saith the LORD, and my servant whom I have chosen: that ye may know and believe me, and understand that I am he: before me there was no God formed, neither shall there be after me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 11, E'I, even I, am the LORD; and beside me there is no saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 12, E'I have declared, and have saved, and I have shewed, when there was no strange god among you: therefore ye are my witnesses, saith the LORD, that I am God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 13, E'Yea, before the day was I am he; and there is none that can deliver out of my hand: I will work, and who shall let it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 14, E'Thus saith the LORD, your redeemer, the Holy One of Israel; For your sake I have sent to Babylon, and have brought down all their nobles, and the Chaldeans, whose cry is in the ships.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 15, E'I am the LORD, your Holy One, the creator of Israel, your King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 16, E'Thus saith the LORD, which maketh a way in the sea, and a path in the mighty waters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 17, E'Which bringeth forth the chariot and horse, the army and the power; they shall lie down together, they shall not rise: they are extinct, they are quenched as tow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 18, E'Remember ye not the former things, neither consider the things of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 19, E'Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 20, E'The beast of the field shall honour me, the dragons and the owls: because I give waters in the wilderness, and rivers in the desert, to give drink to my people, my chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 21, E'This people have I formed for myself; they shall shew forth my praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 22, E'But thou hast not called upon me, O Jacob; but thou hast been weary of me, O Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 23, E'Thou hast not brought me the small cattle of thy burnt offerings; neither hast thou honoured me with thy sacrifices. I have not caused thee to serve with an offering, nor wearied thee with incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 24, E'Thou hast bought me no sweet cane with money, neither hast thou filled me with the fat of thy sacrifices: but thou hast made me to serve with thy sins, thou hast wearied me with thine iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 25, E'I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 26, E'Put me in remembrance: let us plead together: declare thou, that thou mayest be justified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 27, E'Thy first father hath sinned, and thy teachers have transgressed against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 28, E'Therefore I have profaned the princes of the sanctuary, and have given Jacob to the curse, and Israel to reproaches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 1, E'Yet now hear, O Jacob my servant; and Israel, whom I have chosen:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 2, E'Thus saith the LORD that made thee, and formed thee from the womb, which will help thee; Fear not, O Jacob, my servant; and thou, Jesurun, whom I have chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 3, E'For I will pour water upon him that is thirsty, and floods upon the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 4, E'And they shall spring up as among the grass, as willows by the water courses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 5, E'One shall say, I am the LORD’s; and another shall call himself by the name of Jacob; and another shall subscribe with his hand unto the LORD, and surname himself by the name of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 6, E'Thus saith the LORD the King of Israel, and his redeemer the LORD of hosts; I am the first, and I am the last; and beside me there is no God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 7, E'And who, as I, shall call, and shall declare it, and set it in order for me, since I appointed the ancient people? and the things that are coming, and shall come, let them shew unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 8, E'Fear ye not, neither be afraid: have not I told thee from that time, and have declared it? ye are even my witnesses. Is there a God beside me? yea, there is no God; I know not any.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 9, E'They that make a graven image are all of them vanity; and their delectable things shall not profit; and they are their own witnesses; they see not, nor know; that they may be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 10, E'Who hath formed a god, or molten a graven image that is profitable for nothing?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 11, E'Behold, all his fellows shall be ashamed: and the workmen, they are of men: let them all be gathered together, let them stand up; yet they shall fear, and they shall be ashamed together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 12, E'The smith with the tongs both worketh in the coals, and fashioneth it with hammers, and worketh it with the strength of his arms: yea, he is hungry, and his strength faileth: he drinketh no water, and is faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 13, E'The carpenter stretcheth out his rule; he marketh it out with a line; he fitteth it with planes, and he marketh it out with the compass, and maketh it after the figure of a man, according to the beauty of a man; that it may remain in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 14, E'He heweth him down cedars, and taketh the cypress and the oak, which he strengtheneth for himself among the trees of the forest: he planteth an ash, and the rain doth nourish it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 15, E'Then shall it be for a man to burn: for he will take thereof, and warm himself; yea, he kindleth it, and baketh bread; yea, he maketh a god, and worshippeth it; he maketh it a graven image, and falleth down thereto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 16, E'He burneth part thereof in the fire; with part thereof he eateth flesh; he roasteth roast, and is satisfied: yea, he warmeth himself, and saith, Aha, I am warm, I have seen the fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 17, E'And the residue thereof he maketh a god, even his graven image: he falleth down unto it, and worshippeth it, and prayeth unto it, and saith, Deliver me; for thou art my god.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 18, E'They have not known nor understood: for he hath shut their eyes, that they cannot see; and their hearts, that they cannot understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 19, E'And none considereth in his heart, neither is there knowledge nor understanding to say, I have burned part of it in the fire; yea, also I have baked bread upon the coals thereof; I have roasted flesh, and eaten it: and shall I make the residue thereof an abomination? shall I fall down to the stock of a tree?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 20, E'He feedeth on ashes: a deceived heart hath turned him aside, that he cannot deliver his soul, nor say, Is there not a lie in my right hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 21, E'Remember these, O Jacob and Israel; for thou art my servant: I have formed thee; thou art my servant: O Israel, thou shalt not be forgotten of me.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 22, E'I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 23, E'Sing, O ye heavens; for the LORD hath done it: shout, ye lower parts of the earth: break forth into singing, ye mountains, O forest, and every tree therein: for the LORD hath redeemed Jacob, and glorified himself in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 24, E'Thus saith the LORD, thy redeemer, and he that formed thee from the womb, I am the LORD that maketh all things; that stretcheth forth the heavens alone; that spreadeth abroad the earth by myself;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 25, E'That frustrateth the tokens of the liars, and maketh diviners mad; that turneth wise men backward, and maketh their knowledge foolish;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 26, E'That confirmeth the word of his servant, and performeth the counsel of his messengers; that saith to Jerusalem, Thou shalt be inhabited; and to the cities of Judah, Ye shall be built, and I will raise up the decayed places thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 27, E'That saith to the deep, Be dry, and I will dry up thy rivers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 28, E'That saith of Cyrus, He is my shepherd, and shall perform all my pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 1, E'Thus saith the LORD to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 2, E'I will go before thee, and make the crooked places straight: I will break in pieces the gates of brass, and cut in sunder the bars of iron:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 3, E'And I will give thee the treasures of darkness, and hidden riches of secret places, that thou mayest know that I, the LORD, which call thee by thy name, am the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 4, E'For Jacob my servant’s sake, and Israel mine elect, I have even called thee by thy name: I have surnamed thee, though thou hast not known me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 5, E'I am the LORD, and there is none else, there is no God beside me: I girded thee, though thou hast not known me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 6, E'That they may know from the rising of the sun, and from the west, that there is none beside me. I am the LORD, and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 7, E'I form the light, and create darkness: I make peace, and create evil: I the LORD do all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 8, E'Drop down, ye heavens, from above, and let the skies pour down righteousness: let the earth open, and let them bring forth salvation, and let righteousness spring up together; I the LORD have created it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 9, E'Woe unto him that striveth with his Maker! Let the potsherd strive with the potsherds of the earth. Shall the clay say to him that fashioneth it, What makest thou? or thy work, He hath no hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 10, E'Woe unto him that saith unto his father, What begettest thou? or to the woman, What hast thou brought forth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 11, E'Thus saith the LORD, the Holy One of Israel, and his Maker, Ask me of things to come concerning my sons, and concerning the work of my hands command ye me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 12, E'I have made the earth, and created man upon it: I, even my hands, have stretched out the heavens, and all their host have I commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 13, E'I have raised him up in righteousness, and I will direct all his ways: he shall build my city, and he shall let go my captives, not for price nor reward, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 14, E'Thus saith the LORD, The labour of Egypt, and merchandise of Ethiopia and of the Sabeans, men of stature, shall come over unto thee, and they shall be thine: they shall come after thee; in chains they shall come over, and they shall fall down unto thee, they shall make supplication unto thee, saying, Surely God is in thee; and there is none else, there is no God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 15, E'Verily thou art a God that hidest thyself, O God of Israel, the Saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 16, E'They shall be ashamed, and also confounded, all of them: they shall go to confusion together that are makers of idols.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 17, E'But Israel shall be saved in the LORD with an everlasting salvation: ye shall not be ashamed nor confounded world without end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 18, E'For thus saith the LORD that created the heavens; God himself that formed the earth and made it; he hath established it, he created it not in vain, he formed it to be inhabited: I am the LORD; and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 19, E'I have not spoken in secret, in a dark place of the earth: I said not unto the seed of Jacob, Seek ye me in vain: I the LORD speak righteousness, I declare things that are right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 20, E'Assemble yourselves and come; draw near together, ye that are escaped of the nations: they have no knowledge that set up the wood of their graven image, and pray unto a god that cannot save.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 21, E'Tell ye, and bring them near; yea, let them take counsel together: who hath declared this from ancient time? who hath told it from that time? have not I the LORD? and there is no God else beside me; a just God and a Saviour; there is none beside me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 22, E'Look unto me, and be ye saved, all the ends of the earth: for I am God, and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 23, E'I have sworn by myself, the word is gone out of my mouth in righteousness, and shall not return, That unto me every knee shall bow, every tongue shall swear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 24, E'Surely, shall one say, in the LORD have I righteousness and strength: even to him shall men come; and all that are incensed against him shall be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 25, E'In the LORD shall all the seed of Israel be justified, and shall glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 1, E'Bel boweth down, Nebo stoopeth, their idols were upon the beasts, and upon the cattle: your carriages were heavy loaden; they are a burden to the weary beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 2, E'They stoop, they bow down together; they could not deliver the burden, but themselves are gone into captivity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 3, E'Hearken unto me, O house of Jacob, and all the remnant of the house of Israel, which are borne by me from the belly, which are carried from the womb:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 4, E'And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 5, E'To whom will ye liken me, and make me equal, and compare me, that we may be like?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 6, E'They lavish gold out of the bag, and weigh silver in the balance, and hire a goldsmith; and he maketh it a god: they fall down, yea, they worship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 7, E'They bear him upon the shoulder, they carry him, and set him in his place, and he standeth; from his place shall he not remove: yea, one shall cry unto him, yet can he not answer, nor save him out of his trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 8, E'Remember this, and shew yourselves men: bring it again to mind, O ye transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 9, E'Remember the former things of old: for I am God, and there is none else; I am God, and there is none like me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 10, E'Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 11, E'Calling a ravenous bird from the east, the man that executeth my counsel from a far country: yea, I have spoken it, I will also bring it to pass; I have purposed it, I will also do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 12, E'Hearken unto me, ye stouthearted, that are far from righteousness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 13, E'I bring near my righteousness; it shall not be far off, and my salvation shall not tarry: and I will place salvation in Zion for Israel my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 1, E'Come down, and sit in the dust, O virgin daughter of Babylon, sit on the ground: there is no throne, O daughter of the Chaldeans: for thou shalt no more be called tender and delicate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 2, E'Take the millstones, and grind meal: uncover thy locks, make bare the leg, uncover the thigh, pass over the rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 3, E'Thy nakedness shall be uncovered, yea, thy shame shall be seen: I will take vengeance, and I will not meet thee as a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 4, E'As for our redeemer, the LORD of hosts is his name, the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 5, E'Sit thou silent, and get thee into darkness, O daughter of the Chaldeans: for thou shalt no more be called, The lady of kingdoms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 6, E'I was wroth with my people, I have polluted mine inheritance, and given them into thine hand: thou didst shew them no mercy; upon the ancient hast thou very heavily laid thy yoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 7, E'And thou saidst, I shall be a lady for ever: so that thou didst not lay these things to thy heart, neither didst remember the latter end of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 8, E'Therefore hear now this, thou that art given to pleasures, that dwellest carelessly, that sayest in thine heart, I am, and none else beside me; I shall not sit as a widow, neither shall I know the loss of children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 9, E'But these two things shall come to thee in a moment in one day, the loss of children, and widowhood: they shall come upon thee in their perfection for the multitude of thy sorceries, and for the great abundance of thine enchantments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 10, E'For thou hast trusted in thy wickedness: thou hast said, None seeth me. Thy wisdom and thy knowledge, it hath perverted thee; and thou hast said in thine heart, I am, and none else beside me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 11, E'Therefore shall evil come upon thee; thou shalt not know from whence it riseth: and mischief shall fall upon thee; thou shalt not be able to put it off: and desolation shall come upon thee suddenly, which thou shalt not know.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 12, E'Stand now with thine enchantments, and with the multitude of thy sorceries, wherein thou hast laboured from thy youth; if so be thou shalt be able to profit, if so be thou mayest prevail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 13, E'Thou art wearied in the multitude of thy counsels. Let now the astrologers, the stargazers, the monthly prognosticators, stand up, and save thee from these things that shall come upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 14, E'Behold, they shall be as stubble; the fire shall burn them; they shall not deliver themselves from the power of the flame: there shall not be a coal to warm at, nor fire to sit before it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 15, E'Thus shall they be unto thee with whom thou hast laboured, even thy merchants, from thy youth: they shall wander every one to his quarter; none shall save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 1, E'Hear ye this, O house of Jacob, which are called by the name of Israel, and are come forth out of the waters of Judah, which swear by the name of the LORD, and make mention of the God of Israel, but not in truth, nor in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 2, E'For they call themselves of the holy city, and stay themselves upon the God of Israel; The LORD of hosts is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 3, E'I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 4, E'Because I knew that thou art obstinate, and thy neck is an iron sinew, and thy brow brass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 5, E'I have even from the beginning declared it to thee; before it came to pass I shewed it thee: lest thou shouldest say, Mine idol hath done them, and my graven image, and my molten image, hath commanded them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 6, E'Thou hast heard, see all this; and will not ye declare it? I have shewed thee new things from this time, even hidden things, and thou didst not know them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 7, E'They are created now, and not from the beginning; even before the day when thou heardest them not; lest thou shouldest say, Behold, I knew them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 8, E'Yea, thou heardest not; yea, thou knewest not; yea, from that time that thine ear was not opened: for I knew that thou wouldest deal very treacherously, and wast called a transgressor from the womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 9, E'For my name’s sake will I defer mine anger, and for my praise will I refrain for thee, that I cut thee not off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 10, E'Behold, I have refined thee, but not with silver; I have chosen thee in the furnace of affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 11, E'For mine own sake, even for mine own sake, will I do it: for how should my name be polluted? and I will not give my glory unto another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 12, E'Hearken unto me, O Jacob and Israel, my called; I am he; I am the first, I also am the last.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 13, E'Mine hand also hath laid the foundation of the earth, and my right hand hath spanned the heavens: when I call unto them, they stand up together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 14, E'All ye, assemble yourselves, and hear; which among them hath declared these things? The LORD hath loved him: he will do his pleasure on Babylon, and his arm shall be on the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 15, E'I, even I, have spoken; yea, I have called him: I have brought him, and he shall make his way prosperous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 16, E'Come ye near unto me, hear ye this; I have not spoken in secret from the beginning; from the time that it was, there am I: and now the Lord GOD, and his Spirit, hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 17, E'Thus saith the LORD, thy Redeemer, the Holy One of Israel; I am the LORD thy God which teacheth thee to profit, which leadeth thee by the way that thou shouldest go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 18, E'O that thou hadst hearkened to my commandments! then had thy peace been as a river, and thy righteousness as the waves of the sea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 19, E'Thy seed also had been as the sand, and the offspring of thy bowels like the gravel thereof; his name should not have been cut off nor destroyed from before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 20, E'Go ye forth of Babylon, flee ye from the Chaldeans, with a voice of singing declare ye, tell this, utter it even to the end of the earth; say ye, The LORD hath redeemed his servant Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 21, E'And they thirsted not when he led them through the deserts: he caused the waters to flow out of the rock for them: he clave the rock also, and the waters gushed out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 22, E'There is no peace, saith the LORD, unto the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 1, E'Listen, O isles, unto me; and hearken, ye people, from far; The LORD hath called me from the womb; from the bowels of my mother hath he made mention of my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 2, E'And he hath made my mouth like a sharp sword; in the shadow of his hand hath he hid me, and made me a polished shaft; in his quiver hath he hid me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 3, E'And said unto me, Thou art my servant, O Israel, in whom I will be glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 4, E'Then I said, I have laboured in vain, I have spent my strength for nought, and in vain: yet surely my judgment is with the LORD, and my work with my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 5, E'And now, saith the LORD that formed me from the womb to be his servant, to bring Jacob again to him, Though Israel be not gathered, yet shall I be glorious in the eyes of the LORD, and my God shall be my strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 6, E'And he said, It is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Israel: I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 7, E'Thus saith the LORD, the Redeemer of Israel, and his Holy One, to him whom man despiseth, to him whom the nation abhorreth, to a servant of rulers, Kings shall see and arise, princes also shall worship, because of the LORD that is faithful, and the Holy One of Israel, and he shall choose thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 8, E'Thus saith the LORD, In an acceptable time have I heard thee, and in a day of salvation have I helped thee: and I will preserve thee, and give thee for a covenant of the people, to establish the earth, to cause to inherit the desolate heritages;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 9, E'That thou mayest say to the prisoners, Go forth; to them that are in darkness, Shew yourselves. They shall feed in the ways, and their pastures shall be in all high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 10, E'They shall not hunger nor thirst; neither shall the heat nor sun smite them: for he that hath mercy on them shall lead them, even by the springs of water shall he guide them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 11, E'And I will make all my mountains a way, and my highways shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 12, E'Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 13, E'Sing, O heavens; and be joyful, O earth; and break forth into singing, O mountains: for the LORD hath comforted his people, and will have mercy upon his afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 14, E'But Zion said, The LORD hath forsaken me, and my Lord hath forgotten me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 15, E'Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 16, E'Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 17, E'Thy children shall make haste; thy destroyers and they that made thee waste shall go forth of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 18, E'Lift up thine eyes round about, and behold: all these gather themselves together, and come to thee. As I live, saith the LORD, thou shalt surely clothe thee with them all, as with an ornament, and bind them on thee, as a bride doeth.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

